window.SHAKESPEARE_ENGLISH["hamlet"] = {"id":"hamlet","title":"Hamlet","kind":"play","source":"MIT Shakespeare (Complete Moby Shakespeare)","sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","sourceRevision":"6b82db852c7322dd33e95db347f0ddfc812c6409","sections":[{"id":"1.1","label":"Act 1 · SCENE I. Elsinore. A platform before the castle.","act":1,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"FRANCISCO at his post. Enter to him BERNARDO","id":"hamlet:1.1:1"},{"kind":"speech","text":"Who's there?","sourceLine":"1.1.1","speaker":"BERNARDO","id":"hamlet:1.1:2"},{"kind":"speech","text":"Nay, answer me: stand, and unfold yourself.","sourceLine":"1.1.2","speaker":"FRANCISCO","id":"hamlet:1.1:3"},{"kind":"speech","text":"Long live the king!","sourceLine":"1.1.3","speaker":"BERNARDO","id":"hamlet:1.1:4"},{"kind":"speech","text":"Bernardo?","sourceLine":"1.1.4","speaker":"FRANCISCO","id":"hamlet:1.1:5"},{"kind":"speech","text":"He.","sourceLine":"1.1.5","speaker":"BERNARDO","id":"hamlet:1.1:6"},{"kind":"speech","text":"You come most carefully upon your hour.","sourceLine":"1.1.6","speaker":"FRANCISCO","id":"hamlet:1.1:7"},{"kind":"speech","text":"'Tis now struck twelve; get thee to bed, Francisco.","sourceLine":"1.1.7","speaker":"BERNARDO","id":"hamlet:1.1:8"},{"kind":"speech","text":"For this relief much thanks: 'tis bitter cold,\nAnd I am sick at heart.","sourceLine":"1.1.8","speaker":"FRANCISCO","id":"hamlet:1.1:9"},{"kind":"speech","text":"Have you had quiet guard?","sourceLine":"1.1.10","speaker":"BERNARDO","id":"hamlet:1.1:10"},{"kind":"speech","text":"Not a mouse stirring.","sourceLine":"1.1.11","speaker":"FRANCISCO","id":"hamlet:1.1:11"},{"kind":"speech","text":"Well, good night.\nIf you do meet Horatio and Marcellus,\nThe rivals of my watch, bid them make haste.","sourceLine":"1.1.12","speaker":"BERNARDO","id":"hamlet:1.1:12"},{"kind":"speech","text":"I think I hear them. Stand, ho! Who's there?","sourceLine":"1.1.15","speaker":"FRANCISCO","id":"hamlet:1.1:13"},{"kind":"stage","text":"Enter HORATIO and MARCELLUS","id":"hamlet:1.1:14"},{"kind":"speech","text":"Friends to this ground.","sourceLine":"1.1.16","speaker":"HORATIO","id":"hamlet:1.1:15"},{"kind":"speech","text":"And liegemen to the Dane.","sourceLine":"1.1.17","speaker":"MARCELLUS","id":"hamlet:1.1:16"},{"kind":"speech","text":"Give you good night.","sourceLine":"1.1.18","speaker":"FRANCISCO","id":"hamlet:1.1:17"},{"kind":"speech","text":"O, farewell, honest soldier:\nWho hath relieved you?","sourceLine":"1.1.19","speaker":"MARCELLUS","id":"hamlet:1.1:18"},{"kind":"speech","text":"Bernardo has my place.\nGive you good night.","sourceLine":"1.1.21","speaker":"FRANCISCO","id":"hamlet:1.1:19"},{"kind":"stage","text":"Exit","id":"hamlet:1.1:20"},{"kind":"speech","text":"Holla! Bernardo!","sourceLine":"1.1.23","speaker":"MARCELLUS","id":"hamlet:1.1:21"},{"kind":"speech","text":"Say,\nWhat, is Horatio there?","sourceLine":"1.1.24","speaker":"BERNARDO","id":"hamlet:1.1:22"},{"kind":"speech","text":"A piece of him.","sourceLine":"1.1.26","speaker":"HORATIO","id":"hamlet:1.1:23"},{"kind":"speech","text":"Welcome, Horatio: welcome, good Marcellus.","sourceLine":"1.1.27","speaker":"BERNARDO","id":"hamlet:1.1:24"},{"kind":"speech","text":"What, has this thing appear'd again to-night?","sourceLine":"1.1.28","speaker":"MARCELLUS","id":"hamlet:1.1:25"},{"kind":"speech","text":"I have seen nothing.","sourceLine":"1.1.29","speaker":"BERNARDO","id":"hamlet:1.1:26"},{"kind":"speech","text":"Horatio says 'tis but our fantasy,\nAnd will not let belief take hold of him\nTouching this dreaded sight, twice seen of us:\nTherefore I have entreated him along\nWith us to watch the minutes of this night;\nThat if again this apparition come,\nHe may approve our eyes and speak to it.","sourceLine":"1.1.30","speaker":"MARCELLUS","id":"hamlet:1.1:27"},{"kind":"speech","text":"Tush, tush, 'twill not appear.","sourceLine":"1.1.37","speaker":"HORATIO","id":"hamlet:1.1:28"},{"kind":"speech","text":"Sit down awhile;\nAnd let us once again assail your ears,\nThat are so fortified against our story\nWhat we have two nights seen.","sourceLine":"1.1.38","speaker":"BERNARDO","id":"hamlet:1.1:29"},{"kind":"speech","text":"Well, sit we down,\nAnd let us hear Bernardo speak of this.","sourceLine":"1.1.42","speaker":"HORATIO","id":"hamlet:1.1:30"},{"kind":"speech","text":"Last night of all,\nWhen yond same star that's westward from the pole\nHad made his course to illume that part of heaven\nWhere now it burns, Marcellus and myself,\nThe bell then beating one,--","sourceLine":"1.1.44","speaker":"BERNARDO","id":"hamlet:1.1:31"},{"kind":"stage","text":"Enter Ghost","id":"hamlet:1.1:32"},{"kind":"speech","text":"Peace, break thee off; look, where it comes again!","sourceLine":"1.1.49","speaker":"MARCELLUS","id":"hamlet:1.1:33"},{"kind":"speech","text":"In the same figure, like the king that's dead.","sourceLine":"1.1.50","speaker":"BERNARDO","id":"hamlet:1.1:34"},{"kind":"speech","text":"Thou art a scholar; speak to it, Horatio.","sourceLine":"1.1.51","speaker":"MARCELLUS","id":"hamlet:1.1:35"},{"kind":"speech","text":"Looks it not like the king? mark it, Horatio.","sourceLine":"1.1.52","speaker":"BERNARDO","id":"hamlet:1.1:36"},{"kind":"speech","text":"Most like: it harrows me with fear and wonder.","sourceLine":"1.1.53","speaker":"HORATIO","id":"hamlet:1.1:37"},{"kind":"speech","text":"It would be spoke to.","sourceLine":"1.1.54","speaker":"BERNARDO","id":"hamlet:1.1:38"},{"kind":"speech","text":"Question it, Horatio.","sourceLine":"1.1.55","speaker":"MARCELLUS","id":"hamlet:1.1:39"},{"kind":"speech","text":"What art thou that usurp'st this time of night,\nTogether with that fair and warlike form\nIn which the majesty of buried Denmark\nDid sometimes march? by heaven I charge thee, speak!","sourceLine":"1.1.56","speaker":"HORATIO","id":"hamlet:1.1:40"},{"kind":"speech","text":"It is offended.","sourceLine":"1.1.60","speaker":"MARCELLUS","id":"hamlet:1.1:41"},{"kind":"speech","text":"See, it stalks away!","sourceLine":"1.1.61","speaker":"BERNARDO","id":"hamlet:1.1:42"},{"kind":"speech","text":"Stay! speak, speak! I charge thee, speak!","sourceLine":"1.1.62","speaker":"HORATIO","id":"hamlet:1.1:43"},{"kind":"stage","text":"Exit Ghost","id":"hamlet:1.1:44"},{"kind":"speech","text":"'Tis gone, and will not answer.","sourceLine":"1.1.63","speaker":"MARCELLUS","id":"hamlet:1.1:45"},{"kind":"speech","text":"How now, Horatio! you tremble and look pale:\nIs not this something more than fantasy?\nWhat think you on't?","sourceLine":"1.1.64","speaker":"BERNARDO","id":"hamlet:1.1:46"},{"kind":"speech","text":"Before my God, I might not this believe\nWithout the sensible and true avouch\nOf mine own eyes.","sourceLine":"1.1.67","speaker":"HORATIO","id":"hamlet:1.1:47"},{"kind":"speech","text":"Is it not like the king?","sourceLine":"1.1.70","speaker":"MARCELLUS","id":"hamlet:1.1:48"},{"kind":"speech","text":"As thou art to thyself:\nSuch was the very armour he had on\nWhen he the ambitious Norway combated;\nSo frown'd he once, when, in an angry parle,\nHe smote the sledded Polacks on the ice.\n'Tis strange.","sourceLine":"1.1.71","speaker":"HORATIO","id":"hamlet:1.1:49"},{"kind":"speech","text":"Thus twice before, and jump at this dead hour,\nWith martial stalk hath he gone by our watch.","sourceLine":"1.1.77","speaker":"MARCELLUS","id":"hamlet:1.1:50"},{"kind":"speech","text":"In what particular thought to work I know not;\nBut in the gross and scope of my opinion,\nThis bodes some strange eruption to our state.","sourceLine":"1.1.79","speaker":"HORATIO","id":"hamlet:1.1:51"},{"kind":"speech","text":"Good now, sit down, and tell me, he that knows,\nWhy this same strict and most observant watch\nSo nightly toils the subject of the land,\nAnd why such daily cast of brazen cannon,\nAnd foreign mart for implements of war;\nWhy such impress of shipwrights, whose sore task\nDoes not divide the Sunday from the week;\nWhat might be toward, that this sweaty haste\nDoth make the night joint-labourer with the day:\nWho is't that can inform me?","sourceLine":"1.1.82","speaker":"MARCELLUS","id":"hamlet:1.1:52"},{"kind":"speech","text":"That can I;\nAt least, the whisper goes so. Our last king,\nWhose image even but now appear'd to us,\nWas, as you know, by Fortinbras of Norway,\nThereto prick'd on by a most emulate pride,\nDared to the combat; in which our valiant Hamlet--\nFor so this side of our known world esteem'd him--\nDid slay this Fortinbras; who by a seal'd compact,\nWell ratified by law and heraldry,\nDid forfeit, with his life, all those his lands\nWhich he stood seized of, to the conqueror:\nAgainst the which, a moiety competent\nWas gaged by our king; which had return'd\nTo the inheritance of Fortinbras,\nHad he been vanquisher; as, by the same covenant,\nAnd carriage of the article design'd,\nHis fell to Hamlet. Now, sir, young Fortinbras,\nOf unimproved mettle hot and full,\nHath in the skirts of Norway here and there\nShark'd up a list of lawless resolutes,\nFor food and diet, to some enterprise\nThat hath a stomach in't; which is no other--\nAs it doth well appear unto our state--\nBut to recover of us, by strong hand\nAnd terms compulsatory, those foresaid lands\nSo by his father lost: and this, I take it,\nIs the main motive of our preparations,\nThe source of this our watch and the chief head\nOf this post-haste and romage in the land.","sourceLine":"1.1.92","speaker":"HORATIO","id":"hamlet:1.1:53"},{"kind":"speech","text":"I think it be no other but e'en so:\nWell may it sort that this portentous figure\nComes armed through our watch; so like the king\nThat was and is the question of these wars.","sourceLine":"1.1.121","speaker":"BERNARDO","id":"hamlet:1.1:54"},{"kind":"speech","text":"A mote it is to trouble the mind's eye.\nIn the most high and palmy state of Rome,\nA little ere the mightiest Julius fell,\nThe graves stood tenantless and the sheeted dead\nDid squeak and gibber in the Roman streets:\nAs stars with trains of fire and dews of blood,\nDisasters in the sun; and the moist star\nUpon whose influence Neptune's empire stands\nWas sick almost to doomsday with eclipse:\nAnd even the like precurse of fierce events,\nAs harbingers preceding still the fates\nAnd prologue to the omen coming on,\nHave heaven and earth together demonstrated\nUnto our climatures and countrymen.--\nBut soft, behold! lo, where it comes again!","sourceLine":"1.1.125","speaker":"HORATIO","id":"hamlet:1.1:55"},{"kind":"stage","text":"Re-enter Ghost","id":"hamlet:1.1:56"},{"kind":"speech","text":"I'll cross it, though it blast me. Stay, illusion!\nIf thou hast any sound, or use of voice,\nSpeak to me:\nIf there be any good thing to be done,\nThat may to thee do ease and grace to me,\nSpeak to me:","sourceLine":"1.1.140","speaker":"HORATIO","id":"hamlet:1.1:57"},{"kind":"stage","text":"Cock crows","id":"hamlet:1.1:58"},{"kind":"speech","text":"If thou art privy to thy country's fate,\nWhich, happily, foreknowing may avoid, O, speak!\nOr if thou hast uphoarded in thy life\nExtorted treasure in the womb of earth,\nFor which, they say, you spirits oft walk in death,\nSpeak of it: stay, and speak! Stop it, Marcellus.","sourceLine":"1.1.146","speaker":"HORATIO","id":"hamlet:1.1:59"},{"kind":"speech","text":"Shall I strike at it with my partisan?","sourceLine":"1.1.152","speaker":"MARCELLUS","id":"hamlet:1.1:60"},{"kind":"speech","text":"Do, if it will not stand.","sourceLine":"1.1.153","speaker":"HORATIO","id":"hamlet:1.1:61"},{"kind":"speech","text":"'Tis here!","sourceLine":"1.1.154","speaker":"BERNARDO","id":"hamlet:1.1:62"},{"kind":"speech","text":"'Tis here!","sourceLine":"1.1.155","speaker":"HORATIO","id":"hamlet:1.1:63"},{"kind":"speech","text":"'Tis gone!","sourceLine":"1.1.156","speaker":"MARCELLUS","id":"hamlet:1.1:64"},{"kind":"stage","text":"Exit Ghost","id":"hamlet:1.1:65"},{"kind":"speech","text":"We do it wrong, being so majestical,\nTo offer it the show of violence;\nFor it is, as the air, invulnerable,\nAnd our vain blows malicious mockery.","sourceLine":"1.1.157","speaker":"MARCELLUS","id":"hamlet:1.1:66"},{"kind":"speech","text":"It was about to speak, when the cock crew.","sourceLine":"1.1.161","speaker":"BERNARDO","id":"hamlet:1.1:67"},{"kind":"speech","text":"And then it started like a guilty thing\nUpon a fearful summons. I have heard,\nThe cock, that is the trumpet to the morn,\nDoth with his lofty and shrill-sounding throat\nAwake the god of day; and, at his warning,\nWhether in sea or fire, in earth or air,\nThe extravagant and erring spirit hies\nTo his confine: and of the truth herein\nThis present object made probation.","sourceLine":"1.1.162","speaker":"HORATIO","id":"hamlet:1.1:68"},{"kind":"speech","text":"It faded on the crowing of the cock.\nSome say that ever 'gainst that season comes\nWherein our Saviour's birth is celebrated,\nThe bird of dawning singeth all night long:\nAnd then, they say, no spirit dares stir abroad;\nThe nights are wholesome; then no planets strike,\nNo fairy takes, nor witch hath power to charm,\nSo hallow'd and so gracious is the time.","sourceLine":"1.1.171","speaker":"MARCELLUS","id":"hamlet:1.1:69"},{"kind":"speech","text":"So have I heard and do in part believe it.\nBut, look, the morn, in russet mantle clad,\nWalks o'er the dew of yon high eastward hill:\nBreak we our watch up; and by my advice,\nLet us impart what we have seen to-night\nUnto young Hamlet; for, upon my life,\nThis spirit, dumb to us, will speak to him.\nDo you consent we shall acquaint him with it,\nAs needful in our loves, fitting our duty?","sourceLine":"1.1.179","speaker":"HORATIO","id":"hamlet:1.1:70"},{"kind":"speech","text":"Let's do't, I pray; and I this morning know\nWhere we shall find him most conveniently.","sourceLine":"1.1.188","speaker":"MARCELLUS","id":"hamlet:1.1:71"},{"kind":"stage","text":"Exeunt","id":"hamlet:1.1:72"}],"scene":1},{"id":"1.2","label":"Act 1 · SCENE II. A room of state in the castle.","act":1,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, QUEEN GERTRUDE, HAMLET, POLONIUS, LAERTES, VOLTIMAND, CORNELIUS, Lords, and Attendants","id":"hamlet:1.2:1"},{"kind":"speech","text":"Though yet of Hamlet our dear brother's death\nThe memory be green, and that it us befitted\nTo bear our hearts in grief and our whole kingdom\nTo be contracted in one brow of woe,\nYet so far hath discretion fought with nature\nThat we with wisest sorrow think on him,\nTogether with remembrance of ourselves.\nTherefore our sometime sister, now our queen,\nThe imperial jointress to this warlike state,\nHave we, as 'twere with a defeated joy,--\nWith an auspicious and a dropping eye,\nWith mirth in funeral and with dirge in marriage,\nIn equal scale weighing delight and dole,--\nTaken to wife: nor have we herein barr'd\nYour better wisdoms, which have freely gone\nWith this affair along. For all, our thanks.\nNow follows, that you know, young Fortinbras,\nHolding a weak supposal of our worth,\nOr thinking by our late dear brother's death\nOur state to be disjoint and out of frame,\nColleagued with the dream of his advantage,\nHe hath not fail'd to pester us with message,\nImporting the surrender of those lands\nLost by his father, with all bonds of law,\nTo our most valiant brother. So much for him.\nNow for ourself and for this time of meeting:\nThus much the business is: we have here writ\nTo Norway, uncle of young Fortinbras,--\nWho, impotent and bed-rid, scarcely hears\nOf this his nephew's purpose,--to suppress\nHis further gait herein; in that the levies,\nThe lists and full proportions, are all made\nOut of his subject: and we here dispatch\nYou, good Cornelius, and you, Voltimand,\nFor bearers of this greeting to old Norway;\nGiving to you no further personal power\nTo business with the king, more than the scope\nOf these delated articles allow.\nFarewell, and let your haste commend your duty.","sourceLine":"1.2.1","speaker":"KING CLAUDIUS","id":"hamlet:1.2:2"},{"kind":"speech","text":"In that and all things will we show our duty.","sourceLine":"1.2.40","speaker":"VOLTIMAND","id":"hamlet:1.2:3"},{"kind":"speech","text":"We doubt it nothing: heartily farewell.","sourceLine":"1.2.41","speaker":"KING CLAUDIUS","id":"hamlet:1.2:4"},{"kind":"stage","text":"Exeunt VOLTIMAND and CORNELIUS","id":"hamlet:1.2:5"},{"kind":"speech","text":"And now, Laertes, what's the news with you?\nYou told us of some suit; what is't, Laertes?\nYou cannot speak of reason to the Dane,\nAnd loose your voice: what wouldst thou beg, Laertes,\nThat shall not be my offer, not thy asking?\nThe head is not more native to the heart,\nThe hand more instrumental to the mouth,\nThan is the throne of Denmark to thy father.\nWhat wouldst thou have, Laertes?","sourceLine":"1.2.42","speaker":"KING CLAUDIUS","id":"hamlet:1.2:6"},{"kind":"speech","text":"My dread lord,\nYour leave and favour to return to France;\nFrom whence though willingly I came to Denmark,\nTo show my duty in your coronation,\nYet now, I must confess, that duty done,\nMy thoughts and wishes bend again toward France\nAnd bow them to your gracious leave and pardon.","sourceLine":"1.2.51","speaker":"LAERTES","id":"hamlet:1.2:7"},{"kind":"speech","text":"Have you your father's leave? What says Polonius?","sourceLine":"1.2.58","speaker":"KING CLAUDIUS","id":"hamlet:1.2:8"},{"kind":"speech","text":"He hath, my lord, wrung from me my slow leave\nBy laboursome petition, and at last\nUpon his will I seal'd my hard consent:\nI do beseech you, give him leave to go.","sourceLine":"1.2.59","speaker":"LORD POLONIUS","id":"hamlet:1.2:9"},{"kind":"speech","text":"Take thy fair hour, Laertes; time be thine,\nAnd thy best graces spend it at thy will!\nBut now, my cousin Hamlet, and my son,--","sourceLine":"1.2.63","speaker":"KING CLAUDIUS","id":"hamlet:1.2:10"},{"kind":"speech","text":"[Aside] A little more than kin, and less than kind.","sourceLine":"1.2.66","speaker":"HAMLET","id":"hamlet:1.2:11"},{"kind":"speech","text":"How is it that the clouds still hang on you?","sourceLine":"1.2.67","speaker":"KING CLAUDIUS","id":"hamlet:1.2:12"},{"kind":"speech","text":"Not so, my lord; I am too much i' the sun.","sourceLine":"1.2.68","speaker":"HAMLET","id":"hamlet:1.2:13"},{"kind":"speech","text":"Good Hamlet, cast thy nighted colour off,\nAnd let thine eye look like a friend on Denmark.\nDo not for ever with thy vailed lids\nSeek for thy noble father in the dust:\nThou know'st 'tis common; all that lives must die,\nPassing through nature to eternity.","sourceLine":"1.2.69","speaker":"QUEEN GERTRUDE","id":"hamlet:1.2:14"},{"kind":"speech","text":"Ay, madam, it is common.","sourceLine":"1.2.75","speaker":"HAMLET","id":"hamlet:1.2:15"},{"kind":"speech","text":"If it be,\nWhy seems it so particular with thee?","sourceLine":"1.2.76","speaker":"QUEEN GERTRUDE","id":"hamlet:1.2:16"},{"kind":"speech","text":"Seems, madam! nay it is; I know not 'seems.'\n'Tis not alone my inky cloak, good mother,\nNor customary suits of solemn black,\nNor windy suspiration of forced breath,\nNo, nor the fruitful river in the eye,\nNor the dejected 'havior of the visage,\nTogether with all forms, moods, shapes of grief,\nThat can denote me truly: these indeed seem,\nFor they are actions that a man might play:\nBut I have that within which passeth show;\nThese but the trappings and the suits of woe.","sourceLine":"1.2.78","speaker":"HAMLET","id":"hamlet:1.2:17"},{"kind":"speech","text":"'Tis sweet and commendable in your nature, Hamlet,\nTo give these mourning duties to your father:\nBut, you must know, your father lost a father;\nThat father lost, lost his, and the survivor bound\nIn filial obligation for some term\nTo do obsequious sorrow: but to persever\nIn obstinate condolement is a course\nOf impious stubbornness; 'tis unmanly grief;\nIt shows a will most incorrect to heaven,\nA heart unfortified, a mind impatient,\nAn understanding simple and unschool'd:\nFor what we know must be and is as common\nAs any the most vulgar thing to sense,\nWhy should we in our peevish opposition\nTake it to heart? Fie! 'tis a fault to heaven,\nA fault against the dead, a fault to nature,\nTo reason most absurd: whose common theme\nIs death of fathers, and who still hath cried,\nFrom the first corse till he that died to-day,\n'This must be so.' We pray you, throw to earth\nThis unprevailing woe, and think of us\nAs of a father: for let the world take note,\nYou are the most immediate to our throne;\nAnd with no less nobility of love\nThan that which dearest father bears his son,\nDo I impart toward you. For your intent\nIn going back to school in Wittenberg,\nIt is most retrograde to our desire:\nAnd we beseech you, bend you to remain\nHere, in the cheer and comfort of our eye,\nOur chiefest courtier, cousin, and our son.","sourceLine":"1.2.89","speaker":"KING CLAUDIUS","id":"hamlet:1.2:18"},{"kind":"speech","text":"Let not thy mother lose her prayers, Hamlet:\nI pray thee, stay with us; go not to Wittenberg.","sourceLine":"1.2.120","speaker":"QUEEN GERTRUDE","id":"hamlet:1.2:19"},{"kind":"speech","text":"I shall in all my best obey you, madam.","sourceLine":"1.2.122","speaker":"HAMLET","id":"hamlet:1.2:20"},{"kind":"speech","text":"Why, 'tis a loving and a fair reply:\nBe as ourself in Denmark. Madam, come;\nThis gentle and unforced accord of Hamlet\nSits smiling to my heart: in grace whereof,\nNo jocund health that Denmark drinks to-day,\nBut the great cannon to the clouds shall tell,\nAnd the king's rouse the heavens all bruit again,\nRe-speaking earthly thunder. Come away.","sourceLine":"1.2.123","speaker":"KING CLAUDIUS","id":"hamlet:1.2:21"},{"kind":"stage","text":"Exeunt all but HAMLET","id":"hamlet:1.2:22"},{"kind":"speech","text":"O, that this too too solid flesh would melt\nThaw and resolve itself into a dew!\nOr that the Everlasting had not fix'd\nHis canon 'gainst self-slaughter! O God! God!\nHow weary, stale, flat and unprofitable,\nSeem to me all the uses of this world!\nFie on't! ah fie! 'tis an unweeded garden,\nThat grows to seed; things rank and gross in nature\nPossess it merely. That it should come to this!\nBut two months dead: nay, not so much, not two:\nSo excellent a king; that was, to this,\nHyperion to a satyr; so loving to my mother\nThat he might not beteem the winds of heaven\nVisit her face too roughly. Heaven and earth!\nMust I remember? why, she would hang on him,\nAs if increase of appetite had grown\nBy what it fed on: and yet, within a month--\nLet me not think on't--Frailty, thy name is woman!--\nA little month, or ere those shoes were old\nWith which she follow'd my poor father's body,\nLike Niobe, all tears:--why she, even she--\nO, God! a beast, that wants discourse of reason,\nWould have mourn'd longer--married with my uncle,\nMy father's brother, but no more like my father\nThan I to Hercules: within a month:\nEre yet the salt of most unrighteous tears\nHad left the flushing in her galled eyes,\nShe married. O, most wicked speed, to post\nWith such dexterity to incestuous sheets!\nIt is not nor it cannot come to good:\nBut break, my heart; for I must hold my tongue.","sourceLine":"1.2.131","speaker":"HAMLET","id":"hamlet:1.2:23"},{"kind":"stage","text":"Enter HORATIO, MARCELLUS, and BERNARDO","id":"hamlet:1.2:24"},{"kind":"speech","text":"Hail to your lordship!","sourceLine":"1.2.162","speaker":"HORATIO","id":"hamlet:1.2:25"},{"kind":"speech","text":"I am glad to see you well:\nHoratio,--or I do forget myself.","sourceLine":"1.2.163","speaker":"HAMLET","id":"hamlet:1.2:26"},{"kind":"speech","text":"The same, my lord, and your poor servant ever.","sourceLine":"1.2.165","speaker":"HORATIO","id":"hamlet:1.2:27"},{"kind":"speech","text":"Sir, my good friend; I'll change that name with you:\nAnd what make you from Wittenberg, Horatio? Marcellus?","sourceLine":"1.2.166","speaker":"HAMLET","id":"hamlet:1.2:28"},{"kind":"speech","text":"My good lord--","sourceLine":"1.2.168","speaker":"MARCELLUS","id":"hamlet:1.2:29"},{"kind":"speech","text":"I am very glad to see you. Good even, sir.\nBut what, in faith, make you from Wittenberg?","sourceLine":"1.2.169","speaker":"HAMLET","id":"hamlet:1.2:30"},{"kind":"speech","text":"A truant disposition, good my lord.","sourceLine":"1.2.171","speaker":"HORATIO","id":"hamlet:1.2:31"},{"kind":"speech","text":"I would not hear your enemy say so,\nNor shall you do mine ear that violence,\nTo make it truster of your own report\nAgainst yourself: I know you are no truant.\nBut what is your affair in Elsinore?\nWe'll teach you to drink deep ere you depart.","sourceLine":"1.2.172","speaker":"HAMLET","id":"hamlet:1.2:32"},{"kind":"speech","text":"My lord, I came to see your father's funeral.","sourceLine":"1.2.178","speaker":"HORATIO","id":"hamlet:1.2:33"},{"kind":"speech","text":"I pray thee, do not mock me, fellow-student;\nI think it was to see my mother's wedding.","sourceLine":"1.2.179","speaker":"HAMLET","id":"hamlet:1.2:34"},{"kind":"speech","text":"Indeed, my lord, it follow'd hard upon.","sourceLine":"1.2.181","speaker":"HORATIO","id":"hamlet:1.2:35"},{"kind":"speech","text":"Thrift, thrift, Horatio! the funeral baked meats\nDid coldly furnish forth the marriage tables.\nWould I had met my dearest foe in heaven\nOr ever I had seen that day, Horatio!\nMy father!--methinks I see my father.","sourceLine":"1.2.182","speaker":"HAMLET","id":"hamlet:1.2:36"},{"kind":"speech","text":"Where, my lord?","sourceLine":"1.2.187","speaker":"HORATIO","id":"hamlet:1.2:37"},{"kind":"speech","text":"In my mind's eye, Horatio.","sourceLine":"1.2.188","speaker":"HAMLET","id":"hamlet:1.2:38"},{"kind":"speech","text":"I saw him once; he was a goodly king.","sourceLine":"1.2.189","speaker":"HORATIO","id":"hamlet:1.2:39"},{"kind":"speech","text":"He was a man, take him for all in all,\nI shall not look upon his like again.","sourceLine":"1.2.190","speaker":"HAMLET","id":"hamlet:1.2:40"},{"kind":"speech","text":"My lord, I think I saw him yesternight.","sourceLine":"1.2.192","speaker":"HORATIO","id":"hamlet:1.2:41"},{"kind":"speech","text":"Saw? who?","sourceLine":"1.2.193","speaker":"HAMLET","id":"hamlet:1.2:42"},{"kind":"speech","text":"My lord, the king your father.","sourceLine":"1.2.194","speaker":"HORATIO","id":"hamlet:1.2:43"},{"kind":"speech","text":"The king my father!","sourceLine":"1.2.195","speaker":"HAMLET","id":"hamlet:1.2:44"},{"kind":"speech","text":"Season your admiration for awhile\nWith an attent ear, till I may deliver,\nUpon the witness of these gentlemen,\nThis marvel to you.","sourceLine":"1.2.196","speaker":"HORATIO","id":"hamlet:1.2:45"},{"kind":"speech","text":"For God's love, let me hear.","sourceLine":"1.2.200","speaker":"HAMLET","id":"hamlet:1.2:46"},{"kind":"speech","text":"Two nights together had these gentlemen,\nMarcellus and Bernardo, on their watch,\nIn the dead vast and middle of the night,\nBeen thus encounter'd. A figure like your father,\nArmed at point exactly, cap-a-pe,\nAppears before them, and with solemn march\nGoes slow and stately by them: thrice he walk'd\nBy their oppress'd and fear-surprised eyes,\nWithin his truncheon's length; whilst they, distilled\nAlmost to jelly with the act of fear,\nStand dumb and speak not to him. This to me\nIn dreadful secrecy impart they did;\nAnd I with them the third night kept the watch;\nWhere, as they had deliver'd, both in time,\nForm of the thing, each word made true and good,\nThe apparition comes: I knew your father;\nThese hands are not more like.","sourceLine":"1.2.201","speaker":"HORATIO","id":"hamlet:1.2:47"},{"kind":"speech","text":"But where was this?","sourceLine":"1.2.218","speaker":"HAMLET","id":"hamlet:1.2:48"},{"kind":"speech","text":"My lord, upon the platform where we watch'd.","sourceLine":"1.2.219","speaker":"MARCELLUS","id":"hamlet:1.2:49"},{"kind":"speech","text":"Did you not speak to it?","sourceLine":"1.2.220","speaker":"HAMLET","id":"hamlet:1.2:50"},{"kind":"speech","text":"My lord, I did;\nBut answer made it none: yet once methought\nIt lifted up its head and did address\nItself to motion, like as it would speak;\nBut even then the morning cock crew loud,\nAnd at the sound it shrunk in haste away,\nAnd vanish'd from our sight.","sourceLine":"1.2.221","speaker":"HORATIO","id":"hamlet:1.2:51"},{"kind":"speech","text":"'Tis very strange.","sourceLine":"1.2.228","speaker":"HAMLET","id":"hamlet:1.2:52"},{"kind":"speech","text":"As I do live, my honour'd lord, 'tis true;\nAnd we did think it writ down in our duty\nTo let you know of it.","sourceLine":"1.2.229","speaker":"HORATIO","id":"hamlet:1.2:53"},{"kind":"speech","text":"Indeed, indeed, sirs, but this troubles me.\nHold you the watch to-night?","sourceLine":"1.2.232","speaker":"HAMLET","id":"hamlet:1.2:54"},{"kind":"speech","text":"We do, my lord.","sourceLine":"1.2.234","speaker":"BERNARDO","id":"hamlet:1.2:55"},{"kind":"speech","text":"Arm'd, say you?","sourceLine":"1.2.235","speaker":"HAMLET","id":"hamlet:1.2:56"},{"kind":"speech","text":"Arm'd, my lord.","sourceLine":"1.2.236","speaker":"BERNARDO","id":"hamlet:1.2:57"},{"kind":"speech","text":"From top to toe?","sourceLine":"1.2.237","speaker":"HAMLET","id":"hamlet:1.2:58"},{"kind":"speech","text":"My lord, from head to foot.","sourceLine":"1.2.238","speaker":"BERNARDO","id":"hamlet:1.2:59"},{"kind":"speech","text":"Then saw you not his face?","sourceLine":"1.2.239","speaker":"HAMLET","id":"hamlet:1.2:60"},{"kind":"speech","text":"O, yes, my lord; he wore his beaver up.","sourceLine":"1.2.240","speaker":"HORATIO","id":"hamlet:1.2:61"},{"kind":"speech","text":"What, look'd he frowningly?","sourceLine":"1.2.241","speaker":"HAMLET","id":"hamlet:1.2:62"},{"kind":"speech","text":"A countenance more in sorrow than in anger.","sourceLine":"1.2.242","speaker":"HORATIO","id":"hamlet:1.2:63"},{"kind":"speech","text":"Pale or red?","sourceLine":"1.2.243","speaker":"HAMLET","id":"hamlet:1.2:64"},{"kind":"speech","text":"Nay, very pale.","sourceLine":"1.2.244","speaker":"HORATIO","id":"hamlet:1.2:65"},{"kind":"speech","text":"And fix'd his eyes upon you?","sourceLine":"1.2.245","speaker":"HAMLET","id":"hamlet:1.2:66"},{"kind":"speech","text":"Most constantly.","sourceLine":"1.2.246","speaker":"HORATIO","id":"hamlet:1.2:67"},{"kind":"speech","text":"I would I had been there.","sourceLine":"1.2.247","speaker":"HAMLET","id":"hamlet:1.2:68"},{"kind":"speech","text":"It would have much amazed you.","sourceLine":"1.2.248","speaker":"HORATIO","id":"hamlet:1.2:69"},{"kind":"speech","text":"Very like, very like. Stay'd it long?","sourceLine":"1.2.249","speaker":"HAMLET","id":"hamlet:1.2:70"},{"kind":"speech","text":"While one with moderate haste might tell a hundred.","sourceLine":"1.2.250","speaker":"HORATIO","id":"hamlet:1.2:71"},{"kind":"speech","text":"Longer, longer.","sourceLine":"1.2.251","speaker":"BERNARDO","id":"hamlet:1.2:72"},{"kind":"speech","text":"Not when I saw't.","sourceLine":"1.2.252","speaker":"HORATIO","id":"hamlet:1.2:73"},{"kind":"speech","text":"His beard was grizzled--no?","sourceLine":"1.2.253","speaker":"HAMLET","id":"hamlet:1.2:74"},{"kind":"speech","text":"It was, as I have seen it in his life,\nA sable silver'd.","sourceLine":"1.2.254","speaker":"HORATIO","id":"hamlet:1.2:75"},{"kind":"speech","text":"I will watch to-night;\nPerchance 'twill walk again.","sourceLine":"1.2.256","speaker":"HAMLET","id":"hamlet:1.2:76"},{"kind":"speech","text":"I warrant it will.","sourceLine":"1.2.258","speaker":"HORATIO","id":"hamlet:1.2:77"},{"kind":"speech","text":"If it assume my noble father's person,\nI'll speak to it, though hell itself should gape\nAnd bid me hold my peace. I pray you all,\nIf you have hitherto conceal'd this sight,\nLet it be tenable in your silence still;\nAnd whatsoever else shall hap to-night,\nGive it an understanding, but no tongue:\nI will requite your loves. So, fare you well:\nUpon the platform, 'twixt eleven and twelve,\nI'll visit you.","sourceLine":"1.2.259","speaker":"HAMLET","id":"hamlet:1.2:78"},{"kind":"speech","text":"Our duty to your honour.","sourceLine":"1.2.269","speaker":"All","id":"hamlet:1.2:79"},{"kind":"speech","text":"Your loves, as mine to you: farewell.","sourceLine":"1.2.270","speaker":"HAMLET","id":"hamlet:1.2:80"},{"kind":"stage","text":"Exeunt all but HAMLET","id":"hamlet:1.2:81"},{"kind":"speech","text":"My father's spirit in arms! all is not well;\nI doubt some foul play: would the night were come!\nTill then sit still, my soul: foul deeds will rise,\nThough all the earth o'erwhelm them, to men's eyes.","sourceLine":"1.2.271","speaker":"HAMLET","id":"hamlet:1.2:82"},{"kind":"stage","text":"Exit","id":"hamlet:1.2:83"}],"scene":2},{"id":"1.3","label":"Act 1 · SCENE III. A room in Polonius' house.","act":1,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter LAERTES and OPHELIA","id":"hamlet:1.3:1"},{"kind":"speech","text":"My necessaries are embark'd: farewell:\nAnd, sister, as the winds give benefit\nAnd convoy is assistant, do not sleep,\nBut let me hear from you.","sourceLine":"1.3.1","speaker":"LAERTES","id":"hamlet:1.3:2"},{"kind":"speech","text":"Do you doubt that?","sourceLine":"1.3.5","speaker":"OPHELIA","id":"hamlet:1.3:3"},{"kind":"speech","text":"For Hamlet and the trifling of his favour,\nHold it a fashion and a toy in blood,\nA violet in the youth of primy nature,\nForward, not permanent, sweet, not lasting,\nThe perfume and suppliance of a minute; No more.","sourceLine":"1.3.6","speaker":"LAERTES","id":"hamlet:1.3:4"},{"kind":"speech","text":"No more but so?","sourceLine":"1.3.11","speaker":"OPHELIA","id":"hamlet:1.3:5"},{"kind":"speech","text":"Think it no more;\nFor nature, crescent, does not grow alone\nIn thews and bulk, but, as this temple waxes,\nThe inward service of the mind and soul\nGrows wide withal. Perhaps he loves you now,\nAnd now no soil nor cautel doth besmirch\nThe virtue of his will: but you must fear,\nHis greatness weigh'd, his will is not his own;\nFor he himself is subject to his birth:\nHe may not, as unvalued persons do,\nCarve for himself; for on his choice depends\nThe safety and health of this whole state;\nAnd therefore must his choice be circumscribed\nUnto the voice and yielding of that body\nWhereof he is the head. Then if he says he loves you,\nIt fits your wisdom so far to believe it\nAs he in his particular act and place\nMay give his saying deed; which is no further\nThan the main voice of Denmark goes withal.\nThen weigh what loss your honour may sustain,\nIf with too credent ear you list his songs,\nOr lose your heart, or your chaste treasure open\nTo his unmaster'd importunity.\nFear it, Ophelia, fear it, my dear sister,\nAnd keep you in the rear of your affection,\nOut of the shot and danger of desire.\nThe chariest maid is prodigal enough,\nIf she unmask her beauty to the moon:\nVirtue itself 'scapes not calumnious strokes:\nThe canker galls the infants of the spring,\nToo oft before their buttons be disclosed,\nAnd in the morn and liquid dew of youth\nContagious blastments are most imminent.\nBe wary then; best safety lies in fear:\nYouth to itself rebels, though none else near.","sourceLine":"1.3.12","speaker":"LAERTES","id":"hamlet:1.3:6"},{"kind":"speech","text":"I shall the effect of this good lesson keep,\nAs watchman to my heart. But, good my brother,\nDo not, as some ungracious pastors do,\nShow me the steep and thorny way to heaven;\nWhiles, like a puff'd and reckless libertine,\nHimself the primrose path of dalliance treads,\nAnd recks not his own rede.","sourceLine":"1.3.47","speaker":"OPHELIA","id":"hamlet:1.3:7"},{"kind":"speech","text":"O, fear me not.\nI stay too long: but here my father comes.","sourceLine":"1.3.54","speaker":"LAERTES","id":"hamlet:1.3:8"},{"kind":"stage","text":"Enter POLONIUS","id":"hamlet:1.3:9"},{"kind":"speech","text":"A double blessing is a double grace,\nOccasion smiles upon a second leave.","sourceLine":"1.3.56","speaker":"LAERTES","id":"hamlet:1.3:10"},{"kind":"speech","text":"Yet here, Laertes! aboard, aboard, for shame!\nThe wind sits in the shoulder of your sail,\nAnd you are stay'd for. There; my blessing with thee!\nAnd these few precepts in thy memory\nSee thou character. Give thy thoughts no tongue,\nNor any unproportioned thought his act.\nBe thou familiar, but by no means vulgar.\nThose friends thou hast, and their adoption tried,\nGrapple them to thy soul with hoops of steel;\nBut do not dull thy palm with entertainment\nOf each new-hatch'd, unfledged comrade. Beware\nOf entrance to a quarrel, but being in,\nBear't that the opposed may beware of thee.\nGive every man thy ear, but few thy voice;\nTake each man's censure, but reserve thy judgment.\nCostly thy habit as thy purse can buy,\nBut not express'd in fancy; rich, not gaudy;\nFor the apparel oft proclaims the man,\nAnd they in France of the best rank and station\nAre of a most select and generous chief in that.\nNeither a borrower nor a lender be;\nFor loan oft loses both itself and friend,\nAnd borrowing dulls the edge of husbandry.\nThis above all: to thine ownself be true,\nAnd it must follow, as the night the day,\nThou canst not then be false to any man.\nFarewell: my blessing season this in thee!","sourceLine":"1.3.58","speaker":"LORD POLONIUS","id":"hamlet:1.3:11"},{"kind":"speech","text":"Most humbly do I take my leave, my lord.","sourceLine":"1.3.85","speaker":"LAERTES","id":"hamlet:1.3:12"},{"kind":"speech","text":"The time invites you; go; your servants tend.","sourceLine":"1.3.86","speaker":"LORD POLONIUS","id":"hamlet:1.3:13"},{"kind":"speech","text":"Farewell, Ophelia; and remember well\nWhat I have said to you.","sourceLine":"1.3.87","speaker":"LAERTES","id":"hamlet:1.3:14"},{"kind":"speech","text":"'Tis in my memory lock'd,\nAnd you yourself shall keep the key of it.","sourceLine":"1.3.89","speaker":"OPHELIA","id":"hamlet:1.3:15"},{"kind":"speech","text":"Farewell.","sourceLine":"1.3.91","speaker":"LAERTES","id":"hamlet:1.3:16"},{"kind":"stage","text":"Exit","id":"hamlet:1.3:17"},{"kind":"speech","text":"What is't, Ophelia, be hath said to you?","sourceLine":"1.3.92","speaker":"LORD POLONIUS","id":"hamlet:1.3:18"},{"kind":"speech","text":"So please you, something touching the Lord Hamlet.","sourceLine":"1.3.93","speaker":"OPHELIA","id":"hamlet:1.3:19"},{"kind":"speech","text":"Marry, well bethought:\n'Tis told me, he hath very oft of late\nGiven private time to you; and you yourself\nHave of your audience been most free and bounteous:\nIf it be so, as so 'tis put on me,\nAnd that in way of caution, I must tell you,\nYou do not understand yourself so clearly\nAs it behoves my daughter and your honour.\nWhat is between you? give me up the truth.","sourceLine":"1.3.94","speaker":"LORD POLONIUS","id":"hamlet:1.3:20"},{"kind":"speech","text":"He hath, my lord, of late made many tenders\nOf his affection to me.","sourceLine":"1.3.103","speaker":"OPHELIA","id":"hamlet:1.3:21"},{"kind":"speech","text":"Affection! pooh! you speak like a green girl,\nUnsifted in such perilous circumstance.\nDo you believe his tenders, as you call them?","sourceLine":"1.3.105","speaker":"LORD POLONIUS","id":"hamlet:1.3:22"},{"kind":"speech","text":"I do not know, my lord, what I should think.","sourceLine":"1.3.108","speaker":"OPHELIA","id":"hamlet:1.3:23"},{"kind":"speech","text":"Marry, I'll teach you: think yourself a baby;\nThat you have ta'en these tenders for true pay,\nWhich are not sterling. Tender yourself more dearly;\nOr--not to crack the wind of the poor phrase,\nRunning it thus--you'll tender me a fool.","sourceLine":"1.3.109","speaker":"LORD POLONIUS","id":"hamlet:1.3:24"},{"kind":"speech","text":"My lord, he hath importuned me with love\nIn honourable fashion.","sourceLine":"1.3.114","speaker":"OPHELIA","id":"hamlet:1.3:25"},{"kind":"speech","text":"Ay, fashion you may call it; go to, go to.","sourceLine":"1.3.116","speaker":"LORD POLONIUS","id":"hamlet:1.3:26"},{"kind":"speech","text":"And hath given countenance to his speech, my lord,\nWith almost all the holy vows of heaven.","sourceLine":"1.3.117","speaker":"OPHELIA","id":"hamlet:1.3:27"},{"kind":"speech","text":"Ay, springes to catch woodcocks. I do know,\nWhen the blood burns, how prodigal the soul\nLends the tongue vows: these blazes, daughter,\nGiving more light than heat, extinct in both,\nEven in their promise, as it is a-making,\nYou must not take for fire. From this time\nBe somewhat scanter of your maiden presence;\nSet your entreatments at a higher rate\nThan a command to parley. For Lord Hamlet,\nBelieve so much in him, that he is young\nAnd with a larger tether may he walk\nThan may be given you: in few, Ophelia,\nDo not believe his vows; for they are brokers,\nNot of that dye which their investments show,\nBut mere implorators of unholy suits,\nBreathing like sanctified and pious bawds,\nThe better to beguile. This is for all:\nI would not, in plain terms, from this time forth,\nHave you so slander any moment leisure,\nAs to give words or talk with the Lord Hamlet.\nLook to't, I charge you: come your ways.","sourceLine":"1.3.119","speaker":"LORD POLONIUS","id":"hamlet:1.3:28"},{"kind":"speech","text":"I shall obey, my lord.","sourceLine":"1.3.140","speaker":"OPHELIA","id":"hamlet:1.3:29"},{"kind":"stage","text":"Exeunt","id":"hamlet:1.3:30"}],"scene":3},{"id":"1.4","label":"Act 1 · SCENE IV. The platform.","act":1,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter HAMLET, HORATIO, and MARCELLUS","id":"hamlet:1.4:1"},{"kind":"speech","text":"The air bites shrewdly; it is very cold.","sourceLine":"1.4.1","speaker":"HAMLET","id":"hamlet:1.4:2"},{"kind":"speech","text":"It is a nipping and an eager air.","sourceLine":"1.4.2","speaker":"HORATIO","id":"hamlet:1.4:3"},{"kind":"speech","text":"What hour now?","sourceLine":"1.4.3","speaker":"HAMLET","id":"hamlet:1.4:4"},{"kind":"speech","text":"I think it lacks of twelve.","sourceLine":"1.4.4","speaker":"HORATIO","id":"hamlet:1.4:5"},{"kind":"speech","text":"No, it is struck.","sourceLine":"1.4.5","speaker":"HAMLET","id":"hamlet:1.4:6"},{"kind":"speech","text":"Indeed? I heard it not: then it draws near the season\nWherein the spirit held his wont to walk.","sourceLine":"1.4.6","speaker":"HORATIO","id":"hamlet:1.4:7"},{"kind":"stage","text":"A flourish of trumpets, and ordnance shot off, within","id":"hamlet:1.4:8"},{"kind":"speech","text":"What does this mean, my lord?","sourceLine":"1.4.8","speaker":"HORATIO","id":"hamlet:1.4:9"},{"kind":"speech","text":"The king doth wake to-night and takes his rouse,\nKeeps wassail, and the swaggering up-spring reels;\nAnd, as he drains his draughts of Rhenish down,\nThe kettle-drum and trumpet thus bray out\nThe triumph of his pledge.","sourceLine":"1.4.9","speaker":"HAMLET","id":"hamlet:1.4:10"},{"kind":"speech","text":"Is it a custom?","sourceLine":"1.4.14","speaker":"HORATIO","id":"hamlet:1.4:11"},{"kind":"speech","text":"Ay, marry, is't:\nBut to my mind, though I am native here\nAnd to the manner born, it is a custom\nMore honour'd in the breach than the observance.\nThis heavy-headed revel east and west\nMakes us traduced and tax'd of other nations:\nThey clepe us drunkards, and with swinish phrase\nSoil our addition; and indeed it takes\nFrom our achievements, though perform'd at height,\nThe pith and marrow of our attribute.\nSo, oft it chances in particular men,\nThat for some vicious mole of nature in them,\nAs, in their birth--wherein they are not guilty,\nSince nature cannot choose his origin--\nBy the o'ergrowth of some complexion,\nOft breaking down the pales and forts of reason,\nOr by some habit that too much o'er-leavens\nThe form of plausive manners, that these men,\nCarrying, I say, the stamp of one defect,\nBeing nature's livery, or fortune's star,--\nTheir virtues else--be they as pure as grace,\nAs infinite as man may undergo--\nShall in the general censure take corruption\nFrom that particular fault: the dram of eale\nDoth all the noble substance of a doubt\nTo his own scandal.","sourceLine":"1.4.15","speaker":"HAMLET","id":"hamlet:1.4:12"},{"kind":"speech","text":"Look, my lord, it comes!","sourceLine":"1.4.41","speaker":"HORATIO","id":"hamlet:1.4:13"},{"kind":"stage","text":"Enter Ghost","id":"hamlet:1.4:14"},{"kind":"speech","text":"Angels and ministers of grace defend us!\nBe thou a spirit of health or goblin damn'd,\nBring with thee airs from heaven or blasts from hell,\nBe thy intents wicked or charitable,\nThou comest in such a questionable shape\nThat I will speak to thee: I'll call thee Hamlet,\nKing, father, royal Dane: O, answer me!\nLet me not burst in ignorance; but tell\nWhy thy canonized bones, hearsed in death,\nHave burst their cerements; why the sepulchre,\nWherein we saw thee quietly inurn'd,\nHath oped his ponderous and marble jaws,\nTo cast thee up again. What may this mean,\nThat thou, dead corse, again in complete steel\nRevisit'st thus the glimpses of the moon,\nMaking night hideous; and we fools of nature\nSo horridly to shake our disposition\nWith thoughts beyond the reaches of our souls?\nSay, why is this? wherefore? what should we do?","sourceLine":"1.4.42","speaker":"HAMLET","id":"hamlet:1.4:15"},{"kind":"stage","text":"Ghost beckons HAMLET","id":"hamlet:1.4:16"},{"kind":"speech","text":"It beckons you to go away with it,\nAs if it some impartment did desire\nTo you alone.","sourceLine":"1.4.61","speaker":"HORATIO","id":"hamlet:1.4:17"},{"kind":"speech","text":"Look, with what courteous action\nIt waves you to a more removed ground:\nBut do not go with it.","sourceLine":"1.4.64","speaker":"MARCELLUS","id":"hamlet:1.4:18"},{"kind":"speech","text":"No, by no means.","sourceLine":"1.4.67","speaker":"HORATIO","id":"hamlet:1.4:19"},{"kind":"speech","text":"It will not speak; then I will follow it.","sourceLine":"1.4.68","speaker":"HAMLET","id":"hamlet:1.4:20"},{"kind":"speech","text":"Do not, my lord.","sourceLine":"1.4.69","speaker":"HORATIO","id":"hamlet:1.4:21"},{"kind":"speech","text":"Why, what should be the fear?\nI do not set my life in a pin's fee;\nAnd for my soul, what can it do to that,\nBeing a thing immortal as itself?\nIt waves me forth again: I'll follow it.","sourceLine":"1.4.70","speaker":"HAMLET","id":"hamlet:1.4:22"},{"kind":"speech","text":"What if it tempt you toward the flood, my lord,\nOr to the dreadful summit of the cliff\nThat beetles o'er his base into the sea,\nAnd there assume some other horrible form,\nWhich might deprive your sovereignty of reason\nAnd draw you into madness? think of it:\nThe very place puts toys of desperation,\nWithout more motive, into every brain\nThat looks so many fathoms to the sea\nAnd hears it roar beneath.","sourceLine":"1.4.75","speaker":"HORATIO","id":"hamlet:1.4:23"},{"kind":"speech","text":"It waves me still.\nGo on; I'll follow thee.","sourceLine":"1.4.85","speaker":"HAMLET","id":"hamlet:1.4:24"},{"kind":"speech","text":"You shall not go, my lord.","sourceLine":"1.4.87","speaker":"MARCELLUS","id":"hamlet:1.4:25"},{"kind":"speech","text":"Hold off your hands.","sourceLine":"1.4.88","speaker":"HAMLET","id":"hamlet:1.4:26"},{"kind":"speech","text":"Be ruled; you shall not go.","sourceLine":"1.4.89","speaker":"HORATIO","id":"hamlet:1.4:27"},{"kind":"speech","text":"My fate cries out,\nAnd makes each petty artery in this body\nAs hardy as the Nemean lion's nerve.\nStill am I call'd. Unhand me, gentlemen.\nBy heaven, I'll make a ghost of him that lets me!\nI say, away! Go on; I'll follow thee.","sourceLine":"1.4.90","speaker":"HAMLET","id":"hamlet:1.4:28"},{"kind":"stage","text":"Exeunt Ghost and HAMLET","id":"hamlet:1.4:29"},{"kind":"speech","text":"He waxes desperate with imagination.","sourceLine":"1.4.96","speaker":"HORATIO","id":"hamlet:1.4:30"},{"kind":"speech","text":"Let's follow; 'tis not fit thus to obey him.","sourceLine":"1.4.97","speaker":"MARCELLUS","id":"hamlet:1.4:31"},{"kind":"speech","text":"Have after. To what issue will this come?","sourceLine":"1.4.98","speaker":"HORATIO","id":"hamlet:1.4:32"},{"kind":"speech","text":"Something is rotten in the state of Denmark.","sourceLine":"1.4.99","speaker":"MARCELLUS","id":"hamlet:1.4:33"},{"kind":"speech","text":"Heaven will direct it.","sourceLine":"1.4.100","speaker":"HORATIO","id":"hamlet:1.4:34"},{"kind":"speech","text":"Nay, let's follow him.","sourceLine":"1.4.101","speaker":"MARCELLUS","id":"hamlet:1.4:35"},{"kind":"stage","text":"Exeunt","id":"hamlet:1.4:36"}],"scene":4},{"id":"1.5","label":"Act 1 · SCENE V. Another part of the platform.","act":1,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter GHOST and HAMLET","id":"hamlet:1.5:1"},{"kind":"speech","text":"Where wilt thou lead me? speak; I'll go no further.","sourceLine":"1.5.1","speaker":"HAMLET","id":"hamlet:1.5:2"},{"kind":"speech","text":"Mark me.","sourceLine":"1.5.2","speaker":"Ghost","id":"hamlet:1.5:3"},{"kind":"speech","text":"I will.","sourceLine":"1.5.3","speaker":"HAMLET","id":"hamlet:1.5:4"},{"kind":"speech","text":"My hour is almost come,\nWhen I to sulphurous and tormenting flames\nMust render up myself.","sourceLine":"1.5.4","speaker":"Ghost","id":"hamlet:1.5:5"},{"kind":"speech","text":"Alas, poor ghost!","sourceLine":"1.5.7","speaker":"HAMLET","id":"hamlet:1.5:6"},{"kind":"speech","text":"Pity me not, but lend thy serious hearing\nTo what I shall unfold.","sourceLine":"1.5.8","speaker":"Ghost","id":"hamlet:1.5:7"},{"kind":"speech","text":"Speak; I am bound to hear.","sourceLine":"1.5.10","speaker":"HAMLET","id":"hamlet:1.5:8"},{"kind":"speech","text":"So art thou to revenge, when thou shalt hear.","sourceLine":"1.5.11","speaker":"Ghost","id":"hamlet:1.5:9"},{"kind":"speech","text":"What?","sourceLine":"1.5.12","speaker":"HAMLET","id":"hamlet:1.5:10"},{"kind":"speech","text":"I am thy father's spirit,\nDoom'd for a certain term to walk the night,\nAnd for the day confined to fast in fires,\nTill the foul crimes done in my days of nature\nAre burnt and purged away. But that I am forbid\nTo tell the secrets of my prison-house,\nI could a tale unfold whose lightest word\nWould harrow up thy soul, freeze thy young blood,\nMake thy two eyes, like stars, start from their spheres,\nThy knotted and combined locks to part\nAnd each particular hair to stand on end,\nLike quills upon the fretful porpentine:\nBut this eternal blazon must not be\nTo ears of flesh and blood. List, list, O, list!\nIf thou didst ever thy dear father love--","sourceLine":"1.5.13","speaker":"Ghost","id":"hamlet:1.5:11"},{"kind":"speech","text":"O God!","sourceLine":"1.5.28","speaker":"HAMLET","id":"hamlet:1.5:12"},{"kind":"speech","text":"Revenge his foul and most unnatural murder.","sourceLine":"1.5.29","speaker":"Ghost","id":"hamlet:1.5:13"},{"kind":"speech","text":"Murder!","sourceLine":"1.5.30","speaker":"HAMLET","id":"hamlet:1.5:14"},{"kind":"speech","text":"Murder most foul, as in the best it is;\nBut this most foul, strange and unnatural.","sourceLine":"1.5.31","speaker":"Ghost","id":"hamlet:1.5:15"},{"kind":"speech","text":"Haste me to know't, that I, with wings as swift\nAs meditation or the thoughts of love,\nMay sweep to my revenge.","sourceLine":"1.5.33","speaker":"HAMLET","id":"hamlet:1.5:16"},{"kind":"speech","text":"I find thee apt;\nAnd duller shouldst thou be than the fat weed\nThat roots itself in ease on Lethe wharf,\nWouldst thou not stir in this. Now, Hamlet, hear:\n'Tis given out that, sleeping in my orchard,\nA serpent stung me; so the whole ear of Denmark\nIs by a forged process of my death\nRankly abused: but know, thou noble youth,\nThe serpent that did sting thy father's life\nNow wears his crown.","sourceLine":"1.5.36","speaker":"Ghost","id":"hamlet:1.5:17"},{"kind":"speech","text":"O my prophetic soul! My uncle!","sourceLine":"1.5.46","speaker":"HAMLET","id":"hamlet:1.5:18"},{"kind":"speech","text":"Ay, that incestuous, that adulterate beast,\nWith witchcraft of his wit, with traitorous gifts,--\nO wicked wit and gifts, that have the power\nSo to seduce!--won to his shameful lust\nThe will of my most seeming-virtuous queen:\nO Hamlet, what a falling-off was there!\nFrom me, whose love was of that dignity\nThat it went hand in hand even with the vow\nI made to her in marriage, and to decline\nUpon a wretch whose natural gifts were poor\nTo those of mine!\nBut virtue, as it never will be moved,\nThough lewdness court it in a shape of heaven,\nSo lust, though to a radiant angel link'd,\nWill sate itself in a celestial bed,\nAnd prey on garbage.\nBut, soft! methinks I scent the morning air;\nBrief let me be. Sleeping within my orchard,\nMy custom always of the afternoon,\nUpon my secure hour thy uncle stole,\nWith juice of cursed hebenon in a vial,\nAnd in the porches of my ears did pour\nThe leperous distilment; whose effect\nHolds such an enmity with blood of man\nThat swift as quicksilver it courses through\nThe natural gates and alleys of the body,\nAnd with a sudden vigour doth posset\nAnd curd, like eager droppings into milk,\nThe thin and wholesome blood: so did it mine;\nAnd a most instant tetter bark'd about,\nMost lazar-like, with vile and loathsome crust,\nAll my smooth body.\nThus was I, sleeping, by a brother's hand\nOf life, of crown, of queen, at once dispatch'd:\nCut off even in the blossoms of my sin,\nUnhousel'd, disappointed, unanel'd,\nNo reckoning made, but sent to my account\nWith all my imperfections on my head:\nO, horrible! O, horrible! most horrible!\nIf thou hast nature in thee, bear it not;\nLet not the royal bed of Denmark be\nA couch for luxury and damned incest.\nBut, howsoever thou pursuest this act,\nTaint not thy mind, nor let thy soul contrive\nAgainst thy mother aught: leave her to heaven\nAnd to those thorns that in her bosom lodge,\nTo prick and sting her. Fare thee well at once!\nThe glow-worm shows the matin to be near,\nAnd 'gins to pale his uneffectual fire:\nAdieu, adieu! Hamlet, remember me.","sourceLine":"1.5.47","speaker":"Ghost","id":"hamlet:1.5:19"},{"kind":"stage","text":"Exit","id":"hamlet:1.5:20"},{"kind":"speech","text":"O all you host of heaven! O earth! what else?\nAnd shall I couple hell? O, fie! Hold, hold, my heart;\nAnd you, my sinews, grow not instant old,\nBut bear me stiffly up. Remember thee!\nAy, thou poor ghost, while memory holds a seat\nIn this distracted globe. Remember thee!\nYea, from the table of my memory\nI'll wipe away all trivial fond records,\nAll saws of books, all forms, all pressures past,\nThat youth and observation copied there;\nAnd thy commandment all alone shall live\nWithin the book and volume of my brain,\nUnmix'd with baser matter: yes, by heaven!\nO most pernicious woman!\nO villain, villain, smiling, damned villain!\nMy tables,--meet it is I set it down,\nThat one may smile, and smile, and be a villain;\nAt least I'm sure it may be so in Denmark:","sourceLine":"1.5.97","speaker":"HAMLET","id":"hamlet:1.5:21"},{"kind":"stage","text":"Writing","id":"hamlet:1.5:22"},{"kind":"speech","text":"So, uncle, there you are. Now to my word;\nIt is 'Adieu, adieu! remember me.'\nI have sworn 't.","sourceLine":"1.5.115","speaker":"HAMLET","id":"hamlet:1.5:23"},{"kind":"speech","text":"[Within] My lord, my lord,--","sourceLine":"1.5.118","speaker":"HORATIO","id":"hamlet:1.5:24"},{"kind":"speech","text":"[Within] Lord Hamlet,--","sourceLine":"1.5.119","speaker":"MARCELLUS","id":"hamlet:1.5:25"},{"kind":"speech","text":"[Within] Heaven secure him!","sourceLine":"1.5.120","speaker":"HORATIO","id":"hamlet:1.5:26"},{"kind":"speech","text":"So be it!","sourceLine":"1.5.121","speaker":"HAMLET","id":"hamlet:1.5:27"},{"kind":"speech","text":"[Within] Hillo, ho, ho, my lord!","sourceLine":"1.5.122","speaker":"HORATIO","id":"hamlet:1.5:28"},{"kind":"speech","text":"Hillo, ho, ho, boy! come, bird, come.","sourceLine":"1.5.123","speaker":"HAMLET","id":"hamlet:1.5:29"},{"kind":"stage","text":"Enter HORATIO and MARCELLUS","id":"hamlet:1.5:30"},{"kind":"speech","text":"How is't, my noble lord?","sourceLine":"1.5.124","speaker":"MARCELLUS","id":"hamlet:1.5:31"},{"kind":"speech","text":"What news, my lord?","sourceLine":"1.5.125","speaker":"HORATIO","id":"hamlet:1.5:32"},{"kind":"speech","text":"O, wonderful!","sourceLine":"1.5.126","speaker":"HAMLET","id":"hamlet:1.5:33"},{"kind":"speech","text":"Good my lord, tell it.","sourceLine":"1.5.127","speaker":"HORATIO","id":"hamlet:1.5:34"},{"kind":"speech","text":"No; you'll reveal it.","sourceLine":"1.5.128","speaker":"HAMLET","id":"hamlet:1.5:35"},{"kind":"speech","text":"Not I, my lord, by heaven.","sourceLine":"1.5.129","speaker":"HORATIO","id":"hamlet:1.5:36"},{"kind":"speech","text":"Nor I, my lord.","sourceLine":"1.5.130","speaker":"MARCELLUS","id":"hamlet:1.5:37"},{"kind":"speech","text":"How say you, then; would heart of man once think it?\nBut you'll be secret?","sourceLine":"1.5.131","speaker":"HAMLET","id":"hamlet:1.5:38"},{"kind":"speech","text":"Ay, by heaven, my lord.","sourceLine":"1.5.133","speaker":"MARCELLUS","id":"hamlet:1.5:39"},{"kind":"speech","text":"There's ne'er a villain dwelling in all Denmark\nBut he's an arrant knave.","sourceLine":"1.5.134","speaker":"HAMLET","id":"hamlet:1.5:40"},{"kind":"speech","text":"There needs no ghost, my lord, come from the grave\nTo tell us this.","sourceLine":"1.5.136","speaker":"HORATIO","id":"hamlet:1.5:41"},{"kind":"speech","text":"Why, right; you are i' the right;\nAnd so, without more circumstance at all,\nI hold it fit that we shake hands and part:\nYou, as your business and desire shall point you;\nFor every man has business and desire,\nSuch as it is; and for mine own poor part,\nLook you, I'll go pray.","sourceLine":"1.5.138","speaker":"HAMLET","id":"hamlet:1.5:42"},{"kind":"speech","text":"These are but wild and whirling words, my lord.","sourceLine":"1.5.145","speaker":"HORATIO","id":"hamlet:1.5:43"},{"kind":"speech","text":"I'm sorry they offend you, heartily;\nYes, 'faith heartily.","sourceLine":"1.5.146","speaker":"HAMLET","id":"hamlet:1.5:44"},{"kind":"speech","text":"There's no offence, my lord.","sourceLine":"1.5.148","speaker":"HORATIO","id":"hamlet:1.5:45"},{"kind":"speech","text":"Yes, by Saint Patrick, but there is, Horatio,\nAnd much offence too. Touching this vision here,\nIt is an honest ghost, that let me tell you:\nFor your desire to know what is between us,\nO'ermaster 't as you may. And now, good friends,\nAs you are friends, scholars and soldiers,\nGive me one poor request.","sourceLine":"1.5.149","speaker":"HAMLET","id":"hamlet:1.5:46"},{"kind":"speech","text":"What is't, my lord? we will.","sourceLine":"1.5.156","speaker":"HORATIO","id":"hamlet:1.5:47"},{"kind":"speech","text":"Never make known what you have seen to-night.","sourceLine":"1.5.157","speaker":"HAMLET","id":"hamlet:1.5:48"},{"kind":"speech","text":"My lord, we will not.","sourceLine":"1.5.158","speaker":"MARCELLUS","id":"hamlet:1.5:49"},{"kind":"speech","text":"Nay, but swear't.","sourceLine":"1.5.159","speaker":"HAMLET","id":"hamlet:1.5:50"},{"kind":"speech","text":"In faith,\nMy lord, not I.","sourceLine":"1.5.160","speaker":"HORATIO","id":"hamlet:1.5:51"},{"kind":"speech","text":"Nor I, my lord, in faith.","sourceLine":"1.5.162","speaker":"MARCELLUS","id":"hamlet:1.5:52"},{"kind":"speech","text":"Upon my sword.","sourceLine":"1.5.163","speaker":"HAMLET","id":"hamlet:1.5:53"},{"kind":"speech","text":"We have sworn, my lord, already.","sourceLine":"1.5.164","speaker":"MARCELLUS","id":"hamlet:1.5:54"},{"kind":"speech","text":"Indeed, upon my sword, indeed.","sourceLine":"1.5.165","speaker":"HAMLET","id":"hamlet:1.5:55"},{"kind":"speech","text":"[Beneath] Swear.","sourceLine":"1.5.166","speaker":"Ghost","id":"hamlet:1.5:56"},{"kind":"speech","text":"Ah, ha, boy! say'st thou so? art thou there,\ntruepenny?\nCome on--you hear this fellow in the cellarage--\nConsent to swear.","sourceLine":"1.5.167","speaker":"HAMLET","id":"hamlet:1.5:57"},{"kind":"speech","text":"Propose the oath, my lord.","sourceLine":"1.5.171","speaker":"HORATIO","id":"hamlet:1.5:58"},{"kind":"speech","text":"Never to speak of this that you have seen,\nSwear by my sword.","sourceLine":"1.5.172","speaker":"HAMLET","id":"hamlet:1.5:59"},{"kind":"speech","text":"[Beneath] Swear.","sourceLine":"1.5.174","speaker":"Ghost","id":"hamlet:1.5:60"},{"kind":"speech","text":"Hic et ubique? then we'll shift our ground.\nCome hither, gentlemen,\nAnd lay your hands again upon my sword:\nNever to speak of this that you have heard,\nSwear by my sword.","sourceLine":"1.5.175","speaker":"HAMLET","id":"hamlet:1.5:61"},{"kind":"speech","text":"[Beneath] Swear.","sourceLine":"1.5.180","speaker":"Ghost","id":"hamlet:1.5:62"},{"kind":"speech","text":"Well said, old mole! canst work i' the earth so fast?\nA worthy pioner! Once more remove, good friends.","sourceLine":"1.5.181","speaker":"HAMLET","id":"hamlet:1.5:63"},{"kind":"speech","text":"O day and night, but this is wondrous strange!","sourceLine":"1.5.183","speaker":"HORATIO","id":"hamlet:1.5:64"},{"kind":"speech","text":"And therefore as a stranger give it welcome.\nThere are more things in heaven and earth, Horatio,\nThan are dreamt of in your philosophy. But come;\nHere, as before, never, so help you mercy,\nHow strange or odd soe'er I bear myself,\nAs I perchance hereafter shall think meet\nTo put an antic disposition on,\nThat you, at such times seeing me, never shall,\nWith arms encumber'd thus, or this headshake,\nOr by pronouncing of some doubtful phrase,\nAs 'Well, well, we know,' or 'We could, an if we would,'\nOr 'If we list to speak,' or 'There be, an if they might,'\nOr such ambiguous giving out, to note\nThat you know aught of me: this not to do,\nSo grace and mercy at your most need help you, Swear.","sourceLine":"1.5.184","speaker":"HAMLET","id":"hamlet:1.5:65"},{"kind":"speech","text":"[Beneath] Swear.","sourceLine":"1.5.199","speaker":"Ghost","id":"hamlet:1.5:66"},{"kind":"speech","text":"Rest, rest, perturbed spirit!","sourceLine":"1.5.200","speaker":"HAMLET","id":"hamlet:1.5:67"},{"kind":"stage","text":"They swear","id":"hamlet:1.5:68"},{"kind":"speech","text":"So, gentlemen,\nWith all my love I do commend me to you:\nAnd what so poor a man as Hamlet is\nMay do, to express his love and friending to you,\nGod willing, shall not lack. Let us go in together;\nAnd still your fingers on your lips, I pray.\nThe time is out of joint: O cursed spite,\nThat ever I was born to set it right!\nNay, come, let's go together.","sourceLine":"1.5.201","speaker":"HAMLET","id":"hamlet:1.5:69"},{"kind":"stage","text":"Exeunt","id":"hamlet:1.5:70"}],"scene":5},{"id":"2.1","label":"Act 2 · SCENE I. A room in POLONIUS' house.","act":2,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter POLONIUS and REYNALDO","id":"hamlet:2.1:1"},{"kind":"speech","text":"Give him this money and these notes, Reynaldo.","sourceLine":"2.1.1","speaker":"LORD POLONIUS","id":"hamlet:2.1:2"},{"kind":"speech","text":"I will, my lord.","sourceLine":"2.1.2","speaker":"REYNALDO","id":"hamlet:2.1:3"},{"kind":"speech","text":"You shall do marvellous wisely, good Reynaldo,\nBefore you visit him, to make inquire\nOf his behavior.","sourceLine":"2.1.3","speaker":"LORD POLONIUS","id":"hamlet:2.1:4"},{"kind":"speech","text":"My lord, I did intend it.","sourceLine":"2.1.6","speaker":"REYNALDO","id":"hamlet:2.1:5"},{"kind":"speech","text":"Marry, well said; very well said. Look you, sir,\nInquire me first what Danskers are in Paris;\nAnd how, and who, what means, and where they keep,\nWhat company, at what expense; and finding\nBy this encompassment and drift of question\nThat they do know my son, come you more nearer\nThan your particular demands will touch it:\nTake you, as 'twere, some distant knowledge of him;\nAs thus, 'I know his father and his friends,\nAnd in part him: ' do you mark this, Reynaldo?","sourceLine":"2.1.7","speaker":"LORD POLONIUS","id":"hamlet:2.1:6"},{"kind":"speech","text":"Ay, very well, my lord.","sourceLine":"2.1.17","speaker":"REYNALDO","id":"hamlet:2.1:7"},{"kind":"speech","text":"'And in part him; but' you may say 'not well:\nBut, if't be he I mean, he's very wild;\nAddicted so and so:' and there put on him\nWhat forgeries you please; marry, none so rank\nAs may dishonour him; take heed of that;\nBut, sir, such wanton, wild and usual slips\nAs are companions noted and most known\nTo youth and liberty.","sourceLine":"2.1.18","speaker":"LORD POLONIUS","id":"hamlet:2.1:8"},{"kind":"speech","text":"As gaming, my lord.","sourceLine":"2.1.26","speaker":"REYNALDO","id":"hamlet:2.1:9"},{"kind":"speech","text":"Ay, or drinking, fencing, swearing, quarrelling,\nDrabbing: you may go so far.","sourceLine":"2.1.27","speaker":"LORD POLONIUS","id":"hamlet:2.1:10"},{"kind":"speech","text":"My lord, that would dishonour him.","sourceLine":"2.1.29","speaker":"REYNALDO","id":"hamlet:2.1:11"},{"kind":"speech","text":"'Faith, no; as you may season it in the charge\nYou must not put another scandal on him,\nThat he is open to incontinency;\nThat's not my meaning: but breathe his faults so quaintly\nThat they may seem the taints of liberty,\nThe flash and outbreak of a fiery mind,\nA savageness in unreclaimed blood,\nOf general assault.","sourceLine":"2.1.30","speaker":"LORD POLONIUS","id":"hamlet:2.1:12"},{"kind":"speech","text":"But, my good lord,--","sourceLine":"2.1.38","speaker":"REYNALDO","id":"hamlet:2.1:13"},{"kind":"speech","text":"Wherefore should you do this?","sourceLine":"2.1.39","speaker":"LORD POLONIUS","id":"hamlet:2.1:14"},{"kind":"speech","text":"Ay, my lord,\nI would know that.","sourceLine":"2.1.40","speaker":"REYNALDO","id":"hamlet:2.1:15"},{"kind":"speech","text":"Marry, sir, here's my drift;\nAnd I believe, it is a fetch of wit:\nYou laying these slight sullies on my son,\nAs 'twere a thing a little soil'd i' the working, Mark you,\nYour party in converse, him you would sound,\nHaving ever seen in the prenominate crimes\nThe youth you breathe of guilty, be assured\nHe closes with you in this consequence;\n'Good sir,' or so, or 'friend,' or 'gentleman,'\nAccording to the phrase or the addition\nOf man and country.","sourceLine":"2.1.42","speaker":"LORD POLONIUS","id":"hamlet:2.1:16"},{"kind":"speech","text":"Very good, my lord.","sourceLine":"2.1.53","speaker":"REYNALDO","id":"hamlet:2.1:17"},{"kind":"speech","text":"And then, sir, does he this--he does--what was I\nabout to say? By the mass, I was about to say\nsomething: where did I leave?","sourceLine":"2.1.54","speaker":"LORD POLONIUS","id":"hamlet:2.1:18"},{"kind":"speech","text":"At 'closes in the consequence,' at 'friend or so,'\nand 'gentleman.'","sourceLine":"2.1.57","speaker":"REYNALDO","id":"hamlet:2.1:19"},{"kind":"speech","text":"At 'closes in the consequence,' ay, marry;\nHe closes thus: 'I know the gentleman;\nI saw him yesterday, or t' other day,\nOr then, or then; with such, or such; and, as you say,\nThere was a' gaming; there o'ertook in's rouse;\nThere falling out at tennis:' or perchance,\n'I saw him enter such a house of sale,'\nVidelicet, a brothel, or so forth.\nSee you now;\nYour bait of falsehood takes this carp of truth:\nAnd thus do we of wisdom and of reach,\nWith windlasses and with assays of bias,\nBy indirections find directions out:\nSo by my former lecture and advice,\nShall you my son. You have me, have you not?","sourceLine":"2.1.59","speaker":"LORD POLONIUS","id":"hamlet:2.1:20"},{"kind":"speech","text":"My lord, I have.","sourceLine":"2.1.74","speaker":"REYNALDO","id":"hamlet:2.1:21"},{"kind":"speech","text":"God be wi' you; fare you well.","sourceLine":"2.1.75","speaker":"LORD POLONIUS","id":"hamlet:2.1:22"},{"kind":"speech","text":"Good my lord!","sourceLine":"2.1.76","speaker":"REYNALDO","id":"hamlet:2.1:23"},{"kind":"speech","text":"Observe his inclination in yourself.","sourceLine":"2.1.77","speaker":"LORD POLONIUS","id":"hamlet:2.1:24"},{"kind":"speech","text":"I shall, my lord.","sourceLine":"2.1.78","speaker":"REYNALDO","id":"hamlet:2.1:25"},{"kind":"speech","text":"And let him ply his music.","sourceLine":"2.1.79","speaker":"LORD POLONIUS","id":"hamlet:2.1:26"},{"kind":"speech","text":"Well, my lord.","sourceLine":"2.1.80","speaker":"REYNALDO","id":"hamlet:2.1:27"},{"kind":"speech","text":"Farewell!","sourceLine":"2.1.81","speaker":"LORD POLONIUS","id":"hamlet:2.1:28"},{"kind":"stage","text":"Exit REYNALDO","id":"hamlet:2.1:29"},{"kind":"stage","text":"Enter OPHELIA","id":"hamlet:2.1:30"},{"kind":"speech","text":"How now, Ophelia! what's the matter?","sourceLine":"2.1.82","speaker":"LORD POLONIUS","id":"hamlet:2.1:31"},{"kind":"speech","text":"O, my lord, my lord, I have been so affrighted!","sourceLine":"2.1.83","speaker":"OPHELIA","id":"hamlet:2.1:32"},{"kind":"speech","text":"With what, i' the name of God?","sourceLine":"2.1.84","speaker":"LORD POLONIUS","id":"hamlet:2.1:33"},{"kind":"speech","text":"My lord, as I was sewing in my closet,\nLord Hamlet, with his doublet all unbraced;\nNo hat upon his head; his stockings foul'd,\nUngarter'd, and down-gyved to his ancle;\nPale as his shirt; his knees knocking each other;\nAnd with a look so piteous in purport\nAs if he had been loosed out of hell\nTo speak of horrors,--he comes before me.","sourceLine":"2.1.85","speaker":"OPHELIA","id":"hamlet:2.1:34"},{"kind":"speech","text":"Mad for thy love?","sourceLine":"2.1.93","speaker":"LORD POLONIUS","id":"hamlet:2.1:35"},{"kind":"speech","text":"My lord, I do not know;\nBut truly, I do fear it.","sourceLine":"2.1.94","speaker":"OPHELIA","id":"hamlet:2.1:36"},{"kind":"speech","text":"What said he?","sourceLine":"2.1.96","speaker":"LORD POLONIUS","id":"hamlet:2.1:37"},{"kind":"speech","text":"He took me by the wrist and held me hard;\nThen goes he to the length of all his arm;\nAnd, with his other hand thus o'er his brow,\nHe falls to such perusal of my face\nAs he would draw it. Long stay'd he so;\nAt last, a little shaking of mine arm\nAnd thrice his head thus waving up and down,\nHe raised a sigh so piteous and profound\nAs it did seem to shatter all his bulk\nAnd end his being: that done, he lets me go:\nAnd, with his head over his shoulder turn'd,\nHe seem'd to find his way without his eyes;\nFor out o' doors he went without their helps,\nAnd, to the last, bended their light on me.","sourceLine":"2.1.97","speaker":"OPHELIA","id":"hamlet:2.1:38"},{"kind":"speech","text":"Come, go with me: I will go seek the king.\nThis is the very ecstasy of love,\nWhose violent property fordoes itself\nAnd leads the will to desperate undertakings\nAs oft as any passion under heaven\nThat does afflict our natures. I am sorry.\nWhat, have you given him any hard words of late?","sourceLine":"2.1.111","speaker":"LORD POLONIUS","id":"hamlet:2.1:39"},{"kind":"speech","text":"No, my good lord, but, as you did command,\nI did repel his fetters and denied\nHis access to me.","sourceLine":"2.1.118","speaker":"OPHELIA","id":"hamlet:2.1:40"},{"kind":"speech","text":"That hath made him mad.\nI am sorry that with better heed and judgment\nI had not quoted him: I fear'd he did but trifle,\nAnd meant to wreck thee; but, beshrew my jealousy!\nBy heaven, it is as proper to our age\nTo cast beyond ourselves in our opinions\nAs it is common for the younger sort\nTo lack discretion. Come, go we to the king:\nThis must be known; which, being kept close, might\nmove\nMore grief to hide than hate to utter love.","sourceLine":"2.1.121","speaker":"LORD POLONIUS","id":"hamlet:2.1:41"},{"kind":"stage","text":"Exeunt","id":"hamlet:2.1:42"}],"scene":1},{"id":"2.2","label":"Act 2 · SCENE II. A room in the castle.","act":2,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, QUEEN GERTRUDE, ROSENCRANTZ, GUILDENSTERN, and Attendants","id":"hamlet:2.2:1"},{"kind":"speech","text":"Welcome, dear Rosencrantz and Guildenstern!\nMoreover that we much did long to see you,\nThe need we have to use you did provoke\nOur hasty sending. Something have you heard\nOf Hamlet's transformation; so call it,\nSith nor the exterior nor the inward man\nResembles that it was. What it should be,\nMore than his father's death, that thus hath put him\nSo much from the understanding of himself,\nI cannot dream of: I entreat you both,\nThat, being of so young days brought up with him,\nAnd sith so neighbour'd to his youth and havior,\nThat you vouchsafe your rest here in our court\nSome little time: so by your companies\nTo draw him on to pleasures, and to gather,\nSo much as from occasion you may glean,\nWhether aught, to us unknown, afflicts him thus,\nThat, open'd, lies within our remedy.","sourceLine":"2.2.1","speaker":"KING CLAUDIUS","id":"hamlet:2.2:2"},{"kind":"speech","text":"Good gentlemen, he hath much talk'd of you;\nAnd sure I am two men there are not living\nTo whom he more adheres. If it will please you\nTo show us so much gentry and good will\nAs to expend your time with us awhile,\nFor the supply and profit of our hope,\nYour visitation shall receive such thanks\nAs fits a king's remembrance.","sourceLine":"2.2.19","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:3"},{"kind":"speech","text":"Both your majesties\nMight, by the sovereign power you have of us,\nPut your dread pleasures more into command\nThan to entreaty.","sourceLine":"2.2.27","speaker":"ROSENCRANTZ","id":"hamlet:2.2:4"},{"kind":"speech","text":"But we both obey,\nAnd here give up ourselves, in the full bent\nTo lay our service freely at your feet,\nTo be commanded.","sourceLine":"2.2.31","speaker":"GUILDENSTERN","id":"hamlet:2.2:5"},{"kind":"speech","text":"Thanks, Rosencrantz and gentle Guildenstern.","sourceLine":"2.2.35","speaker":"KING CLAUDIUS","id":"hamlet:2.2:6"},{"kind":"speech","text":"Thanks, Guildenstern and gentle Rosencrantz:\nAnd I beseech you instantly to visit\nMy too much changed son. Go, some of you,\nAnd bring these gentlemen where Hamlet is.","sourceLine":"2.2.36","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:7"},{"kind":"speech","text":"Heavens make our presence and our practises\nPleasant and helpful to him!","sourceLine":"2.2.40","speaker":"GUILDENSTERN","id":"hamlet:2.2:8"},{"kind":"speech","text":"Ay, amen!","sourceLine":"2.2.42","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:9"},{"kind":"stage","text":"Exeunt ROSENCRANTZ, GUILDENSTERN, and some Attendants","id":"hamlet:2.2:10"},{"kind":"stage","text":"Enter POLONIUS","id":"hamlet:2.2:11"},{"kind":"speech","text":"The ambassadors from Norway, my good lord,\nAre joyfully return'd.","sourceLine":"2.2.43","speaker":"LORD POLONIUS","id":"hamlet:2.2:12"},{"kind":"speech","text":"Thou still hast been the father of good news.","sourceLine":"2.2.45","speaker":"KING CLAUDIUS","id":"hamlet:2.2:13"},{"kind":"speech","text":"Have I, my lord? I assure my good liege,\nI hold my duty, as I hold my soul,\nBoth to my God and to my gracious king:\nAnd I do think, or else this brain of mine\nHunts not the trail of policy so sure\nAs it hath used to do, that I have found\nThe very cause of Hamlet's lunacy.","sourceLine":"2.2.46","speaker":"LORD POLONIUS","id":"hamlet:2.2:14"},{"kind":"speech","text":"O, speak of that; that do I long to hear.","sourceLine":"2.2.53","speaker":"KING CLAUDIUS","id":"hamlet:2.2:15"},{"kind":"speech","text":"Give first admittance to the ambassadors;\nMy news shall be the fruit to that great feast.","sourceLine":"2.2.54","speaker":"LORD POLONIUS","id":"hamlet:2.2:16"},{"kind":"speech","text":"Thyself do grace to them, and bring them in.","sourceLine":"2.2.56","speaker":"KING CLAUDIUS","id":"hamlet:2.2:17"},{"kind":"stage","text":"Exit POLONIUS","id":"hamlet:2.2:18"},{"kind":"speech","text":"He tells me, my dear Gertrude, he hath found\nThe head and source of all your son's distemper.","sourceLine":"2.2.57","speaker":"KING CLAUDIUS","id":"hamlet:2.2:19"},{"kind":"speech","text":"I doubt it is no other but the main;\nHis father's death, and our o'erhasty marriage.","sourceLine":"2.2.59","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:20"},{"kind":"speech","text":"Well, we shall sift him.","sourceLine":"2.2.61","speaker":"KING CLAUDIUS","id":"hamlet:2.2:21"},{"kind":"stage","text":"Re-enter POLONIUS, with VOLTIMAND and CORNELIUS","id":"hamlet:2.2:22"},{"kind":"speech","text":"Welcome, my good friends!\nSay, Voltimand, what from our brother Norway?","sourceLine":"2.2.62","speaker":"KING CLAUDIUS","id":"hamlet:2.2:23"},{"kind":"speech","text":"Most fair return of greetings and desires.\nUpon our first, he sent out to suppress\nHis nephew's levies; which to him appear'd\nTo be a preparation 'gainst the Polack;\nBut, better look'd into, he truly found\nIt was against your highness: whereat grieved,\nThat so his sickness, age and impotence\nWas falsely borne in hand, sends out arrests\nOn Fortinbras; which he, in brief, obeys;\nReceives rebuke from Norway, and in fine\nMakes vow before his uncle never more\nTo give the assay of arms against your majesty.\nWhereon old Norway, overcome with joy,\nGives him three thousand crowns in annual fee,\nAnd his commission to employ those soldiers,\nSo levied as before, against the Polack:\nWith an entreaty, herein further shown,","sourceLine":"2.2.64","speaker":"VOLTIMAND","id":"hamlet:2.2:24"},{"kind":"stage","text":"Giving a paper","id":"hamlet:2.2:25"},{"kind":"speech","text":"That it might please you to give quiet pass\nThrough your dominions for this enterprise,\nOn such regards of safety and allowance\nAs therein are set down.","sourceLine":"2.2.81","speaker":"VOLTIMAND","id":"hamlet:2.2:26"},{"kind":"speech","text":"It likes us well;\nAnd at our more consider'd time well read,\nAnswer, and think upon this business.\nMeantime we thank you for your well-took labour:\nGo to your rest; at night we'll feast together:\nMost welcome home!","sourceLine":"2.2.85","speaker":"KING CLAUDIUS","id":"hamlet:2.2:27"},{"kind":"stage","text":"Exeunt VOLTIMAND and CORNELIUS","id":"hamlet:2.2:28"},{"kind":"speech","text":"This business is well ended.\nMy liege, and madam, to expostulate\nWhat majesty should be, what duty is,\nWhy day is day, night night, and time is time,\nWere nothing but to waste night, day and time.\nTherefore, since brevity is the soul of wit,\nAnd tediousness the limbs and outward flourishes,\nI will be brief: your noble son is mad:\nMad call I it; for, to define true madness,\nWhat is't but to be nothing else but mad?\nBut let that go.","sourceLine":"2.2.91","speaker":"LORD POLONIUS","id":"hamlet:2.2:29"},{"kind":"speech","text":"More matter, with less art.","sourceLine":"2.2.102","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:30"},{"kind":"speech","text":"Madam, I swear I use no art at all.\nThat he is mad, 'tis true: 'tis true 'tis pity;\nAnd pity 'tis 'tis true: a foolish figure;\nBut farewell it, for I will use no art.\nMad let us grant him, then: and now remains\nThat we find out the cause of this effect,\nOr rather say, the cause of this defect,\nFor this effect defective comes by cause:\nThus it remains, and the remainder thus. Perpend.\nI have a daughter--have while she is mine--\nWho, in her duty and obedience, mark,\nHath given me this: now gather, and surmise.","sourceLine":"2.2.103","speaker":"LORD POLONIUS","id":"hamlet:2.2:31"},{"kind":"stage","text":"Reads","id":"hamlet:2.2:32"},{"kind":"speech","text":"'To the celestial and my soul's idol, the most\nbeautified Ophelia,'--\nThat's an ill phrase, a vile phrase; 'beautified' is\na vile phrase: but you shall hear. Thus:","sourceLine":"2.2.115","speaker":"LORD POLONIUS","id":"hamlet:2.2:33"},{"kind":"stage","text":"Reads","id":"hamlet:2.2:34"},{"kind":"speech","text":"'In her excellent white bosom, these, & c.'","sourceLine":"2.2.119","speaker":"LORD POLONIUS","id":"hamlet:2.2:35"},{"kind":"speech","text":"Came this from Hamlet to her?","sourceLine":"2.2.120","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:36"},{"kind":"speech","text":"Good madam, stay awhile; I will be faithful.","sourceLine":"2.2.121","speaker":"LORD POLONIUS","id":"hamlet:2.2:37"},{"kind":"stage","text":"Reads","id":"hamlet:2.2:38"},{"kind":"speech","text":"'Doubt thou the stars are fire;\nDoubt that the sun doth move;\nDoubt truth to be a liar;\nBut never doubt I love.\n'O dear Ophelia, I am ill at these numbers;\nI have not art to reckon my groans: but that\nI love thee best, O most best, believe it. Adieu.\n'Thine evermore most dear lady, whilst\nthis machine is to him, HAMLET.'\nThis, in obedience, hath my daughter shown me,\nAnd more above, hath his solicitings,\nAs they fell out by time, by means and place,\nAll given to mine ear.","sourceLine":"2.2.122","speaker":"LORD POLONIUS","id":"hamlet:2.2:39"},{"kind":"speech","text":"But how hath she\nReceived his love?","sourceLine":"2.2.135","speaker":"KING CLAUDIUS","id":"hamlet:2.2:40"},{"kind":"speech","text":"What do you think of me?","sourceLine":"2.2.137","speaker":"LORD POLONIUS","id":"hamlet:2.2:41"},{"kind":"speech","text":"As of a man faithful and honourable.","sourceLine":"2.2.138","speaker":"KING CLAUDIUS","id":"hamlet:2.2:42"},{"kind":"speech","text":"I would fain prove so. But what might you think,\nWhen I had seen this hot love on the wing--\nAs I perceived it, I must tell you that,\nBefore my daughter told me--what might you,\nOr my dear majesty your queen here, think,\nIf I had play'd the desk or table-book,\nOr given my heart a winking, mute and dumb,\nOr look'd upon this love with idle sight;\nWhat might you think? No, I went round to work,\nAnd my young mistress thus I did bespeak:\n'Lord Hamlet is a prince, out of thy star;\nThis must not be:' and then I precepts gave her,\nThat she should lock herself from his resort,\nAdmit no messengers, receive no tokens.\nWhich done, she took the fruits of my advice;\nAnd he, repulsed--a short tale to make--\nFell into a sadness, then into a fast,\nThence to a watch, thence into a weakness,\nThence to a lightness, and, by this declension,\nInto the madness wherein now he raves,\nAnd all we mourn for.","sourceLine":"2.2.139","speaker":"LORD POLONIUS","id":"hamlet:2.2:43"},{"kind":"speech","text":"Do you think 'tis this?","sourceLine":"2.2.160","speaker":"KING CLAUDIUS","id":"hamlet:2.2:44"},{"kind":"speech","text":"It may be, very likely.","sourceLine":"2.2.161","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:45"},{"kind":"speech","text":"Hath there been such a time--I'd fain know that--\nThat I have positively said 'Tis so,'\nWhen it proved otherwise?","sourceLine":"2.2.162","speaker":"LORD POLONIUS","id":"hamlet:2.2:46"},{"kind":"speech","text":"Not that I know.","sourceLine":"2.2.165","speaker":"KING CLAUDIUS","id":"hamlet:2.2:47"},{"kind":"speech","text":"[Pointing to his head and shoulder]\nTake this from this, if this be otherwise:\nIf circumstances lead me, I will find\nWhere truth is hid, though it were hid indeed\nWithin the centre.","sourceLine":"2.2.166","speaker":"LORD POLONIUS","id":"hamlet:2.2:48"},{"kind":"speech","text":"How may we try it further?","sourceLine":"2.2.171","speaker":"KING CLAUDIUS","id":"hamlet:2.2:49"},{"kind":"speech","text":"You know, sometimes he walks four hours together\nHere in the lobby.","sourceLine":"2.2.172","speaker":"LORD POLONIUS","id":"hamlet:2.2:50"},{"kind":"speech","text":"So he does indeed.","sourceLine":"2.2.174","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:51"},{"kind":"speech","text":"At such a time I'll loose my daughter to him:\nBe you and I behind an arras then;\nMark the encounter: if he love her not\nAnd be not from his reason fall'n thereon,\nLet me be no assistant for a state,\nBut keep a farm and carters.","sourceLine":"2.2.175","speaker":"LORD POLONIUS","id":"hamlet:2.2:52"},{"kind":"speech","text":"We will try it.","sourceLine":"2.2.181","speaker":"KING CLAUDIUS","id":"hamlet:2.2:53"},{"kind":"speech","text":"But, look, where sadly the poor wretch comes reading.","sourceLine":"2.2.182","speaker":"QUEEN GERTRUDE","id":"hamlet:2.2:54"},{"kind":"speech","text":"Away, I do beseech you, both away:\nI'll board him presently.","sourceLine":"2.2.183","speaker":"LORD POLONIUS","id":"hamlet:2.2:55"},{"kind":"stage","text":"Exeunt KING CLAUDIUS, QUEEN GERTRUDE, and Attendants","id":"hamlet:2.2:56"},{"kind":"stage","text":"Enter HAMLET, reading","id":"hamlet:2.2:57"},{"kind":"speech","text":"O, give me leave:\nHow does my good Lord Hamlet?","sourceLine":"2.2.185","speaker":"LORD POLONIUS","id":"hamlet:2.2:58"},{"kind":"speech","text":"Well, God-a-mercy.","sourceLine":"2.2.187","speaker":"HAMLET","id":"hamlet:2.2:59"},{"kind":"speech","text":"Do you know me, my lord?","sourceLine":"2.2.188","speaker":"LORD POLONIUS","id":"hamlet:2.2:60"},{"kind":"speech","text":"Excellent well; you are a fishmonger.","sourceLine":"2.2.189","speaker":"HAMLET","id":"hamlet:2.2:61"},{"kind":"speech","text":"Not I, my lord.","sourceLine":"2.2.190","speaker":"LORD POLONIUS","id":"hamlet:2.2:62"},{"kind":"speech","text":"Then I would you were so honest a man.","sourceLine":"2.2.191","speaker":"HAMLET","id":"hamlet:2.2:63"},{"kind":"speech","text":"Honest, my lord!","sourceLine":"2.2.192","speaker":"LORD POLONIUS","id":"hamlet:2.2:64"},{"kind":"speech","text":"Ay, sir; to be honest, as this world goes, is to be\none man picked out of ten thousand.","sourceLine":"2.2.193","speaker":"HAMLET","id":"hamlet:2.2:65"},{"kind":"speech","text":"That's very true, my lord.","sourceLine":"2.2.195","speaker":"LORD POLONIUS","id":"hamlet:2.2:66"},{"kind":"speech","text":"For if the sun breed maggots in a dead dog, being a\ngod kissing carrion,--Have you a daughter?","sourceLine":"2.2.196","speaker":"HAMLET","id":"hamlet:2.2:67"},{"kind":"speech","text":"I have, my lord.","sourceLine":"2.2.198","speaker":"LORD POLONIUS","id":"hamlet:2.2:68"},{"kind":"speech","text":"Let her not walk i' the sun: conception is a\nblessing: but not as your daughter may conceive.\nFriend, look to 't.","sourceLine":"2.2.199","speaker":"HAMLET","id":"hamlet:2.2:69"},{"kind":"speech","text":"[Aside] How say you by that? Still harping on my\ndaughter: yet he knew me not at first; he said I\nwas a fishmonger: he is far gone, far gone: and\ntruly in my youth I suffered much extremity for\nlove; very near this. I'll speak to him again.\nWhat do you read, my lord?","sourceLine":"2.2.202","speaker":"LORD POLONIUS","id":"hamlet:2.2:70"},{"kind":"speech","text":"Words, words, words.","sourceLine":"2.2.208","speaker":"HAMLET","id":"hamlet:2.2:71"},{"kind":"speech","text":"What is the matter, my lord?","sourceLine":"2.2.209","speaker":"LORD POLONIUS","id":"hamlet:2.2:72"},{"kind":"speech","text":"Between who?","sourceLine":"2.2.210","speaker":"HAMLET","id":"hamlet:2.2:73"},{"kind":"speech","text":"I mean, the matter that you read, my lord.","sourceLine":"2.2.211","speaker":"LORD POLONIUS","id":"hamlet:2.2:74"},{"kind":"speech","text":"Slanders, sir: for the satirical rogue says here\nthat old men have grey beards, that their faces are\nwrinkled, their eyes purging thick amber and\nplum-tree gum and that they have a plentiful lack of\nwit, together with most weak hams: all which, sir,\nthough I most powerfully and potently believe, yet\nI hold it not honesty to have it thus set down, for\nyourself, sir, should be old as I am, if like a crab\nyou could go backward.","sourceLine":"2.2.212","speaker":"HAMLET","id":"hamlet:2.2:75"},{"kind":"speech","text":"[Aside] Though this be madness, yet there is method\nin 't. Will you walk out of the air, my lord?","sourceLine":"2.2.221","speaker":"LORD POLONIUS","id":"hamlet:2.2:76"},{"kind":"speech","text":"Into my grave.","sourceLine":"2.2.223","speaker":"HAMLET","id":"hamlet:2.2:77"},{"kind":"speech","text":"Indeed, that is out o' the air.","sourceLine":"2.2.224","speaker":"LORD POLONIUS","id":"hamlet:2.2:78"},{"kind":"stage","text":"Aside","id":"hamlet:2.2:79"},{"kind":"speech","text":"How pregnant sometimes his replies are! a happiness\nthat often madness hits on, which reason and sanity\ncould not so prosperously be delivered of. I will\nleave him, and suddenly contrive the means of\nmeeting between him and my daughter.--My honourable\nlord, I will most humbly take my leave of you.","sourceLine":"2.2.225","speaker":"LORD POLONIUS","id":"hamlet:2.2:80"},{"kind":"speech","text":"You cannot, sir, take from me any thing that I will\nmore willingly part withal: except my life, except\nmy life, except my life.","sourceLine":"2.2.231","speaker":"HAMLET","id":"hamlet:2.2:81"},{"kind":"speech","text":"Fare you well, my lord.","sourceLine":"2.2.234","speaker":"LORD POLONIUS","id":"hamlet:2.2:82"},{"kind":"speech","text":"These tedious old fools!","sourceLine":"2.2.235","speaker":"HAMLET","id":"hamlet:2.2:83"},{"kind":"stage","text":"Enter ROSENCRANTZ and GUILDENSTERN","id":"hamlet:2.2:84"},{"kind":"speech","text":"You go to seek the Lord Hamlet; there he is.","sourceLine":"2.2.236","speaker":"LORD POLONIUS","id":"hamlet:2.2:85"},{"kind":"speech","text":"[To POLONIUS] God save you, sir!","sourceLine":"2.2.237","speaker":"ROSENCRANTZ","id":"hamlet:2.2:86"},{"kind":"stage","text":"Exit POLONIUS","id":"hamlet:2.2:87"},{"kind":"speech","text":"My honoured lord!","sourceLine":"2.2.238","speaker":"GUILDENSTERN","id":"hamlet:2.2:88"},{"kind":"speech","text":"My most dear lord!","sourceLine":"2.2.239","speaker":"ROSENCRANTZ","id":"hamlet:2.2:89"},{"kind":"speech","text":"My excellent good friends! How dost thou,\nGuildenstern? Ah, Rosencrantz! Good lads, how do ye both?","sourceLine":"2.2.240","speaker":"HAMLET","id":"hamlet:2.2:90"},{"kind":"speech","text":"As the indifferent children of the earth.","sourceLine":"2.2.242","speaker":"ROSENCRANTZ","id":"hamlet:2.2:91"},{"kind":"speech","text":"Happy, in that we are not over-happy;\nOn fortune's cap we are not the very button.","sourceLine":"2.2.243","speaker":"GUILDENSTERN","id":"hamlet:2.2:92"},{"kind":"speech","text":"Nor the soles of her shoe?","sourceLine":"2.2.245","speaker":"HAMLET","id":"hamlet:2.2:93"},{"kind":"speech","text":"Neither, my lord.","sourceLine":"2.2.246","speaker":"ROSENCRANTZ","id":"hamlet:2.2:94"},{"kind":"speech","text":"Then you live about her waist, or in the middle of\nher favours?","sourceLine":"2.2.247","speaker":"HAMLET","id":"hamlet:2.2:95"},{"kind":"speech","text":"'Faith, her privates we.","sourceLine":"2.2.249","speaker":"GUILDENSTERN","id":"hamlet:2.2:96"},{"kind":"speech","text":"In the secret parts of fortune? O, most true; she\nis a strumpet. What's the news?","sourceLine":"2.2.250","speaker":"HAMLET","id":"hamlet:2.2:97"},{"kind":"speech","text":"None, my lord, but that the world's grown honest.","sourceLine":"2.2.252","speaker":"ROSENCRANTZ","id":"hamlet:2.2:98"},{"kind":"speech","text":"Then is doomsday near: but your news is not true.\nLet me question more in particular: what have you,\nmy good friends, deserved at the hands of fortune,\nthat she sends you to prison hither?","sourceLine":"2.2.253","speaker":"HAMLET","id":"hamlet:2.2:99"},{"kind":"speech","text":"Prison, my lord!","sourceLine":"2.2.257","speaker":"GUILDENSTERN","id":"hamlet:2.2:100"},{"kind":"speech","text":"Denmark's a prison.","sourceLine":"2.2.258","speaker":"HAMLET","id":"hamlet:2.2:101"},{"kind":"speech","text":"Then is the world one.","sourceLine":"2.2.259","speaker":"ROSENCRANTZ","id":"hamlet:2.2:102"},{"kind":"speech","text":"A goodly one; in which there are many confines,\nwards and dungeons, Denmark being one o' the worst.","sourceLine":"2.2.260","speaker":"HAMLET","id":"hamlet:2.2:103"},{"kind":"speech","text":"We think not so, my lord.","sourceLine":"2.2.262","speaker":"ROSENCRANTZ","id":"hamlet:2.2:104"},{"kind":"speech","text":"Why, then, 'tis none to you; for there is nothing\neither good or bad, but thinking makes it so: to me\nit is a prison.","sourceLine":"2.2.263","speaker":"HAMLET","id":"hamlet:2.2:105"},{"kind":"speech","text":"Why then, your ambition makes it one; 'tis too\nnarrow for your mind.","sourceLine":"2.2.266","speaker":"ROSENCRANTZ","id":"hamlet:2.2:106"},{"kind":"speech","text":"O God, I could be bounded in a nut shell and count\nmyself a king of infinite space, were it not that I\nhave bad dreams.","sourceLine":"2.2.268","speaker":"HAMLET","id":"hamlet:2.2:107"},{"kind":"speech","text":"Which dreams indeed are ambition, for the very\nsubstance of the ambitious is merely the shadow of a dream.","sourceLine":"2.2.271","speaker":"GUILDENSTERN","id":"hamlet:2.2:108"},{"kind":"speech","text":"A dream itself is but a shadow.","sourceLine":"2.2.273","speaker":"HAMLET","id":"hamlet:2.2:109"},{"kind":"speech","text":"Truly, and I hold ambition of so airy and light a\nquality that it is but a shadow's shadow.","sourceLine":"2.2.274","speaker":"ROSENCRANTZ","id":"hamlet:2.2:110"},{"kind":"speech","text":"Then are our beggars bodies, and our monarchs and\noutstretched heroes the beggars' shadows. Shall we\nto the court? for, by my fay, I cannot reason.","sourceLine":"2.2.276","speaker":"HAMLET","id":"hamlet:2.2:111"},{"kind":"speech","text":"We'll wait upon you.","sourceLine":"2.2.279","speaker":"GUILDENSTERN","id":"hamlet:2.2:112"},{"kind":"speech","text":"No such matter: I will not sort you with the rest\nof my servants, for, to speak to you like an honest\nman, I am most dreadfully attended. But, in the\nbeaten way of friendship, what make you at Elsinore?","sourceLine":"2.2.280","speaker":"HAMLET","id":"hamlet:2.2:113"},{"kind":"speech","text":"To visit you, my lord; no other occasion.","sourceLine":"2.2.284","speaker":"ROSENCRANTZ","id":"hamlet:2.2:114"},{"kind":"speech","text":"Beggar that I am, I am even poor in thanks; but I\nthank you: and sure, dear friends, my thanks are\ntoo dear a halfpenny. Were you not sent for? Is it\nyour own inclining? Is it a free visitation? Come,\ndeal justly with me: come, come; nay, speak.","sourceLine":"2.2.285","speaker":"HAMLET","id":"hamlet:2.2:115"},{"kind":"speech","text":"What should we say, my lord?","sourceLine":"2.2.290","speaker":"GUILDENSTERN","id":"hamlet:2.2:116"},{"kind":"speech","text":"Why, any thing, but to the purpose. You were sent\nfor; and there is a kind of confession in your looks\nwhich your modesties have not craft enough to colour:\nI know the good king and queen have sent for you.","sourceLine":"2.2.291","speaker":"HAMLET","id":"hamlet:2.2:117"},{"kind":"speech","text":"To what end, my lord?","sourceLine":"2.2.295","speaker":"ROSENCRANTZ","id":"hamlet:2.2:118"},{"kind":"speech","text":"That you must teach me. But let me conjure you, by\nthe rights of our fellowship, by the consonancy of\nour youth, by the obligation of our ever-preserved\nlove, and by what more dear a better proposer could\ncharge you withal, be even and direct with me,\nwhether you were sent for, or no?","sourceLine":"2.2.296","speaker":"HAMLET","id":"hamlet:2.2:119"},{"kind":"speech","text":"[Aside to GUILDENSTERN] What say you?","sourceLine":"2.2.302","speaker":"ROSENCRANTZ","id":"hamlet:2.2:120"},{"kind":"speech","text":"[Aside] Nay, then, I have an eye of you.--If you\nlove me, hold not off.","sourceLine":"2.2.303","speaker":"HAMLET","id":"hamlet:2.2:121"},{"kind":"speech","text":"My lord, we were sent for.","sourceLine":"2.2.305","speaker":"GUILDENSTERN","id":"hamlet:2.2:122"},{"kind":"speech","text":"I will tell you why; so shall my anticipation\nprevent your discovery, and your secrecy to the king\nand queen moult no feather. I have of late--but\nwherefore I know not--lost all my mirth, forgone all\ncustom of exercises; and indeed it goes so heavily\nwith my disposition that this goodly frame, the\nearth, seems to me a sterile promontory, this most\nexcellent canopy, the air, look you, this brave\no'erhanging firmament, this majestical roof fretted\nwith golden fire, why, it appears no other thing to\nme than a foul and pestilent congregation of vapours.\nWhat a piece of work is a man! how noble in reason!\nhow infinite in faculty! in form and moving how\nexpress and admirable! in action how like an angel!\nin apprehension how like a god! the beauty of the\nworld! the paragon of animals! And yet, to me,\nwhat is this quintessence of dust? man delights not\nme: no, nor woman neither, though by your smiling\nyou seem to say so.","sourceLine":"2.2.306","speaker":"HAMLET","id":"hamlet:2.2:123"},{"kind":"speech","text":"My lord, there was no such stuff in my thoughts.","sourceLine":"2.2.325","speaker":"ROSENCRANTZ","id":"hamlet:2.2:124"},{"kind":"speech","text":"Why did you laugh then, when I said 'man delights not me'?","sourceLine":"2.2.326","speaker":"HAMLET","id":"hamlet:2.2:125"},{"kind":"speech","text":"To think, my lord, if you delight not in man, what\nlenten entertainment the players shall receive from\nyou: we coted them on the way; and hither are they\ncoming, to offer you service.","sourceLine":"2.2.327","speaker":"ROSENCRANTZ","id":"hamlet:2.2:126"},{"kind":"speech","text":"He that plays the king shall be welcome; his majesty\nshall have tribute of me; the adventurous knight\nshall use his foil and target; the lover shall not\nsigh gratis; the humourous man shall end his part\nin peace; the clown shall make those laugh whose\nlungs are tickled o' the sere; and the lady shall\nsay her mind freely, or the blank verse shall halt\nfor't. What players are they?","sourceLine":"2.2.331","speaker":"HAMLET","id":"hamlet:2.2:127"},{"kind":"speech","text":"Even those you were wont to take delight in, the\ntragedians of the city.","sourceLine":"2.2.339","speaker":"ROSENCRANTZ","id":"hamlet:2.2:128"},{"kind":"speech","text":"How chances it they travel? their residence, both\nin reputation and profit, was better both ways.","sourceLine":"2.2.341","speaker":"HAMLET","id":"hamlet:2.2:129"},{"kind":"speech","text":"I think their inhibition comes by the means of the\nlate innovation.","sourceLine":"2.2.343","speaker":"ROSENCRANTZ","id":"hamlet:2.2:130"},{"kind":"speech","text":"Do they hold the same estimation they did when I was\nin the city? are they so followed?","sourceLine":"2.2.345","speaker":"HAMLET","id":"hamlet:2.2:131"},{"kind":"speech","text":"No, indeed, are they not.","sourceLine":"2.2.347","speaker":"ROSENCRANTZ","id":"hamlet:2.2:132"},{"kind":"speech","text":"How comes it? do they grow rusty?","sourceLine":"2.2.348","speaker":"HAMLET","id":"hamlet:2.2:133"},{"kind":"speech","text":"Nay, their endeavour keeps in the wonted pace: but\nthere is, sir, an aery of children, little eyases,\nthat cry out on the top of question, and are most\ntyrannically clapped for't: these are now the\nfashion, and so berattle the common stages--so they\ncall them--that many wearing rapiers are afraid of\ngoose-quills and dare scarce come thither.","sourceLine":"2.2.349","speaker":"ROSENCRANTZ","id":"hamlet:2.2:134"},{"kind":"speech","text":"What, are they children? who maintains 'em? how are\nthey escoted? Will they pursue the quality no\nlonger than they can sing? will they not say\nafterwards, if they should grow themselves to common\nplayers--as it is most like, if their means are no\nbetter--their writers do them wrong, to make them\nexclaim against their own succession?","sourceLine":"2.2.356","speaker":"HAMLET","id":"hamlet:2.2:135"},{"kind":"speech","text":"'Faith, there has been much to do on both sides; and\nthe nation holds it no sin to tarre them to\ncontroversy: there was, for a while, no money bid\nfor argument, unless the poet and the player went to\ncuffs in the question.","sourceLine":"2.2.363","speaker":"ROSENCRANTZ","id":"hamlet:2.2:136"},{"kind":"speech","text":"Is't possible?","sourceLine":"2.2.368","speaker":"HAMLET","id":"hamlet:2.2:137"},{"kind":"speech","text":"O, there has been much throwing about of brains.","sourceLine":"2.2.369","speaker":"GUILDENSTERN","id":"hamlet:2.2:138"},{"kind":"speech","text":"Do the boys carry it away?","sourceLine":"2.2.370","speaker":"HAMLET","id":"hamlet:2.2:139"},{"kind":"speech","text":"Ay, that they do, my lord; Hercules and his load too.","sourceLine":"2.2.371","speaker":"ROSENCRANTZ","id":"hamlet:2.2:140"},{"kind":"speech","text":"It is not very strange; for mine uncle is king of\nDenmark, and those that would make mows at him while\nmy father lived, give twenty, forty, fifty, an\nhundred ducats a-piece for his picture in little.\n'Sblood, there is something in this more than\nnatural, if philosophy could find it out.","sourceLine":"2.2.372","speaker":"HAMLET","id":"hamlet:2.2:141"},{"kind":"stage","text":"Flourish of trumpets within","id":"hamlet:2.2:142"},{"kind":"speech","text":"There are the players.","sourceLine":"2.2.378","speaker":"GUILDENSTERN","id":"hamlet:2.2:143"},{"kind":"speech","text":"Gentlemen, you are welcome to Elsinore. Your hands,\ncome then: the appurtenance of welcome is fashion\nand ceremony: let me comply with you in this garb,\nlest my extent to the players, which, I tell you,\nmust show fairly outward, should more appear like\nentertainment than yours. You are welcome: but my\nuncle-father and aunt-mother are deceived.","sourceLine":"2.2.379","speaker":"HAMLET","id":"hamlet:2.2:144"},{"kind":"speech","text":"In what, my dear lord?","sourceLine":"2.2.386","speaker":"GUILDENSTERN","id":"hamlet:2.2:145"},{"kind":"speech","text":"I am but mad north-north-west: when the wind is\nsoutherly I know a hawk from a handsaw.","sourceLine":"2.2.387","speaker":"HAMLET","id":"hamlet:2.2:146"},{"kind":"stage","text":"Enter POLONIUS","id":"hamlet:2.2:147"},{"kind":"speech","text":"Well be with you, gentlemen!","sourceLine":"2.2.389","speaker":"LORD POLONIUS","id":"hamlet:2.2:148"},{"kind":"speech","text":"Hark you, Guildenstern; and you too: at each ear a\nhearer: that great baby you see there is not yet\nout of his swaddling-clouts.","sourceLine":"2.2.390","speaker":"HAMLET","id":"hamlet:2.2:149"},{"kind":"speech","text":"Happily he's the second time come to them; for they\nsay an old man is twice a child.","sourceLine":"2.2.393","speaker":"ROSENCRANTZ","id":"hamlet:2.2:150"},{"kind":"speech","text":"I will prophesy he comes to tell me of the players;\nmark it. You say right, sir: o' Monday morning;\n'twas so indeed.","sourceLine":"2.2.395","speaker":"HAMLET","id":"hamlet:2.2:151"},{"kind":"speech","text":"My lord, I have news to tell you.","sourceLine":"2.2.398","speaker":"LORD POLONIUS","id":"hamlet:2.2:152"},{"kind":"speech","text":"My lord, I have news to tell you.\nWhen Roscius was an actor in Rome,--","sourceLine":"2.2.399","speaker":"HAMLET","id":"hamlet:2.2:153"},{"kind":"speech","text":"The actors are come hither, my lord.","sourceLine":"2.2.401","speaker":"LORD POLONIUS","id":"hamlet:2.2:154"},{"kind":"speech","text":"Buz, buz!","sourceLine":"2.2.402","speaker":"HAMLET","id":"hamlet:2.2:155"},{"kind":"speech","text":"Upon mine honour,--","sourceLine":"2.2.403","speaker":"LORD POLONIUS","id":"hamlet:2.2:156"},{"kind":"speech","text":"Then came each actor on his ass,--","sourceLine":"2.2.404","speaker":"HAMLET","id":"hamlet:2.2:157"},{"kind":"speech","text":"The best actors in the world, either for tragedy,\ncomedy, history, pastoral, pastoral-comical,\nhistorical-pastoral, tragical-historical, tragical-\ncomical-historical-pastoral, scene individable, or\npoem unlimited: Seneca cannot be too heavy, nor\nPlautus too light. For the law of writ and the\nliberty, these are the only men.","sourceLine":"2.2.405","speaker":"LORD POLONIUS","id":"hamlet:2.2:158"},{"kind":"speech","text":"O Jephthah, judge of Israel, what a treasure hadst thou!","sourceLine":"2.2.412","speaker":"HAMLET","id":"hamlet:2.2:159"},{"kind":"speech","text":"What a treasure had he, my lord?","sourceLine":"2.2.413","speaker":"LORD POLONIUS","id":"hamlet:2.2:160"},{"kind":"speech","text":"Why,\n'One fair daughter and no more,\nThe which he loved passing well.'","sourceLine":"2.2.414","speaker":"HAMLET","id":"hamlet:2.2:161"},{"kind":"speech","text":"[Aside] Still on my daughter.","sourceLine":"2.2.417","speaker":"LORD POLONIUS","id":"hamlet:2.2:162"},{"kind":"speech","text":"Am I not i' the right, old Jephthah?","sourceLine":"2.2.418","speaker":"HAMLET","id":"hamlet:2.2:163"},{"kind":"speech","text":"If you call me Jephthah, my lord, I have a daughter\nthat I love passing well.","sourceLine":"2.2.419","speaker":"LORD POLONIUS","id":"hamlet:2.2:164"},{"kind":"speech","text":"Nay, that follows not.","sourceLine":"2.2.421","speaker":"HAMLET","id":"hamlet:2.2:165"},{"kind":"speech","text":"What follows, then, my lord?","sourceLine":"2.2.422","speaker":"LORD POLONIUS","id":"hamlet:2.2:166"},{"kind":"speech","text":"Why,\n'As by lot, God wot,'\nand then, you know,\n'It came to pass, as most like it was,'--\nthe first row of the pious chanson will show you\nmore; for look, where my abridgement comes.","sourceLine":"2.2.423","speaker":"HAMLET","id":"hamlet:2.2:167"},{"kind":"stage","text":"Enter four or five Players","id":"hamlet:2.2:168"},{"kind":"speech","text":"You are welcome, masters; welcome, all. I am glad\nto see thee well. Welcome, good friends. O, my old\nfriend! thy face is valenced since I saw thee last:\ncomest thou to beard me in Denmark? What, my young\nlady and mistress! By'r lady, your ladyship is\nnearer to heaven than when I saw you last, by the\naltitude of a chopine. Pray God, your voice, like\napiece of uncurrent gold, be not cracked within the\nring. Masters, you are all welcome. We'll e'en\nto't like French falconers, fly at any thing we see:\nwe'll have a speech straight: come, give us a taste\nof your quality; come, a passionate speech.","sourceLine":"2.2.429","speaker":"HAMLET","id":"hamlet:2.2:169"},{"kind":"speech","text":"What speech, my lord?","sourceLine":"2.2.441","speaker":"First Player","id":"hamlet:2.2:170"},{"kind":"speech","text":"I heard thee speak me a speech once, but it was\nnever acted; or, if it was, not above once; for the\nplay, I remember, pleased not the million; 'twas\ncaviare to the general: but it was--as I received\nit, and others, whose judgments in such matters\ncried in the top of mine--an excellent play, well\ndigested in the scenes, set down with as much\nmodesty as cunning. I remember, one said there\nwere no sallets in the lines to make the matter\nsavoury, nor no matter in the phrase that might\nindict the author of affectation; but called it an\nhonest method, as wholesome as sweet, and by very\nmuch more handsome than fine. One speech in it I\nchiefly loved: 'twas Aeneas' tale to Dido; and\nthereabout of it especially, where he speaks of\nPriam's slaughter: if it live in your memory, begin\nat this line: let me see, let me see--\n'The rugged Pyrrhus, like the Hyrcanian beast,'--\nit is not so:--it begins with Pyrrhus:--\n'The rugged Pyrrhus, he whose sable arms,\nBlack as his purpose, did the night resemble\nWhen he lay couched in the ominous horse,\nHath now this dread and black complexion smear'd\nWith heraldry more dismal; head to foot\nNow is he total gules; horridly trick'd\nWith blood of fathers, mothers, daughters, sons,\nBaked and impasted with the parching streets,\nThat lend a tyrannous and damned light\nTo their lord's murder: roasted in wrath and fire,\nAnd thus o'er-sized with coagulate gore,\nWith eyes like carbuncles, the hellish Pyrrhus\nOld grandsire Priam seeks.'\nSo, proceed you.","sourceLine":"2.2.442","speaker":"HAMLET","id":"hamlet:2.2:171"},{"kind":"speech","text":"'Fore God, my lord, well spoken, with good accent and\ngood discretion.","sourceLine":"2.2.475","speaker":"LORD POLONIUS","id":"hamlet:2.2:172"},{"kind":"speech","text":"'Anon he finds him\nStriking too short at Greeks; his antique sword,\nRebellious to his arm, lies where it falls,\nRepugnant to command: unequal match'd,\nPyrrhus at Priam drives; in rage strikes wide;\nBut with the whiff and wind of his fell sword\nThe unnerved father falls. Then senseless Ilium,\nSeeming to feel this blow, with flaming top\nStoops to his base, and with a hideous crash\nTakes prisoner Pyrrhus' ear: for, lo! his sword,\nWhich was declining on the milky head\nOf reverend Priam, seem'd i' the air to stick:\nSo, as a painted tyrant, Pyrrhus stood,\nAnd like a neutral to his will and matter,\nDid nothing.\nBut, as we often see, against some storm,\nA silence in the heavens, the rack stand still,\nThe bold winds speechless and the orb below\nAs hush as death, anon the dreadful thunder\nDoth rend the region, so, after Pyrrhus' pause,\nAroused vengeance sets him new a-work;\nAnd never did the Cyclops' hammers fall\nOn Mars's armour forged for proof eterne\nWith less remorse than Pyrrhus' bleeding sword\nNow falls on Priam.\nOut, out, thou strumpet, Fortune! All you gods,\nIn general synod 'take away her power;\nBreak all the spokes and fellies from her wheel,\nAnd bowl the round nave down the hill of heaven,\nAs low as to the fiends!'","sourceLine":"2.2.477","speaker":"First Player","id":"hamlet:2.2:173"},{"kind":"speech","text":"This is too long.","sourceLine":"2.2.507","speaker":"LORD POLONIUS","id":"hamlet:2.2:174"},{"kind":"speech","text":"It shall to the barber's, with your beard. Prithee,\nsay on: he's for a jig or a tale of bawdry, or he\nsleeps: say on: come to Hecuba.","sourceLine":"2.2.508","speaker":"HAMLET","id":"hamlet:2.2:175"},{"kind":"speech","text":"'But who, O, who had seen the mobled queen--'","sourceLine":"2.2.511","speaker":"First Player","id":"hamlet:2.2:176"},{"kind":"speech","text":"'The mobled queen?'","sourceLine":"2.2.512","speaker":"HAMLET","id":"hamlet:2.2:177"},{"kind":"speech","text":"That's good; 'mobled queen' is good.","sourceLine":"2.2.513","speaker":"LORD POLONIUS","id":"hamlet:2.2:178"},{"kind":"speech","text":"'Run barefoot up and down, threatening the flames\nWith bisson rheum; a clout upon that head\nWhere late the diadem stood, and for a robe,\nAbout her lank and all o'er-teemed loins,\nA blanket, in the alarm of fear caught up;\nWho this had seen, with tongue in venom steep'd,\n'Gainst Fortune's state would treason have\npronounced:\nBut if the gods themselves did see her then\nWhen she saw Pyrrhus make malicious sport\nIn mincing with his sword her husband's limbs,\nThe instant burst of clamour that she made,\nUnless things mortal move them not at all,\nWould have made milch the burning eyes of heaven,\nAnd passion in the gods.'","sourceLine":"2.2.514","speaker":"First Player","id":"hamlet:2.2:179"},{"kind":"speech","text":"Look, whether he has not turned his colour and has\ntears in's eyes. Pray you, no more.","sourceLine":"2.2.529","speaker":"LORD POLONIUS","id":"hamlet:2.2:180"},{"kind":"speech","text":"'Tis well: I'll have thee speak out the rest soon.\nGood my lord, will you see the players well\nbestowed? Do you hear, let them be well used; for\nthey are the abstract and brief chronicles of the\ntime: after your death you were better have a bad\nepitaph than their ill report while you live.","sourceLine":"2.2.531","speaker":"HAMLET","id":"hamlet:2.2:181"},{"kind":"speech","text":"My lord, I will use them according to their desert.","sourceLine":"2.2.537","speaker":"LORD POLONIUS","id":"hamlet:2.2:182"},{"kind":"speech","text":"God's bodykins, man, much better: use every man\nafter his desert, and who should 'scape whipping?\nUse them after your own honour and dignity: the less\nthey deserve, the more merit is in your bounty.\nTake them in.","sourceLine":"2.2.538","speaker":"HAMLET","id":"hamlet:2.2:183"},{"kind":"speech","text":"Come, sirs.","sourceLine":"2.2.543","speaker":"LORD POLONIUS","id":"hamlet:2.2:184"},{"kind":"speech","text":"Follow him, friends: we'll hear a play to-morrow.","sourceLine":"2.2.544","speaker":"HAMLET","id":"hamlet:2.2:185"},{"kind":"stage","text":"Exit POLONIUS with all the Players but the First","id":"hamlet:2.2:186"},{"kind":"speech","text":"Dost thou hear me, old friend; can you play the\nMurder of Gonzago?","sourceLine":"2.2.545","speaker":"HAMLET","id":"hamlet:2.2:187"},{"kind":"speech","text":"Ay, my lord.","sourceLine":"2.2.547","speaker":"First Player","id":"hamlet:2.2:188"},{"kind":"speech","text":"We'll ha't to-morrow night. You could, for a need,\nstudy a speech of some dozen or sixteen lines, which\nI would set down and insert in't, could you not?","sourceLine":"2.2.548","speaker":"HAMLET","id":"hamlet:2.2:189"},{"kind":"speech","text":"Ay, my lord.","sourceLine":"2.2.551","speaker":"First Player","id":"hamlet:2.2:190"},{"kind":"speech","text":"Very well. Follow that lord; and look you mock him\nnot.","sourceLine":"2.2.552","speaker":"HAMLET","id":"hamlet:2.2:191"},{"kind":"stage","text":"Exit First Player","id":"hamlet:2.2:192"},{"kind":"speech","text":"My good friends, I'll leave you till night: you are\nwelcome to Elsinore.","sourceLine":"2.2.554","speaker":"HAMLET","id":"hamlet:2.2:193"},{"kind":"speech","text":"Good my lord!","sourceLine":"2.2.556","speaker":"ROSENCRANTZ","id":"hamlet:2.2:194"},{"kind":"speech","text":"Ay, so, God be wi' ye;","sourceLine":"2.2.557","speaker":"HAMLET","id":"hamlet:2.2:195"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:2.2:196"},{"kind":"speech","text":"Now I am alone.\nO, what a rogue and peasant slave am I!\nIs it not monstrous that this player here,\nBut in a fiction, in a dream of passion,\nCould force his soul so to his own conceit\nThat from her working all his visage wann'd,\nTears in his eyes, distraction in's aspect,\nA broken voice, and his whole function suiting\nWith forms to his conceit? and all for nothing!\nFor Hecuba!\nWhat's Hecuba to him, or he to Hecuba,\nThat he should weep for her? What would he do,\nHad he the motive and the cue for passion\nThat I have? He would drown the stage with tears\nAnd cleave the general ear with horrid speech,\nMake mad the guilty and appal the free,\nConfound the ignorant, and amaze indeed\nThe very faculties of eyes and ears. Yet I,\nA dull and muddy-mettled rascal, peak,\nLike John-a-dreams, unpregnant of my cause,\nAnd can say nothing; no, not for a king,\nUpon whose property and most dear life\nA damn'd defeat was made. Am I a coward?\nWho calls me villain? breaks my pate across?\nPlucks off my beard, and blows it in my face?\nTweaks me by the nose? gives me the lie i' the throat,\nAs deep as to the lungs? who does me this?\nHa!\n'Swounds, I should take it: for it cannot be\nBut I am pigeon-liver'd and lack gall\nTo make oppression bitter, or ere this\nI should have fatted all the region kites\nWith this slave's offal: bloody, bawdy villain!\nRemorseless, treacherous, lecherous, kindless villain!\nO, vengeance!\nWhy, what an ass am I! This is most brave,\nThat I, the son of a dear father murder'd,\nPrompted to my revenge by heaven and hell,\nMust, like a whore, unpack my heart with words,\nAnd fall a-cursing, like a very drab,\nA scullion!\nFie upon't! foh! About, my brain! I have heard\nThat guilty creatures sitting at a play\nHave by the very cunning of the scene\nBeen struck so to the soul that presently\nThey have proclaim'd their malefactions;\nFor murder, though it have no tongue, will speak\nWith most miraculous organ. I'll have these players\nPlay something like the murder of my father\nBefore mine uncle: I'll observe his looks;\nI'll tent him to the quick: if he but blench,\nI know my course. The spirit that I have seen\nMay be the devil: and the devil hath power\nTo assume a pleasing shape; yea, and perhaps\nOut of my weakness and my melancholy,\nAs he is very potent with such spirits,\nAbuses me to damn me: I'll have grounds\nMore relative than this: the play 's the thing\nWherein I'll catch the conscience of the king.","sourceLine":"2.2.558","speaker":"HAMLET","id":"hamlet:2.2:197"},{"kind":"stage","text":"Exit","id":"hamlet:2.2:198"}],"scene":2},{"id":"3.1","label":"Act 3 · SCENE I. A room in the castle.","act":3,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, QUEEN GERTRUDE, POLONIUS, OPHELIA, ROSENCRANTZ, and GUILDENSTERN","id":"hamlet:3.1:1"},{"kind":"speech","text":"And can you, by no drift of circumstance,\nGet from him why he puts on this confusion,\nGrating so harshly all his days of quiet\nWith turbulent and dangerous lunacy?","sourceLine":"3.1.1","speaker":"KING CLAUDIUS","id":"hamlet:3.1:2"},{"kind":"speech","text":"He does confess he feels himself distracted;\nBut from what cause he will by no means speak.","sourceLine":"3.1.5","speaker":"ROSENCRANTZ","id":"hamlet:3.1:3"},{"kind":"speech","text":"Nor do we find him forward to be sounded,\nBut, with a crafty madness, keeps aloof,\nWhen we would bring him on to some confession\nOf his true state.","sourceLine":"3.1.7","speaker":"GUILDENSTERN","id":"hamlet:3.1:4"},{"kind":"speech","text":"Did he receive you well?","sourceLine":"3.1.11","speaker":"QUEEN GERTRUDE","id":"hamlet:3.1:5"},{"kind":"speech","text":"Most like a gentleman.","sourceLine":"3.1.12","speaker":"ROSENCRANTZ","id":"hamlet:3.1:6"},{"kind":"speech","text":"But with much forcing of his disposition.","sourceLine":"3.1.13","speaker":"GUILDENSTERN","id":"hamlet:3.1:7"},{"kind":"speech","text":"Niggard of question; but, of our demands,\nMost free in his reply.","sourceLine":"3.1.14","speaker":"ROSENCRANTZ","id":"hamlet:3.1:8"},{"kind":"speech","text":"Did you assay him?\nTo any pastime?","sourceLine":"3.1.16","speaker":"QUEEN GERTRUDE","id":"hamlet:3.1:9"},{"kind":"speech","text":"Madam, it so fell out, that certain players\nWe o'er-raught on the way: of these we told him;\nAnd there did seem in him a kind of joy\nTo hear of it: they are about the court,\nAnd, as I think, they have already order\nThis night to play before him.","sourceLine":"3.1.18","speaker":"ROSENCRANTZ","id":"hamlet:3.1:10"},{"kind":"speech","text":"'Tis most true:\nAnd he beseech'd me to entreat your majesties\nTo hear and see the matter.","sourceLine":"3.1.24","speaker":"LORD POLONIUS","id":"hamlet:3.1:11"},{"kind":"speech","text":"With all my heart; and it doth much content me\nTo hear him so inclined.\nGood gentlemen, give him a further edge,\nAnd drive his purpose on to these delights.","sourceLine":"3.1.27","speaker":"KING CLAUDIUS","id":"hamlet:3.1:12"},{"kind":"speech","text":"We shall, my lord.","sourceLine":"3.1.31","speaker":"ROSENCRANTZ","id":"hamlet:3.1:13"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:3.1:14"},{"kind":"speech","text":"Sweet Gertrude, leave us too;\nFor we have closely sent for Hamlet hither,\nThat he, as 'twere by accident, may here\nAffront Ophelia:\nHer father and myself, lawful espials,\nWill so bestow ourselves that, seeing, unseen,\nWe may of their encounter frankly judge,\nAnd gather by him, as he is behaved,\nIf 't be the affliction of his love or no\nThat thus he suffers for.","sourceLine":"3.1.32","speaker":"KING CLAUDIUS","id":"hamlet:3.1:15"},{"kind":"speech","text":"I shall obey you.\nAnd for your part, Ophelia, I do wish\nThat your good beauties be the happy cause\nOf Hamlet's wildness: so shall I hope your virtues\nWill bring him to his wonted way again,\nTo both your honours.","sourceLine":"3.1.42","speaker":"QUEEN GERTRUDE","id":"hamlet:3.1:16"},{"kind":"speech","text":"Madam, I wish it may.","sourceLine":"3.1.48","speaker":"OPHELIA","id":"hamlet:3.1:17"},{"kind":"stage","text":"Exit QUEEN GERTRUDE","id":"hamlet:3.1:18"},{"kind":"speech","text":"Ophelia, walk you here. Gracious, so please you,\nWe will bestow ourselves.","sourceLine":"3.1.49","speaker":"LORD POLONIUS","id":"hamlet:3.1:19"},{"kind":"stage","text":"To OPHELIA","id":"hamlet:3.1:20"},{"kind":"speech","text":"Read on this book;\nThat show of such an exercise may colour\nYour loneliness. We are oft to blame in this,--\n'Tis too much proved--that with devotion's visage\nAnd pious action we do sugar o'er\nThe devil himself.","sourceLine":"3.1.51","speaker":"LORD POLONIUS","id":"hamlet:3.1:21"},{"kind":"speech","text":"[Aside] O, 'tis too true!\nHow smart a lash that speech doth give my conscience!\nThe harlot's cheek, beautied with plastering art,\nIs not more ugly to the thing that helps it\nThan is my deed to my most painted word:\nO heavy burthen!","sourceLine":"3.1.57","speaker":"KING CLAUDIUS","id":"hamlet:3.1:22"},{"kind":"speech","text":"I hear him coming: let's withdraw, my lord.","sourceLine":"3.1.63","speaker":"LORD POLONIUS","id":"hamlet:3.1:23"},{"kind":"stage","text":"Exeunt KING CLAUDIUS and POLONIUS","id":"hamlet:3.1:24"},{"kind":"stage","text":"Enter HAMLET","id":"hamlet:3.1:25"},{"kind":"speech","text":"To be, or not to be, that is the question,\nWhether 'tis nobler in the mind to suffer\nThe slings and arrows of outrageous fortune,\nOr to take arms against a sea of troubles,\nAnd by opposing end them? To die: to sleep;\nNo more; and by a sleep to say we end\nThe heart-ache and the thousand natural shocks\nThat flesh is heir to, 'tis a consummation\nDevoutly to be wish'd. To die, to sleep;\nTo sleep: perchance to dream: ay, there's the rub;\nFor in that sleep of death what dreams may come\nWhen we have shuffled off this mortal coil,\nMust give us pause: there's the respect\nThat makes calamity of so long life;\nFor who would bear the whips and scorns of time,\nThe oppressor's wrong, the proud man's contumely,\nThe pangs of despised love, the law's delay,\nThe insolence of office and the spurns\nThat patient merit of the unworthy takes,\nWhen he himself might his quietus make\nWith a bare bodkin? who would fardels bear,\nTo grunt and sweat under a weary life,\nBut that the dread of something after death,\nThe undiscover'd country from whose bourn\nNo traveller returns, puzzles the will\nAnd makes us rather bear those ills we have\nThan fly to others that we know not of?\nThus conscience does make cowards of us all;\nAnd thus the native hue of resolution\nIs sicklied o'er with the pale cast of thought,\nAnd enterprises of great pith and moment\nWith this regard their currents turn awry,\nAnd lose the name of action.--Soft you now!\nThe fair Ophelia! Nymph, in thy orisons\nBe all my sins remember'd.","sourceLine":"3.1.64","speaker":"HAMLET","id":"hamlet:3.1:26"},{"kind":"speech","text":"Good my lord,\nHow does your honour for this many a day?","sourceLine":"3.1.99","speaker":"OPHELIA","id":"hamlet:3.1:27"},{"kind":"speech","text":"I humbly thank you; well, well, well.","sourceLine":"3.1.101","speaker":"HAMLET","id":"hamlet:3.1:28"},{"kind":"speech","text":"My lord, I have remembrances of yours,\nThat I have longed long to re-deliver;\nI pray you, now receive them.","sourceLine":"3.1.102","speaker":"OPHELIA","id":"hamlet:3.1:29"},{"kind":"speech","text":"No, not I;\nI never gave you aught.","sourceLine":"3.1.105","speaker":"HAMLET","id":"hamlet:3.1:30"},{"kind":"speech","text":"My honour'd lord, you know right well you did;\nAnd, with them, words of so sweet breath composed\nAs made the things more rich: their perfume lost,\nTake these again; for to the noble mind\nRich gifts wax poor when givers prove unkind.\nThere, my lord.","sourceLine":"3.1.107","speaker":"OPHELIA","id":"hamlet:3.1:31"},{"kind":"speech","text":"Ha, ha! are you honest?","sourceLine":"3.1.113","speaker":"HAMLET","id":"hamlet:3.1:32"},{"kind":"speech","text":"My lord?","sourceLine":"3.1.114","speaker":"OPHELIA","id":"hamlet:3.1:33"},{"kind":"speech","text":"Are you fair?","sourceLine":"3.1.115","speaker":"HAMLET","id":"hamlet:3.1:34"},{"kind":"speech","text":"What means your lordship?","sourceLine":"3.1.116","speaker":"OPHELIA","id":"hamlet:3.1:35"},{"kind":"speech","text":"That if you be honest and fair, your honesty should\nadmit no discourse to your beauty.","sourceLine":"3.1.117","speaker":"HAMLET","id":"hamlet:3.1:36"},{"kind":"speech","text":"Could beauty, my lord, have better commerce than\nwith honesty?","sourceLine":"3.1.119","speaker":"OPHELIA","id":"hamlet:3.1:37"},{"kind":"speech","text":"Ay, truly; for the power of beauty will sooner\ntransform honesty from what it is to a bawd than the\nforce of honesty can translate beauty into his\nlikeness: this was sometime a paradox, but now the\ntime gives it proof. I did love you once.","sourceLine":"3.1.121","speaker":"HAMLET","id":"hamlet:3.1:38"},{"kind":"speech","text":"Indeed, my lord, you made me believe so.","sourceLine":"3.1.126","speaker":"OPHELIA","id":"hamlet:3.1:39"},{"kind":"speech","text":"You should not have believed me; for virtue cannot\nso inoculate our old stock but we shall relish of\nit: I loved you not.","sourceLine":"3.1.127","speaker":"HAMLET","id":"hamlet:3.1:40"},{"kind":"speech","text":"I was the more deceived.","sourceLine":"3.1.130","speaker":"OPHELIA","id":"hamlet:3.1:41"},{"kind":"speech","text":"Get thee to a nunnery: why wouldst thou be a\nbreeder of sinners? I am myself indifferent honest;\nbut yet I could accuse me of such things that it\nwere better my mother had not borne me: I am very\nproud, revengeful, ambitious, with more offences at\nmy beck than I have thoughts to put them in,\nimagination to give them shape, or time to act them\nin. What should such fellows as I do crawling\nbetween earth and heaven? We are arrant knaves,\nall; believe none of us. Go thy ways to a nunnery.\nWhere's your father?","sourceLine":"3.1.131","speaker":"HAMLET","id":"hamlet:3.1:42"},{"kind":"speech","text":"At home, my lord.","sourceLine":"3.1.142","speaker":"OPHELIA","id":"hamlet:3.1:43"},{"kind":"speech","text":"Let the doors be shut upon him, that he may play the\nfool no where but in's own house. Farewell.","sourceLine":"3.1.143","speaker":"HAMLET","id":"hamlet:3.1:44"},{"kind":"speech","text":"O, help him, you sweet heavens!","sourceLine":"3.1.145","speaker":"OPHELIA","id":"hamlet:3.1:45"},{"kind":"speech","text":"If thou dost marry, I'll give thee this plague for\nthy dowry: be thou as chaste as ice, as pure as\nsnow, thou shalt not escape calumny. Get thee to a\nnunnery, go: farewell. Or, if thou wilt needs\nmarry, marry a fool; for wise men know well enough\nwhat monsters you make of them. To a nunnery, go,\nand quickly too. Farewell.","sourceLine":"3.1.146","speaker":"HAMLET","id":"hamlet:3.1:46"},{"kind":"speech","text":"O heavenly powers, restore him!","sourceLine":"3.1.153","speaker":"OPHELIA","id":"hamlet:3.1:47"},{"kind":"speech","text":"I have heard of your paintings too, well enough; God\nhas given you one face, and you make yourselves\nanother: you jig, you amble, and you lisp, and\nnick-name God's creatures, and make your wantonness\nyour ignorance. Go to, I'll no more on't; it hath\nmade me mad. I say, we will have no more marriages:\nthose that are married already, all but one, shall\nlive; the rest shall keep as they are. To a\nnunnery, go.","sourceLine":"3.1.154","speaker":"HAMLET","id":"hamlet:3.1:48"},{"kind":"stage","text":"Exit","id":"hamlet:3.1:49"},{"kind":"speech","text":"O, what a noble mind is here o'erthrown!\nThe courtier's, soldier's, scholar's, eye, tongue, sword;\nThe expectancy and rose of the fair state,\nThe glass of fashion and the mould of form,\nThe observed of all observers, quite, quite down!\nAnd I, of ladies most deject and wretched,\nThat suck'd the honey of his music vows,\nNow see that noble and most sovereign reason,\nLike sweet bells jangled, out of tune and harsh;\nThat unmatch'd form and feature of blown youth\nBlasted with ecstasy: O, woe is me,\nTo have seen what I have seen, see what I see!","sourceLine":"3.1.163","speaker":"OPHELIA","id":"hamlet:3.1:50"},{"kind":"stage","text":"Re-enter KING CLAUDIUS and POLONIUS","id":"hamlet:3.1:51"},{"kind":"speech","text":"Love! his affections do not that way tend;\nNor what he spake, though it lack'd form a little,\nWas not like madness. There's something in his soul,\nO'er which his melancholy sits on brood;\nAnd I do doubt the hatch and the disclose\nWill be some danger: which for to prevent,\nI have in quick determination\nThus set it down: he shall with speed to England,\nFor the demand of our neglected tribute\nHaply the seas and countries different\nWith variable objects shall expel\nThis something-settled matter in his heart,\nWhereon his brains still beating puts him thus\nFrom fashion of himself. What think you on't?","sourceLine":"3.1.175","speaker":"KING CLAUDIUS","id":"hamlet:3.1:52"},{"kind":"speech","text":"It shall do well: but yet do I believe\nThe origin and commencement of his grief\nSprung from neglected love. How now, Ophelia!\nYou need not tell us what Lord Hamlet said;\nWe heard it all. My lord, do as you please;\nBut, if you hold it fit, after the play\nLet his queen mother all alone entreat him\nTo show his grief: let her be round with him;\nAnd I'll be placed, so please you, in the ear\nOf all their conference. If she find him not,\nTo England send him, or confine him where\nYour wisdom best shall think.","sourceLine":"3.1.189","speaker":"LORD POLONIUS","id":"hamlet:3.1:53"},{"kind":"speech","text":"It shall be so:\nMadness in great ones must not unwatch'd go.","sourceLine":"3.1.201","speaker":"KING CLAUDIUS","id":"hamlet:3.1:54"},{"kind":"stage","text":"Exeunt","id":"hamlet:3.1:55"}],"scene":1},{"id":"3.2","label":"Act 3 · SCENE II. A hall in the castle.","act":3,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter HAMLET and Players","id":"hamlet:3.2:1"},{"kind":"speech","text":"Speak the speech, I pray you, as I pronounced it to\nyou, trippingly on the tongue: but if you mouth it,\nas many of your players do, I had as lief the\ntown-crier spoke my lines. Nor do not saw the air\ntoo much with your hand, thus, but use all gently;\nfor in the very torrent, tempest, and, as I may say,\nthe whirlwind of passion, you must acquire and beget\na temperance that may give it smoothness. O, it\noffends me to the soul to hear a robustious\nperiwig-pated fellow tear a passion to tatters, to\nvery rags, to split the ears of the groundlings, who\nfor the most part are capable of nothing but\ninexplicable dumbshows and noise: I would have such\na fellow whipped for o'erdoing Termagant; it\nout-herods Herod: pray you, avoid it.","sourceLine":"3.2.1","speaker":"HAMLET","id":"hamlet:3.2:2"},{"kind":"speech","text":"I warrant your honour.","sourceLine":"3.2.16","speaker":"First Player","id":"hamlet:3.2:3"},{"kind":"speech","text":"Be not too tame neither, but let your own discretion\nbe your tutor: suit the action to the word, the\nword to the action; with this special o'erstep not\nthe modesty of nature: for any thing so overdone is\nfrom the purpose of playing, whose end, both at the\nfirst and now, was and is, to hold, as 'twere, the\nmirror up to nature; to show virtue her own feature,\nscorn her own image, and the very age and body of\nthe time his form and pressure. Now this overdone,\nor come tardy off, though it make the unskilful\nlaugh, cannot but make the judicious grieve; the\ncensure of the which one must in your allowance\no'erweigh a whole theatre of others. O, there be\nplayers that I have seen play, and heard others\npraise, and that highly, not to speak it profanely,\nthat, neither having the accent of Christians nor\nthe gait of Christian, pagan, nor man, have so\nstrutted and bellowed that I have thought some of\nnature's journeymen had made men and not made them\nwell, they imitated humanity so abominably.","sourceLine":"3.2.17","speaker":"HAMLET","id":"hamlet:3.2:4"},{"kind":"speech","text":"I hope we have reformed that indifferently with us,\nsir.","sourceLine":"3.2.37","speaker":"First Player","id":"hamlet:3.2:5"},{"kind":"speech","text":"O, reform it altogether. And let those that play\nyour clowns speak no more than is set down for them;\nfor there be of them that will themselves laugh, to\nset on some quantity of barren spectators to laugh\ntoo; though, in the mean time, some necessary\nquestion of the play be then to be considered:\nthat's villanous, and shows a most pitiful ambition\nin the fool that uses it. Go, make you ready.","sourceLine":"3.2.39","speaker":"HAMLET","id":"hamlet:3.2:6"},{"kind":"stage","text":"Exeunt Players","id":"hamlet:3.2:7"},{"kind":"stage","text":"Enter POLONIUS, ROSENCRANTZ, and GUILDENSTERN","id":"hamlet:3.2:8"},{"kind":"speech","text":"How now, my lord! I will the king hear this piece of work?","sourceLine":"3.2.47","speaker":"HAMLET","id":"hamlet:3.2:9"},{"kind":"speech","text":"And the queen too, and that presently.","sourceLine":"3.2.48","speaker":"LORD POLONIUS","id":"hamlet:3.2:10"},{"kind":"speech","text":"Bid the players make haste.","sourceLine":"3.2.49","speaker":"HAMLET","id":"hamlet:3.2:11"},{"kind":"stage","text":"Exit POLONIUS","id":"hamlet:3.2:12"},{"kind":"speech","text":"Will you two help to hasten them?","sourceLine":"3.2.50","speaker":"HAMLET","id":"hamlet:3.2:13"},{"kind":"speech","text":"We will, my lord.","sourceLine":"3.2.51","speaker":"GUILDENSTERN","id":"hamlet:3.2:14"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:3.2:15"},{"kind":"speech","text":"What ho! Horatio!","sourceLine":"3.2.52","speaker":"HAMLET","id":"hamlet:3.2:16"},{"kind":"stage","text":"Enter HORATIO","id":"hamlet:3.2:17"},{"kind":"speech","text":"Here, sweet lord, at your service.","sourceLine":"3.2.53","speaker":"HORATIO","id":"hamlet:3.2:18"},{"kind":"speech","text":"Horatio, thou art e'en as just a man\nAs e'er my conversation coped withal.","sourceLine":"3.2.54","speaker":"HAMLET","id":"hamlet:3.2:19"},{"kind":"speech","text":"O, my dear lord,--","sourceLine":"3.2.56","speaker":"HORATIO","id":"hamlet:3.2:20"},{"kind":"speech","text":"Nay, do not think I flatter;\nFor what advancement may I hope from thee\nThat no revenue hast but thy good spirits,\nTo feed and clothe thee? Why should the poor be flatter'd?\nNo, let the candied tongue lick absurd pomp,\nAnd crook the pregnant hinges of the knee\nWhere thrift may follow fawning. Dost thou hear?\nSince my dear soul was mistress of her choice\nAnd could of men distinguish, her election\nHath seal'd thee for herself; for thou hast been\nAs one, in suffering all, that suffers nothing,\nA man that fortune's buffets and rewards\nHast ta'en with equal thanks: and blest are those\nWhose blood and judgment are so well commingled,\nThat they are not a pipe for fortune's finger\nTo sound what stop she please. Give me that man\nThat is not passion's slave, and I will wear him\nIn my heart's core, ay, in my heart of heart,\nAs I do thee.--Something too much of this.--\nThere is a play to-night before the king;\nOne scene of it comes near the circumstance\nWhich I have told thee of my father's death:\nI prithee, when thou seest that act afoot,\nEven with the very comment of thy soul\nObserve mine uncle: if his occulted guilt\nDo not itself unkennel in one speech,\nIt is a damned ghost that we have seen,\nAnd my imaginations are as foul\nAs Vulcan's stithy. Give him heedful note;\nFor I mine eyes will rivet to his face,\nAnd after we will both our judgments join\nIn censure of his seeming.","sourceLine":"3.2.57","speaker":"HAMLET","id":"hamlet:3.2:21"},{"kind":"speech","text":"Well, my lord:\nIf he steal aught the whilst this play is playing,\nAnd 'scape detecting, I will pay the theft.","sourceLine":"3.2.89","speaker":"HORATIO","id":"hamlet:3.2:22"},{"kind":"speech","text":"They are coming to the play; I must be idle:\nGet you a place.","sourceLine":"3.2.92","speaker":"HAMLET","id":"hamlet:3.2:23"},{"kind":"stage","text":"Danish march. A flourish. Enter KING CLAUDIUS, QUEEN GERTRUDE, POLONIUS, OPHELIA, ROSENCRANTZ, GUILDENSTERN, and others","id":"hamlet:3.2:24"},{"kind":"speech","text":"How fares our cousin Hamlet?","sourceLine":"3.2.94","speaker":"KING CLAUDIUS","id":"hamlet:3.2:25"},{"kind":"speech","text":"Excellent, i' faith; of the chameleon's dish: I eat\nthe air, promise-crammed: you cannot feed capons so.","sourceLine":"3.2.95","speaker":"HAMLET","id":"hamlet:3.2:26"},{"kind":"speech","text":"I have nothing with this answer, Hamlet; these words\nare not mine.","sourceLine":"3.2.97","speaker":"KING CLAUDIUS","id":"hamlet:3.2:27"},{"kind":"speech","text":"No, nor mine now.","sourceLine":"3.2.99","speaker":"HAMLET","id":"hamlet:3.2:28"},{"kind":"stage","text":"To POLONIUS","id":"hamlet:3.2:29"},{"kind":"speech","text":"My lord, you played once i' the university, you say?","sourceLine":"3.2.100","speaker":"HAMLET","id":"hamlet:3.2:30"},{"kind":"speech","text":"That did I, my lord; and was accounted a good actor.","sourceLine":"3.2.101","speaker":"LORD POLONIUS","id":"hamlet:3.2:31"},{"kind":"speech","text":"What did you enact?","sourceLine":"3.2.102","speaker":"HAMLET","id":"hamlet:3.2:32"},{"kind":"speech","text":"I did enact Julius Caesar: I was killed i' the\nCapitol; Brutus killed me.","sourceLine":"3.2.103","speaker":"LORD POLONIUS","id":"hamlet:3.2:33"},{"kind":"speech","text":"It was a brute part of him to kill so capital a calf\nthere. Be the players ready?","sourceLine":"3.2.105","speaker":"HAMLET","id":"hamlet:3.2:34"},{"kind":"speech","text":"Ay, my lord; they stay upon your patience.","sourceLine":"3.2.107","speaker":"ROSENCRANTZ","id":"hamlet:3.2:35"},{"kind":"speech","text":"Come hither, my dear Hamlet, sit by me.","sourceLine":"3.2.108","speaker":"QUEEN GERTRUDE","id":"hamlet:3.2:36"},{"kind":"speech","text":"No, good mother, here's metal more attractive.","sourceLine":"3.2.109","speaker":"HAMLET","id":"hamlet:3.2:37"},{"kind":"speech","text":"[To KING CLAUDIUS] O, ho! do you mark that?","sourceLine":"3.2.110","speaker":"LORD POLONIUS","id":"hamlet:3.2:38"},{"kind":"speech","text":"Lady, shall I lie in your lap?","sourceLine":"3.2.111","speaker":"HAMLET","id":"hamlet:3.2:39"},{"kind":"stage","text":"Lying down at OPHELIA's feet","id":"hamlet:3.2:40"},{"kind":"speech","text":"No, my lord.","sourceLine":"3.2.112","speaker":"OPHELIA","id":"hamlet:3.2:41"},{"kind":"speech","text":"I mean, my head upon your lap?","sourceLine":"3.2.113","speaker":"HAMLET","id":"hamlet:3.2:42"},{"kind":"speech","text":"Ay, my lord.","sourceLine":"3.2.114","speaker":"OPHELIA","id":"hamlet:3.2:43"},{"kind":"speech","text":"Do you think I meant country matters?","sourceLine":"3.2.115","speaker":"HAMLET","id":"hamlet:3.2:44"},{"kind":"speech","text":"I think nothing, my lord.","sourceLine":"3.2.116","speaker":"OPHELIA","id":"hamlet:3.2:45"},{"kind":"speech","text":"That's a fair thought to lie between maids' legs.","sourceLine":"3.2.117","speaker":"HAMLET","id":"hamlet:3.2:46"},{"kind":"speech","text":"What is, my lord?","sourceLine":"3.2.118","speaker":"OPHELIA","id":"hamlet:3.2:47"},{"kind":"speech","text":"Nothing.","sourceLine":"3.2.119","speaker":"HAMLET","id":"hamlet:3.2:48"},{"kind":"speech","text":"You are merry, my lord.","sourceLine":"3.2.120","speaker":"OPHELIA","id":"hamlet:3.2:49"},{"kind":"speech","text":"Who, I?","sourceLine":"3.2.121","speaker":"HAMLET","id":"hamlet:3.2:50"},{"kind":"speech","text":"Ay, my lord.","sourceLine":"3.2.122","speaker":"OPHELIA","id":"hamlet:3.2:51"},{"kind":"speech","text":"O God, your only jig-maker. What should a man do\nbut be merry? for, look you, how cheerfully my\nmother looks, and my father died within these two hours.","sourceLine":"3.2.123","speaker":"HAMLET","id":"hamlet:3.2:52"},{"kind":"speech","text":"Nay, 'tis twice two months, my lord.","sourceLine":"3.2.126","speaker":"OPHELIA","id":"hamlet:3.2:53"},{"kind":"speech","text":"So long? Nay then, let the devil wear black, for\nI'll have a suit of sables. O heavens! die two\nmonths ago, and not forgotten yet? Then there's\nhope a great man's memory may outlive his life half\na year: but, by'r lady, he must build churches,\nthen; or else shall he suffer not thinking on, with\nthe hobby-horse, whose epitaph is 'For, O, for, O,\nthe hobby-horse is forgot.'","sourceLine":"3.2.127","speaker":"HAMLET","id":"hamlet:3.2:54"},{"kind":"stage","text":"Hautboys play. The dumb-show enters","id":"hamlet:3.2:55"},{"kind":"stage","text":"Enter a King and a Queen very lovingly; the Queen embracing him, and he her. She kneels, and makes show of protestation unto him. He takes her up, and declines his head upon her neck: lays him down upon a bank of flowers: she, seeing him asleep, leaves him. Anon comes in a fellow, takes off his crown, kisses it, and pours poison in the King's ears, and exit. The Queen returns; finds the King dead, and makes passionate action. The Poisoner, with some two or three Mutes, comes in again, seeming to lament with her. The dead body is carried away. The Poisoner wooes the Queen with gifts: she seems loath and unwilling awhile, but in the end accepts his love","id":"hamlet:3.2:56"},{"kind":"stage","text":"Exeunt","id":"hamlet:3.2:57"},{"kind":"speech","text":"What means this, my lord?","sourceLine":"3.2.135","speaker":"OPHELIA","id":"hamlet:3.2:58"},{"kind":"speech","text":"Marry, this is miching mallecho; it means mischief.","sourceLine":"3.2.136","speaker":"HAMLET","id":"hamlet:3.2:59"},{"kind":"speech","text":"Belike this show imports the argument of the play.","sourceLine":"3.2.137","speaker":"OPHELIA","id":"hamlet:3.2:60"},{"kind":"stage","text":"Enter Prologue","id":"hamlet:3.2:61"},{"kind":"speech","text":"We shall know by this fellow: the players cannot\nkeep counsel; they'll tell all.","sourceLine":"3.2.138","speaker":"HAMLET","id":"hamlet:3.2:62"},{"kind":"speech","text":"Will he tell us what this show meant?","sourceLine":"3.2.140","speaker":"OPHELIA","id":"hamlet:3.2:63"},{"kind":"speech","text":"Ay, or any show that you'll show him: be not you\nashamed to show, he'll not shame to tell you what it means.","sourceLine":"3.2.141","speaker":"HAMLET","id":"hamlet:3.2:64"},{"kind":"speech","text":"You are naught, you are naught: I'll mark the play.","sourceLine":"3.2.143","speaker":"OPHELIA","id":"hamlet:3.2:65"},{"kind":"speech","text":"For us, and for our tragedy,\nHere stooping to your clemency,\nWe beg your hearing patiently.","sourceLine":"3.2.144","speaker":"Prologue","id":"hamlet:3.2:66"},{"kind":"stage","text":"Exit","id":"hamlet:3.2:67"},{"kind":"speech","text":"Is this a prologue, or the posy of a ring?","sourceLine":"3.2.147","speaker":"HAMLET","id":"hamlet:3.2:68"},{"kind":"speech","text":"'Tis brief, my lord.","sourceLine":"3.2.148","speaker":"OPHELIA","id":"hamlet:3.2:69"},{"kind":"speech","text":"As woman's love.","sourceLine":"3.2.149","speaker":"HAMLET","id":"hamlet:3.2:70"},{"kind":"stage","text":"Enter two Players, King and Queen","id":"hamlet:3.2:71"},{"kind":"speech","text":"Full thirty times hath Phoebus' cart gone round\nNeptune's salt wash and Tellus' orbed ground,\nAnd thirty dozen moons with borrow'd sheen\nAbout the world have times twelve thirties been,\nSince love our hearts and Hymen did our hands\nUnite commutual in most sacred bands.","sourceLine":"3.2.150","speaker":"Player King","id":"hamlet:3.2:72"},{"kind":"speech","text":"So many journeys may the sun and moon\nMake us again count o'er ere love be done!\nBut, woe is me, you are so sick of late,\nSo far from cheer and from your former state,\nThat I distrust you. Yet, though I distrust,\nDiscomfort you, my lord, it nothing must:\nFor women's fear and love holds quantity;\nIn neither aught, or in extremity.\nNow, what my love is, proof hath made you know;\nAnd as my love is sized, my fear is so:\nWhere love is great, the littlest doubts are fear;\nWhere little fears grow great, great love grows there.","sourceLine":"3.2.156","speaker":"Player Queen","id":"hamlet:3.2:73"},{"kind":"speech","text":"'Faith, I must leave thee, love, and shortly too;\nMy operant powers their functions leave to do:\nAnd thou shalt live in this fair world behind,\nHonour'd, beloved; and haply one as kind\nFor husband shalt thou--","sourceLine":"3.2.168","speaker":"Player King","id":"hamlet:3.2:74"},{"kind":"speech","text":"O, confound the rest!\nSuch love must needs be treason in my breast:\nIn second husband let me be accurst!\nNone wed the second but who kill'd the first.","sourceLine":"3.2.173","speaker":"Player Queen","id":"hamlet:3.2:75"},{"kind":"speech","text":"[Aside] Wormwood, wormwood.","sourceLine":"3.2.177","speaker":"HAMLET","id":"hamlet:3.2:76"},{"kind":"speech","text":"The instances that second marriage move\nAre base respects of thrift, but none of love:\nA second time I kill my husband dead,\nWhen second husband kisses me in bed.","sourceLine":"3.2.178","speaker":"Player Queen","id":"hamlet:3.2:77"},{"kind":"speech","text":"I do believe you think what now you speak;\nBut what we do determine oft we break.\nPurpose is but the slave to memory,\nOf violent birth, but poor validity;\nWhich now, like fruit unripe, sticks on the tree;\nBut fall, unshaken, when they mellow be.\nMost necessary 'tis that we forget\nTo pay ourselves what to ourselves is debt:\nWhat to ourselves in passion we propose,\nThe passion ending, doth the purpose lose.\nThe violence of either grief or joy\nTheir own enactures with themselves destroy:\nWhere joy most revels, grief doth most lament;\nGrief joys, joy grieves, on slender accident.\nThis world is not for aye, nor 'tis not strange\nThat even our loves should with our fortunes change;\nFor 'tis a question left us yet to prove,\nWhether love lead fortune, or else fortune love.\nThe great man down, you mark his favourite flies;\nThe poor advanced makes friends of enemies.\nAnd hitherto doth love on fortune tend;\nFor who not needs shall never lack a friend,\nAnd who in want a hollow friend doth try,\nDirectly seasons him his enemy.\nBut, orderly to end where I begun,\nOur wills and fates do so contrary run\nThat our devices still are overthrown;\nOur thoughts are ours, their ends none of our own:\nSo think thou wilt no second husband wed;\nBut die thy thoughts when thy first lord is dead.","sourceLine":"3.2.182","speaker":"Player King","id":"hamlet:3.2:78"},{"kind":"speech","text":"Nor earth to me give food, nor heaven light!\nSport and repose lock from me day and night!\nTo desperation turn my trust and hope!\nAn anchor's cheer in prison be my scope!\nEach opposite that blanks the face of joy\nMeet what I would have well and it destroy!\nBoth here and hence pursue me lasting strife,\nIf, once a widow, ever I be wife!","sourceLine":"3.2.212","speaker":"Player Queen","id":"hamlet:3.2:79"},{"kind":"speech","text":"If she should break it now!","sourceLine":"3.2.220","speaker":"HAMLET","id":"hamlet:3.2:80"},{"kind":"speech","text":"'Tis deeply sworn. Sweet, leave me here awhile;\nMy spirits grow dull, and fain I would beguile\nThe tedious day with sleep.","sourceLine":"3.2.221","speaker":"Player King","id":"hamlet:3.2:81"},{"kind":"stage","text":"Sleeps","id":"hamlet:3.2:82"},{"kind":"speech","text":"Sleep rock thy brain,\nAnd never come mischance between us twain!","sourceLine":"3.2.224","speaker":"Player Queen","id":"hamlet:3.2:83"},{"kind":"stage","text":"Exit","id":"hamlet:3.2:84"},{"kind":"speech","text":"Madam, how like you this play?","sourceLine":"3.2.226","speaker":"HAMLET","id":"hamlet:3.2:85"},{"kind":"speech","text":"The lady protests too much, methinks.","sourceLine":"3.2.227","speaker":"QUEEN GERTRUDE","id":"hamlet:3.2:86"},{"kind":"speech","text":"O, but she'll keep her word.","sourceLine":"3.2.228","speaker":"HAMLET","id":"hamlet:3.2:87"},{"kind":"speech","text":"Have you heard the argument? Is there no offence in 't?","sourceLine":"3.2.229","speaker":"KING CLAUDIUS","id":"hamlet:3.2:88"},{"kind":"speech","text":"No, no, they do but jest, poison in jest; no offence\ni' the world.","sourceLine":"3.2.230","speaker":"HAMLET","id":"hamlet:3.2:89"},{"kind":"speech","text":"What do you call the play?","sourceLine":"3.2.232","speaker":"KING CLAUDIUS","id":"hamlet:3.2:90"},{"kind":"speech","text":"The Mouse-trap. Marry, how? Tropically. This play\nis the image of a murder done in Vienna: Gonzago is\nthe duke's name; his wife, Baptista: you shall see\nanon; 'tis a knavish piece of work: but what o'\nthat? your majesty and we that have free souls, it\ntouches us not: let the galled jade wince, our\nwithers are unwrung.","sourceLine":"3.2.233","speaker":"HAMLET","id":"hamlet:3.2:91"},{"kind":"stage","text":"Enter LUCIANUS","id":"hamlet:3.2:92"},{"kind":"speech","text":"This is one Lucianus, nephew to the king.","sourceLine":"3.2.240","speaker":"HAMLET","id":"hamlet:3.2:93"},{"kind":"speech","text":"You are as good as a chorus, my lord.","sourceLine":"3.2.241","speaker":"OPHELIA","id":"hamlet:3.2:94"},{"kind":"speech","text":"I could interpret between you and your love, if I\ncould see the puppets dallying.","sourceLine":"3.2.242","speaker":"HAMLET","id":"hamlet:3.2:95"},{"kind":"speech","text":"You are keen, my lord, you are keen.","sourceLine":"3.2.244","speaker":"OPHELIA","id":"hamlet:3.2:96"},{"kind":"speech","text":"It would cost you a groaning to take off my edge.","sourceLine":"3.2.245","speaker":"HAMLET","id":"hamlet:3.2:97"},{"kind":"speech","text":"Still better, and worse.","sourceLine":"3.2.246","speaker":"OPHELIA","id":"hamlet:3.2:98"},{"kind":"speech","text":"So you must take your husbands. Begin, murderer;\npox, leave thy damnable faces, and begin. Come:\n'the croaking raven doth bellow for revenge.'","sourceLine":"3.2.247","speaker":"HAMLET","id":"hamlet:3.2:99"},{"kind":"speech","text":"Thoughts black, hands apt, drugs fit, and time agreeing;\nConfederate season, else no creature seeing;\nThou mixture rank, of midnight weeds collected,\nWith Hecate's ban thrice blasted, thrice infected,\nThy natural magic and dire property,\nOn wholesome life usurp immediately.","sourceLine":"3.2.250","speaker":"LUCIANUS","id":"hamlet:3.2:100"},{"kind":"stage","text":"Pours the poison into the sleeper's ears","id":"hamlet:3.2:101"},{"kind":"speech","text":"He poisons him i' the garden for's estate. His\nname's Gonzago: the story is extant, and writ in\nchoice Italian: you shall see anon how the murderer\ngets the love of Gonzago's wife.","sourceLine":"3.2.256","speaker":"HAMLET","id":"hamlet:3.2:102"},{"kind":"speech","text":"The king rises.","sourceLine":"3.2.260","speaker":"OPHELIA","id":"hamlet:3.2:103"},{"kind":"speech","text":"What, frighted with false fire!","sourceLine":"3.2.261","speaker":"HAMLET","id":"hamlet:3.2:104"},{"kind":"speech","text":"How fares my lord?","sourceLine":"3.2.262","speaker":"QUEEN GERTRUDE","id":"hamlet:3.2:105"},{"kind":"speech","text":"Give o'er the play.","sourceLine":"3.2.263","speaker":"LORD POLONIUS","id":"hamlet:3.2:106"},{"kind":"speech","text":"Give me some light: away!","sourceLine":"3.2.264","speaker":"KING CLAUDIUS","id":"hamlet:3.2:107"},{"kind":"speech","text":"Lights, lights, lights!","sourceLine":"3.2.265","speaker":"All","id":"hamlet:3.2:108"},{"kind":"stage","text":"Exeunt all but HAMLET and HORATIO","id":"hamlet:3.2:109"},{"kind":"speech","text":"Why, let the stricken deer go weep,\nThe hart ungalled play;\nFor some must watch, while some must sleep:\nSo runs the world away.\nWould not this, sir, and a forest of feathers-- if\nthe rest of my fortunes turn Turk with me--with two\nProvincial roses on my razed shoes, get me a\nfellowship in a cry of players, sir?","sourceLine":"3.2.266","speaker":"HAMLET","id":"hamlet:3.2:110"},{"kind":"speech","text":"Half a share.","sourceLine":"3.2.274","speaker":"HORATIO","id":"hamlet:3.2:111"},{"kind":"speech","text":"A whole one, I.\nFor thou dost know, O Damon dear,\nThis realm dismantled was\nOf Jove himself; and now reigns here\nA very, very--pajock.","sourceLine":"3.2.275","speaker":"HAMLET","id":"hamlet:3.2:112"},{"kind":"speech","text":"You might have rhymed.","sourceLine":"3.2.280","speaker":"HORATIO","id":"hamlet:3.2:113"},{"kind":"speech","text":"O good Horatio, I'll take the ghost's word for a\nthousand pound. Didst perceive?","sourceLine":"3.2.281","speaker":"HAMLET","id":"hamlet:3.2:114"},{"kind":"speech","text":"Very well, my lord.","sourceLine":"3.2.283","speaker":"HORATIO","id":"hamlet:3.2:115"},{"kind":"speech","text":"Upon the talk of the poisoning?","sourceLine":"3.2.284","speaker":"HAMLET","id":"hamlet:3.2:116"},{"kind":"speech","text":"I did very well note him.","sourceLine":"3.2.285","speaker":"HORATIO","id":"hamlet:3.2:117"},{"kind":"speech","text":"Ah, ha! Come, some music! come, the recorders!\nFor if the king like not the comedy,\nWhy then, belike, he likes it not, perdy.\nCome, some music!","sourceLine":"3.2.286","speaker":"HAMLET","id":"hamlet:3.2:118"},{"kind":"stage","text":"Re-enter ROSENCRANTZ and GUILDENSTERN","id":"hamlet:3.2:119"},{"kind":"speech","text":"Good my lord, vouchsafe me a word with you.","sourceLine":"3.2.290","speaker":"GUILDENSTERN","id":"hamlet:3.2:120"},{"kind":"speech","text":"Sir, a whole history.","sourceLine":"3.2.291","speaker":"HAMLET","id":"hamlet:3.2:121"},{"kind":"speech","text":"The king, sir,--","sourceLine":"3.2.292","speaker":"GUILDENSTERN","id":"hamlet:3.2:122"},{"kind":"speech","text":"Ay, sir, what of him?","sourceLine":"3.2.293","speaker":"HAMLET","id":"hamlet:3.2:123"},{"kind":"speech","text":"Is in his retirement marvellous distempered.","sourceLine":"3.2.294","speaker":"GUILDENSTERN","id":"hamlet:3.2:124"},{"kind":"speech","text":"With drink, sir?","sourceLine":"3.2.295","speaker":"HAMLET","id":"hamlet:3.2:125"},{"kind":"speech","text":"No, my lord, rather with choler.","sourceLine":"3.2.296","speaker":"GUILDENSTERN","id":"hamlet:3.2:126"},{"kind":"speech","text":"Your wisdom should show itself more richer to\nsignify this to his doctor; for, for me to put him\nto his purgation would perhaps plunge him into far\nmore choler.","sourceLine":"3.2.297","speaker":"HAMLET","id":"hamlet:3.2:127"},{"kind":"speech","text":"Good my lord, put your discourse into some frame and\nstart not so wildly from my affair.","sourceLine":"3.2.301","speaker":"GUILDENSTERN","id":"hamlet:3.2:128"},{"kind":"speech","text":"I am tame, sir: pronounce.","sourceLine":"3.2.303","speaker":"HAMLET","id":"hamlet:3.2:129"},{"kind":"speech","text":"The queen, your mother, in most great affliction of\nspirit, hath sent me to you.","sourceLine":"3.2.304","speaker":"GUILDENSTERN","id":"hamlet:3.2:130"},{"kind":"speech","text":"You are welcome.","sourceLine":"3.2.306","speaker":"HAMLET","id":"hamlet:3.2:131"},{"kind":"speech","text":"Nay, good my lord, this courtesy is not of the right\nbreed. If it shall please you to make me a\nwholesome answer, I will do your mother's\ncommandment: if not, your pardon and my return\nshall be the end of my business.","sourceLine":"3.2.307","speaker":"GUILDENSTERN","id":"hamlet:3.2:132"},{"kind":"speech","text":"Sir, I cannot.","sourceLine":"3.2.312","speaker":"HAMLET","id":"hamlet:3.2:133"},{"kind":"speech","text":"What, my lord?","sourceLine":"3.2.313","speaker":"GUILDENSTERN","id":"hamlet:3.2:134"},{"kind":"speech","text":"Make you a wholesome answer; my wit's diseased: but,\nsir, such answer as I can make, you shall command;\nor, rather, as you say, my mother: therefore no\nmore, but to the matter: my mother, you say,--","sourceLine":"3.2.314","speaker":"HAMLET","id":"hamlet:3.2:135"},{"kind":"speech","text":"Then thus she says; your behavior hath struck her\ninto amazement and admiration.","sourceLine":"3.2.318","speaker":"ROSENCRANTZ","id":"hamlet:3.2:136"},{"kind":"speech","text":"O wonderful son, that can so astonish a mother! But\nis there no sequel at the heels of this mother's\nadmiration? Impart.","sourceLine":"3.2.320","speaker":"HAMLET","id":"hamlet:3.2:137"},{"kind":"speech","text":"She desires to speak with you in her closet, ere you\ngo to bed.","sourceLine":"3.2.323","speaker":"ROSENCRANTZ","id":"hamlet:3.2:138"},{"kind":"speech","text":"We shall obey, were she ten times our mother. Have\nyou any further trade with us?","sourceLine":"3.2.325","speaker":"HAMLET","id":"hamlet:3.2:139"},{"kind":"speech","text":"My lord, you once did love me.","sourceLine":"3.2.327","speaker":"ROSENCRANTZ","id":"hamlet:3.2:140"},{"kind":"speech","text":"So I do still, by these pickers and stealers.","sourceLine":"3.2.328","speaker":"HAMLET","id":"hamlet:3.2:141"},{"kind":"speech","text":"Good my lord, what is your cause of distemper? you\ndo, surely, bar the door upon your own liberty, if\nyou deny your griefs to your friend.","sourceLine":"3.2.329","speaker":"ROSENCRANTZ","id":"hamlet:3.2:142"},{"kind":"speech","text":"Sir, I lack advancement.","sourceLine":"3.2.332","speaker":"HAMLET","id":"hamlet:3.2:143"},{"kind":"speech","text":"How can that be, when you have the voice of the king\nhimself for your succession in Denmark?","sourceLine":"3.2.333","speaker":"ROSENCRANTZ","id":"hamlet:3.2:144"},{"kind":"speech","text":"Ay, but sir, 'While the grass grows,'--the proverb\nis something musty.","sourceLine":"3.2.335","speaker":"HAMLET","id":"hamlet:3.2:145"},{"kind":"stage","text":"Re-enter Players with recorders","id":"hamlet:3.2:146"},{"kind":"speech","text":"O, the recorders! let me see one. To withdraw with\nyou:--why do you go about to recover the wind of me,\nas if you would drive me into a toil?","sourceLine":"3.2.337","speaker":"HAMLET","id":"hamlet:3.2:147"},{"kind":"speech","text":"O, my lord, if my duty be too bold, my love is too\nunmannerly.","sourceLine":"3.2.340","speaker":"GUILDENSTERN","id":"hamlet:3.2:148"},{"kind":"speech","text":"I do not well understand that. Will you play upon\nthis pipe?","sourceLine":"3.2.342","speaker":"HAMLET","id":"hamlet:3.2:149"},{"kind":"speech","text":"My lord, I cannot.","sourceLine":"3.2.344","speaker":"GUILDENSTERN","id":"hamlet:3.2:150"},{"kind":"speech","text":"I pray you.","sourceLine":"3.2.345","speaker":"HAMLET","id":"hamlet:3.2:151"},{"kind":"speech","text":"Believe me, I cannot.","sourceLine":"3.2.346","speaker":"GUILDENSTERN","id":"hamlet:3.2:152"},{"kind":"speech","text":"I do beseech you.","sourceLine":"3.2.347","speaker":"HAMLET","id":"hamlet:3.2:153"},{"kind":"speech","text":"I know no touch of it, my lord.","sourceLine":"3.2.348","speaker":"GUILDENSTERN","id":"hamlet:3.2:154"},{"kind":"speech","text":"'Tis as easy as lying: govern these ventages with\nyour lingers and thumb, give it breath with your\nmouth, and it will discourse most eloquent music.\nLook you, these are the stops.","sourceLine":"3.2.349","speaker":"HAMLET","id":"hamlet:3.2:155"},{"kind":"speech","text":"But these cannot I command to any utterance of\nharmony; I have not the skill.","sourceLine":"3.2.353","speaker":"GUILDENSTERN","id":"hamlet:3.2:156"},{"kind":"speech","text":"Why, look you now, how unworthy a thing you make of\nme! You would play upon me; you would seem to know\nmy stops; you would pluck out the heart of my\nmystery; you would sound me from my lowest note to\nthe top of my compass: and there is much music,\nexcellent voice, in this little organ; yet cannot\nyou make it speak. 'Sblood, do you think I am\neasier to be played on than a pipe? Call me what\ninstrument you will, though you can fret me, yet you\ncannot play upon me.","sourceLine":"3.2.355","speaker":"HAMLET","id":"hamlet:3.2:157"},{"kind":"stage","text":"Enter POLONIUS","id":"hamlet:3.2:158"},{"kind":"speech","text":"God bless you, sir!","sourceLine":"3.2.365","speaker":"HAMLET","id":"hamlet:3.2:159"},{"kind":"speech","text":"My lord, the queen would speak with you, and\npresently.","sourceLine":"3.2.366","speaker":"LORD POLONIUS","id":"hamlet:3.2:160"},{"kind":"speech","text":"Do you see yonder cloud that's almost in shape of a camel?","sourceLine":"3.2.368","speaker":"HAMLET","id":"hamlet:3.2:161"},{"kind":"speech","text":"By the mass, and 'tis like a camel, indeed.","sourceLine":"3.2.369","speaker":"LORD POLONIUS","id":"hamlet:3.2:162"},{"kind":"speech","text":"Methinks it is like a weasel.","sourceLine":"3.2.370","speaker":"HAMLET","id":"hamlet:3.2:163"},{"kind":"speech","text":"It is backed like a weasel.","sourceLine":"3.2.371","speaker":"LORD POLONIUS","id":"hamlet:3.2:164"},{"kind":"speech","text":"Or like a whale?","sourceLine":"3.2.372","speaker":"HAMLET","id":"hamlet:3.2:165"},{"kind":"speech","text":"Very like a whale.","sourceLine":"3.2.373","speaker":"LORD POLONIUS","id":"hamlet:3.2:166"},{"kind":"speech","text":"Then I will come to my mother by and by. They fool\nme to the top of my bent. I will come by and by.","sourceLine":"3.2.374","speaker":"HAMLET","id":"hamlet:3.2:167"},{"kind":"speech","text":"I will say so.","sourceLine":"3.2.376","speaker":"LORD POLONIUS","id":"hamlet:3.2:168"},{"kind":"speech","text":"By and by is easily said.","sourceLine":"3.2.377","speaker":"HAMLET","id":"hamlet:3.2:169"},{"kind":"stage","text":"Exit POLONIUS","id":"hamlet:3.2:170"},{"kind":"speech","text":"Leave me, friends.","sourceLine":"3.2.378","speaker":"HAMLET","id":"hamlet:3.2:171"},{"kind":"stage","text":"Exeunt all but HAMLET","id":"hamlet:3.2:172"},{"kind":"speech","text":"Tis now the very witching time of night,\nWhen churchyards yawn and hell itself breathes out\nContagion to this world: now could I drink hot blood,\nAnd do such bitter business as the day\nWould quake to look on. Soft! now to my mother.\nO heart, lose not thy nature; let not ever\nThe soul of Nero enter this firm bosom:\nLet me be cruel, not unnatural:\nI will speak daggers to her, but use none;\nMy tongue and soul in this be hypocrites;\nHow in my words soever she be shent,\nTo give them seals never, my soul, consent!","sourceLine":"3.2.379","speaker":"HAMLET","id":"hamlet:3.2:173"},{"kind":"stage","text":"Exit","id":"hamlet:3.2:174"}],"scene":2},{"id":"3.3","label":"Act 3 · SCENE III. A room in the castle.","act":3,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, ROSENCRANTZ, and GUILDENSTERN","id":"hamlet:3.3:1"},{"kind":"speech","text":"I like him not, nor stands it safe with us\nTo let his madness range. Therefore prepare you;\nI your commission will forthwith dispatch,\nAnd he to England shall along with you:\nThe terms of our estate may not endure\nHazard so dangerous as doth hourly grow\nOut of his lunacies.","sourceLine":"3.3.1","speaker":"KING CLAUDIUS","id":"hamlet:3.3:2"},{"kind":"speech","text":"We will ourselves provide:\nMost holy and religious fear it is\nTo keep those many many bodies safe\nThat live and feed upon your majesty.","sourceLine":"3.3.8","speaker":"GUILDENSTERN","id":"hamlet:3.3:3"},{"kind":"speech","text":"The single and peculiar life is bound,\nWith all the strength and armour of the mind,\nTo keep itself from noyance; but much more\nThat spirit upon whose weal depend and rest\nThe lives of many. The cease of majesty\nDies not alone; but, like a gulf, doth draw\nWhat's near it with it: it is a massy wheel,\nFix'd on the summit of the highest mount,\nTo whose huge spokes ten thousand lesser things\nAre mortised and adjoin'd; which, when it falls,\nEach small annexment, petty consequence,\nAttends the boisterous ruin. Never alone\nDid the king sigh, but with a general groan.","sourceLine":"3.3.12","speaker":"ROSENCRANTZ","id":"hamlet:3.3:4"},{"kind":"speech","text":"Arm you, I pray you, to this speedy voyage;\nFor we will fetters put upon this fear,\nWhich now goes too free-footed.","sourceLine":"3.3.25","speaker":"KING CLAUDIUS","id":"hamlet:3.3:5"},{"kind":"speech","text":"We will haste us.","sourceLine":"3.3.28","speaker":"GUILDENSTERN","id":"hamlet:3.3:6"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:3.3:7"},{"kind":"stage","text":"Enter POLONIUS","id":"hamlet:3.3:8"},{"kind":"speech","text":"My lord, he's going to his mother's closet:\nBehind the arras I'll convey myself,\nTo hear the process; and warrant she'll tax him home:\nAnd, as you said, and wisely was it said,\n'Tis meet that some more audience than a mother,\nSince nature makes them partial, should o'erhear\nThe speech, of vantage. Fare you well, my liege:\nI'll call upon you ere you go to bed,\nAnd tell you what I know.","sourceLine":"3.3.29","speaker":"LORD POLONIUS","id":"hamlet:3.3:9"},{"kind":"speech","text":"Thanks, dear my lord.","sourceLine":"3.3.38","speaker":"KING CLAUDIUS","id":"hamlet:3.3:10"},{"kind":"stage","text":"Exit POLONIUS","id":"hamlet:3.3:11"},{"kind":"speech","text":"O, my offence is rank it smells to heaven;\nIt hath the primal eldest curse upon't,\nA brother's murder. Pray can I not,\nThough inclination be as sharp as will:\nMy stronger guilt defeats my strong intent;\nAnd, like a man to double business bound,\nI stand in pause where I shall first begin,\nAnd both neglect. What if this cursed hand\nWere thicker than itself with brother's blood,\nIs there not rain enough in the sweet heavens\nTo wash it white as snow? Whereto serves mercy\nBut to confront the visage of offence?\nAnd what's in prayer but this two-fold force,\nTo be forestalled ere we come to fall,\nOr pardon'd being down? Then I'll look up;\nMy fault is past. But, O, what form of prayer\nCan serve my turn? 'Forgive me my foul murder'?\nThat cannot be; since I am still possess'd\nOf those effects for which I did the murder,\nMy crown, mine own ambition and my queen.\nMay one be pardon'd and retain the offence?\nIn the corrupted currents of this world\nOffence's gilded hand may shove by justice,\nAnd oft 'tis seen the wicked prize itself\nBuys out the law: but 'tis not so above;\nThere is no shuffling, there the action lies\nIn his true nature; and we ourselves compell'd,\nEven to the teeth and forehead of our faults,\nTo give in evidence. What then? what rests?\nTry what repentance can: what can it not?\nYet what can it when one can not repent?\nO wretched state! O bosom black as death!\nO limed soul, that, struggling to be free,\nArt more engaged! Help, angels! Make assay!\nBow, stubborn knees; and, heart with strings of steel,\nBe soft as sinews of the newborn babe!\nAll may be well.","sourceLine":"3.3.39","speaker":"KING CLAUDIUS","id":"hamlet:3.3:12"},{"kind":"stage","text":"Retires and kneels","id":"hamlet:3.3:13"},{"kind":"stage","text":"Enter HAMLET","id":"hamlet:3.3:14"},{"kind":"speech","text":"Now might I do it pat, now he is praying;\nAnd now I'll do't. And so he goes to heaven;\nAnd so am I revenged. That would be scann'd:\nA villain kills my father; and for that,\nI, his sole son, do this same villain send\nTo heaven.\nO, this is hire and salary, not revenge.\nHe took my father grossly, full of bread;\nWith all his crimes broad blown, as flush as May;\nAnd how his audit stands who knows save heaven?\nBut in our circumstance and course of thought,\n'Tis heavy with him: and am I then revenged,\nTo take him in the purging of his soul,\nWhen he is fit and season'd for his passage?\nNo!\nUp, sword; and know thou a more horrid hent:\nWhen he is drunk asleep, or in his rage,\nOr in the incestuous pleasure of his bed;\nAt gaming, swearing, or about some act\nThat has no relish of salvation in't;\nThen trip him, that his heels may kick at heaven,\nAnd that his soul may be as damn'd and black\nAs hell, whereto it goes. My mother stays:\nThis physic but prolongs thy sickly days.","sourceLine":"3.3.76","speaker":"HAMLET","id":"hamlet:3.3:15"},{"kind":"stage","text":"Exit","id":"hamlet:3.3:16"},{"kind":"speech","text":"[Rising] My words fly up, my thoughts remain below:\nWords without thoughts never to heaven go.","sourceLine":"3.3.100","speaker":"KING CLAUDIUS","id":"hamlet:3.3:17"},{"kind":"stage","text":"Exit","id":"hamlet:3.3:18"}],"scene":3},{"id":"3.4","label":"Act 3 · SCENE IV. The Queen's closet.","act":3,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter QUEEN GERTRUDE and POLONIUS","id":"hamlet:3.4:1"},{"kind":"speech","text":"He will come straight. Look you lay home to him:\nTell him his pranks have been too broad to bear with,\nAnd that your grace hath screen'd and stood between\nMuch heat and him. I'll sconce me even here.\nPray you, be round with him.","sourceLine":"3.4.1","speaker":"LORD POLONIUS","id":"hamlet:3.4:2"},{"kind":"speech","text":"[Within] Mother, mother, mother!","sourceLine":"3.4.6","speaker":"HAMLET","id":"hamlet:3.4:3"},{"kind":"speech","text":"I'll warrant you,\nFear me not: withdraw, I hear him coming.","sourceLine":"3.4.7","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:4"},{"kind":"stage","text":"POLONIUS hides behind the arras","id":"hamlet:3.4:5"},{"kind":"stage","text":"Enter HAMLET","id":"hamlet:3.4:6"},{"kind":"speech","text":"Now, mother, what's the matter?","sourceLine":"3.4.9","speaker":"HAMLET","id":"hamlet:3.4:7"},{"kind":"speech","text":"Hamlet, thou hast thy father much offended.","sourceLine":"3.4.10","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:8"},{"kind":"speech","text":"Mother, you have my father much offended.","sourceLine":"3.4.11","speaker":"HAMLET","id":"hamlet:3.4:9"},{"kind":"speech","text":"Come, come, you answer with an idle tongue.","sourceLine":"3.4.12","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:10"},{"kind":"speech","text":"Go, go, you question with a wicked tongue.","sourceLine":"3.4.13","speaker":"HAMLET","id":"hamlet:3.4:11"},{"kind":"speech","text":"Why, how now, Hamlet!","sourceLine":"3.4.14","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:12"},{"kind":"speech","text":"What's the matter now?","sourceLine":"3.4.15","speaker":"HAMLET","id":"hamlet:3.4:13"},{"kind":"speech","text":"Have you forgot me?","sourceLine":"3.4.16","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:14"},{"kind":"speech","text":"No, by the rood, not so:\nYou are the queen, your husband's brother's wife;\nAnd--would it were not so!--you are my mother.","sourceLine":"3.4.17","speaker":"HAMLET","id":"hamlet:3.4:15"},{"kind":"speech","text":"Nay, then, I'll set those to you that can speak.","sourceLine":"3.4.20","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:16"},{"kind":"speech","text":"Come, come, and sit you down; you shall not budge;\nYou go not till I set you up a glass\nWhere you may see the inmost part of you.","sourceLine":"3.4.21","speaker":"HAMLET","id":"hamlet:3.4:17"},{"kind":"speech","text":"What wilt thou do? thou wilt not murder me?\nHelp, help, ho!","sourceLine":"3.4.24","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:18"},{"kind":"speech","text":"[Behind] What, ho! help, help, help!","sourceLine":"3.4.26","speaker":"LORD POLONIUS","id":"hamlet:3.4:19"},{"kind":"speech","text":"[Drawing] How now! a rat? Dead, for a ducat, dead!","sourceLine":"3.4.27","speaker":"HAMLET","id":"hamlet:3.4:20"},{"kind":"stage","text":"Makes a pass through the arras","id":"hamlet:3.4:21"},{"kind":"speech","text":"[Behind] O, I am slain!","sourceLine":"3.4.28","speaker":"LORD POLONIUS","id":"hamlet:3.4:22"},{"kind":"stage","text":"Falls and dies","id":"hamlet:3.4:23"},{"kind":"speech","text":"O me, what hast thou done?","sourceLine":"3.4.29","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:24"},{"kind":"speech","text":"Nay, I know not:\nIs it the king?","sourceLine":"3.4.30","speaker":"HAMLET","id":"hamlet:3.4:25"},{"kind":"speech","text":"O, what a rash and bloody deed is this!","sourceLine":"3.4.32","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:26"},{"kind":"speech","text":"A bloody deed! almost as bad, good mother,\nAs kill a king, and marry with his brother.","sourceLine":"3.4.33","speaker":"HAMLET","id":"hamlet:3.4:27"},{"kind":"speech","text":"As kill a king!","sourceLine":"3.4.35","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:28"},{"kind":"speech","text":"Ay, lady, 'twas my word.","sourceLine":"3.4.36","speaker":"HAMLET","id":"hamlet:3.4:29"},{"kind":"stage","text":"Lifts up the array and discovers POLONIUS","id":"hamlet:3.4:30"},{"kind":"speech","text":"Thou wretched, rash, intruding fool, farewell!\nI took thee for thy better: take thy fortune;\nThou find'st to be too busy is some danger.\nLeave wringing of your hands: peace! sit you down,\nAnd let me wring your heart; for so I shall,\nIf it be made of penetrable stuff,\nIf damned custom have not brass'd it so\nThat it is proof and bulwark against sense.","sourceLine":"3.4.37","speaker":"HAMLET","id":"hamlet:3.4:31"},{"kind":"speech","text":"What have I done, that thou darest wag thy tongue\nIn noise so rude against me?","sourceLine":"3.4.45","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:32"},{"kind":"speech","text":"Such an act\nThat blurs the grace and blush of modesty,\nCalls virtue hypocrite, takes off the rose\nFrom the fair forehead of an innocent love\nAnd sets a blister there, makes marriage-vows\nAs false as dicers' oaths: O, such a deed\nAs from the body of contraction plucks\nThe very soul, and sweet religion makes\nA rhapsody of words: heaven's face doth glow:\nYea, this solidity and compound mass,\nWith tristful visage, as against the doom,\nIs thought-sick at the act.","sourceLine":"3.4.47","speaker":"HAMLET","id":"hamlet:3.4:33"},{"kind":"speech","text":"Ay me, what act,\nThat roars so loud, and thunders in the index?","sourceLine":"3.4.59","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:34"},{"kind":"speech","text":"Look here, upon this picture, and on this,\nThe counterfeit presentment of two brothers.\nSee, what a grace was seated on this brow;\nHyperion's curls; the front of Jove himself;\nAn eye like Mars, to threaten and command;\nA station like the herald Mercury\nNew-lighted on a heaven-kissing hill;\nA combination and a form indeed,\nWhere every god did seem to set his seal,\nTo give the world assurance of a man:\nThis was your husband. Look you now, what follows:\nHere is your husband; like a mildew'd ear,\nBlasting his wholesome brother. Have you eyes?\nCould you on this fair mountain leave to feed,\nAnd batten on this moor? Ha! have you eyes?\nYou cannot call it love; for at your age\nThe hey-day in the blood is tame, it's humble,\nAnd waits upon the judgment: and what judgment\nWould step from this to this? Sense, sure, you have,\nElse could you not have motion; but sure, that sense\nIs apoplex'd; for madness would not err,\nNor sense to ecstasy was ne'er so thrall'd\nBut it reserved some quantity of choice,\nTo serve in such a difference. What devil was't\nThat thus hath cozen'd you at hoodman-blind?\nEyes without feeling, feeling without sight,\nEars without hands or eyes, smelling sans all,\nOr but a sickly part of one true sense\nCould not so mope.\nO shame! where is thy blush? Rebellious hell,\nIf thou canst mutine in a matron's bones,\nTo flaming youth let virtue be as wax,\nAnd melt in her own fire: proclaim no shame\nWhen the compulsive ardour gives the charge,\nSince frost itself as actively doth burn\nAnd reason panders will.","sourceLine":"3.4.61","speaker":"HAMLET","id":"hamlet:3.4:35"},{"kind":"speech","text":"O Hamlet, speak no more:\nThou turn'st mine eyes into my very soul;\nAnd there I see such black and grained spots\nAs will not leave their tinct.","sourceLine":"3.4.97","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:36"},{"kind":"speech","text":"Nay, but to live\nIn the rank sweat of an enseamed bed,\nStew'd in corruption, honeying and making love\nOver the nasty sty,--","sourceLine":"3.4.101","speaker":"HAMLET","id":"hamlet:3.4:37"},{"kind":"speech","text":"O, speak to me no more;\nThese words, like daggers, enter in mine ears;\nNo more, sweet Hamlet!","sourceLine":"3.4.105","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:38"},{"kind":"speech","text":"A murderer and a villain;\nA slave that is not twentieth part the tithe\nOf your precedent lord; a vice of kings;\nA cutpurse of the empire and the rule,\nThat from a shelf the precious diadem stole,\nAnd put it in his pocket!","sourceLine":"3.4.108","speaker":"HAMLET","id":"hamlet:3.4:39"},{"kind":"speech","text":"No more!","sourceLine":"3.4.114","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:40"},{"kind":"speech","text":"A king of shreds and patches,--","sourceLine":"3.4.115","speaker":"HAMLET","id":"hamlet:3.4:41"},{"kind":"stage","text":"Enter Ghost","id":"hamlet:3.4:42"},{"kind":"speech","text":"Save me, and hover o'er me with your wings,\nYou heavenly guards! What would your gracious figure?","sourceLine":"3.4.116","speaker":"HAMLET","id":"hamlet:3.4:43"},{"kind":"speech","text":"Alas, he's mad!","sourceLine":"3.4.118","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:44"},{"kind":"speech","text":"Do you not come your tardy son to chide,\nThat, lapsed in time and passion, lets go by\nThe important acting of your dread command? O, say!","sourceLine":"3.4.119","speaker":"HAMLET","id":"hamlet:3.4:45"},{"kind":"speech","text":"Do not forget: this visitation\nIs but to whet thy almost blunted purpose.\nBut, look, amazement on thy mother sits:\nO, step between her and her fighting soul:\nConceit in weakest bodies strongest works:\nSpeak to her, Hamlet.","sourceLine":"3.4.122","speaker":"Ghost","id":"hamlet:3.4:46"},{"kind":"speech","text":"How is it with you, lady?","sourceLine":"3.4.128","speaker":"HAMLET","id":"hamlet:3.4:47"},{"kind":"speech","text":"Alas, how is't with you,\nThat you do bend your eye on vacancy\nAnd with the incorporal air do hold discourse?\nForth at your eyes your spirits wildly peep;\nAnd, as the sleeping soldiers in the alarm,\nYour bedded hair, like life in excrements,\nStarts up, and stands on end. O gentle son,\nUpon the heat and flame of thy distemper\nSprinkle cool patience. Whereon do you look?","sourceLine":"3.4.129","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:48"},{"kind":"speech","text":"On him, on him! Look you, how pale he glares!\nHis form and cause conjoin'd, preaching to stones,\nWould make them capable. Do not look upon me;\nLest with this piteous action you convert\nMy stern effects: then what I have to do\nWill want true colour; tears perchance for blood.","sourceLine":"3.4.138","speaker":"HAMLET","id":"hamlet:3.4:49"},{"kind":"speech","text":"To whom do you speak this?","sourceLine":"3.4.144","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:50"},{"kind":"speech","text":"Do you see nothing there?","sourceLine":"3.4.145","speaker":"HAMLET","id":"hamlet:3.4:51"},{"kind":"speech","text":"Nothing at all; yet all that is I see.","sourceLine":"3.4.146","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:52"},{"kind":"speech","text":"Nor did you nothing hear?","sourceLine":"3.4.147","speaker":"HAMLET","id":"hamlet:3.4:53"},{"kind":"speech","text":"No, nothing but ourselves.","sourceLine":"3.4.148","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:54"},{"kind":"speech","text":"Why, look you there! look, how it steals away!\nMy father, in his habit as he lived!\nLook, where he goes, even now, out at the portal!","sourceLine":"3.4.149","speaker":"HAMLET","id":"hamlet:3.4:55"},{"kind":"stage","text":"Exit Ghost","id":"hamlet:3.4:56"},{"kind":"speech","text":"This the very coinage of your brain:\nThis bodiless creation ecstasy\nIs very cunning in.","sourceLine":"3.4.152","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:57"},{"kind":"speech","text":"Ecstasy!\nMy pulse, as yours, doth temperately keep time,\nAnd makes as healthful music: it is not madness\nThat I have utter'd: bring me to the test,\nAnd I the matter will re-word; which madness\nWould gambol from. Mother, for love of grace,\nLay not that mattering unction to your soul,\nThat not your trespass, but my madness speaks:\nIt will but skin and film the ulcerous place,\nWhilst rank corruption, mining all within,\nInfects unseen. Confess yourself to heaven;\nRepent what's past; avoid what is to come;\nAnd do not spread the compost on the weeds,\nTo make them ranker. Forgive me this my virtue;\nFor in the fatness of these pursy times\nVirtue itself of vice must pardon beg,\nYea, curb and woo for leave to do him good.","sourceLine":"3.4.155","speaker":"HAMLET","id":"hamlet:3.4:58"},{"kind":"speech","text":"O Hamlet, thou hast cleft my heart in twain.","sourceLine":"3.4.172","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:59"},{"kind":"speech","text":"O, throw away the worser part of it,\nAnd live the purer with the other half.\nGood night: but go not to mine uncle's bed;\nAssume a virtue, if you have it not.\nThat monster, custom, who all sense doth eat,\nOf habits devil, is angel yet in this,\nThat to the use of actions fair and good\nHe likewise gives a frock or livery,\nThat aptly is put on. Refrain to-night,\nAnd that shall lend a kind of easiness\nTo the next abstinence: the next more easy;\nFor use almost can change the stamp of nature,\nAnd either [ ] the devil, or throw him out\nWith wondrous potency. Once more, good night:\nAnd when you are desirous to be bless'd,\nI'll blessing beg of you. For this same lord,","sourceLine":"3.4.173","speaker":"HAMLET","id":"hamlet:3.4:60"},{"kind":"stage","text":"Pointing to POLONIUS","id":"hamlet:3.4:61"},{"kind":"speech","text":"I do repent: but heaven hath pleased it so,\nTo punish me with this and this with me,\nThat I must be their scourge and minister.\nI will bestow him, and will answer well\nThe death I gave him. So, again, good night.\nI must be cruel, only to be kind:\nThus bad begins and worse remains behind.\nOne word more, good lady.","sourceLine":"3.4.189","speaker":"HAMLET","id":"hamlet:3.4:62"},{"kind":"speech","text":"What shall I do?","sourceLine":"3.4.197","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:63"},{"kind":"speech","text":"Not this, by no means, that I bid you do:\nLet the bloat king tempt you again to bed;\nPinch wanton on your cheek; call you his mouse;\nAnd let him, for a pair of reechy kisses,\nOr paddling in your neck with his damn'd fingers,\nMake you to ravel all this matter out,\nThat I essentially am not in madness,\nBut mad in craft. 'Twere good you let him know;\nFor who, that's but a queen, fair, sober, wise,\nWould from a paddock, from a bat, a gib,\nSuch dear concernings hide? who would do so?\nNo, in despite of sense and secrecy,\nUnpeg the basket on the house's top.\nLet the birds fly, and, like the famous ape,\nTo try conclusions, in the basket creep,\nAnd break your own neck down.","sourceLine":"3.4.198","speaker":"HAMLET","id":"hamlet:3.4:64"},{"kind":"speech","text":"Be thou assured, if words be made of breath,\nAnd breath of life, I have no life to breathe\nWhat thou hast said to me.","sourceLine":"3.4.214","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:65"},{"kind":"speech","text":"I must to England; you know that?","sourceLine":"3.4.217","speaker":"HAMLET","id":"hamlet:3.4:66"},{"kind":"speech","text":"Alack,\nI had forgot: 'tis so concluded on.","sourceLine":"3.4.218","speaker":"QUEEN GERTRUDE","id":"hamlet:3.4:67"},{"kind":"speech","text":"There's letters seal'd: and my two schoolfellows,\nWhom I will trust as I will adders fang'd,\nThey bear the mandate; they must sweep my way,\nAnd marshal me to knavery. Let it work;\nFor 'tis the sport to have the engineer\nHoist with his own petard: and 't shall go hard\nBut I will delve one yard below their mines,\nAnd blow them at the moon: O, 'tis most sweet,\nWhen in one line two crafts directly meet.\nThis man shall set me packing:\nI'll lug the guts into the neighbour room.\nMother, good night. Indeed this counsellor\nIs now most still, most secret and most grave,\nWho was in life a foolish prating knave.\nCome, sir, to draw toward an end with you.\nGood night, mother.","sourceLine":"3.4.220","speaker":"HAMLET","id":"hamlet:3.4:68"},{"kind":"stage","text":"Exeunt severally; HAMLET dragging in POLONIUS","id":"hamlet:3.4:69"}],"scene":4},{"id":"4.1","label":"Act 4 · SCENE I. A room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, QUEEN GERTRUDE, ROSENCRANTZ, and GUILDENSTERN","id":"hamlet:4.1:1"},{"kind":"speech","text":"There's matter in these sighs, these profound heaves:\nYou must translate: 'tis fit we understand them.\nWhere is your son?","sourceLine":"4.1.1","speaker":"KING CLAUDIUS","id":"hamlet:4.1:2"},{"kind":"speech","text":"Bestow this place on us a little while.","sourceLine":"4.1.4","speaker":"QUEEN GERTRUDE","id":"hamlet:4.1:3"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:4.1:4"},{"kind":"speech","text":"Ah, my good lord, what have I seen to-night!","sourceLine":"4.1.5","speaker":"QUEEN GERTRUDE","id":"hamlet:4.1:5"},{"kind":"speech","text":"What, Gertrude? How does Hamlet?","sourceLine":"4.1.6","speaker":"KING CLAUDIUS","id":"hamlet:4.1:6"},{"kind":"speech","text":"Mad as the sea and wind, when both contend\nWhich is the mightier: in his lawless fit,\nBehind the arras hearing something stir,\nWhips out his rapier, cries, 'A rat, a rat!'\nAnd, in this brainish apprehension, kills\nThe unseen good old man.","sourceLine":"4.1.7","speaker":"QUEEN GERTRUDE","id":"hamlet:4.1:7"},{"kind":"speech","text":"O heavy deed!\nIt had been so with us, had we been there:\nHis liberty is full of threats to all;\nTo you yourself, to us, to every one.\nAlas, how shall this bloody deed be answer'd?\nIt will be laid to us, whose providence\nShould have kept short, restrain'd and out of haunt,\nThis mad young man: but so much was our love,\nWe would not understand what was most fit;\nBut, like the owner of a foul disease,\nTo keep it from divulging, let it feed\nEven on the pith of Life. Where is he gone?","sourceLine":"4.1.13","speaker":"KING CLAUDIUS","id":"hamlet:4.1:8"},{"kind":"speech","text":"To draw apart the body he hath kill'd:\nO'er whom his very madness, like some ore\nAmong a mineral of metals base,\nShows itself pure; he weeps for what is done.","sourceLine":"4.1.25","speaker":"QUEEN GERTRUDE","id":"hamlet:4.1:9"},{"kind":"speech","text":"O Gertrude, come away!\nThe sun no sooner shall the mountains touch,\nBut we will ship him hence: and this vile deed\nWe must, with all our majesty and skill,\nBoth countenance and excuse. Ho, Guildenstern!","sourceLine":"4.1.29","speaker":"KING CLAUDIUS","id":"hamlet:4.1:10"},{"kind":"stage","text":"Re-enter ROSENCRANTZ and GUILDENSTERN","id":"hamlet:4.1:11"},{"kind":"speech","text":"Friends both, go join you with some further aid:\nHamlet in madness hath Polonius slain,\nAnd from his mother's closet hath he dragg'd him:\nGo seek him out; speak fair, and bring the body\nInto the chapel. I pray you, haste in this.","sourceLine":"4.1.34","speaker":"KING CLAUDIUS","id":"hamlet:4.1:12"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:4.1:13"},{"kind":"speech","text":"Come, Gertrude, we'll call up our wisest friends;\nAnd let them know, both what we mean to do,\nAnd what's untimely done. O, come away!\nMy soul is full of discord and dismay.","sourceLine":"4.1.39","speaker":"KING CLAUDIUS","id":"hamlet:4.1:14"},{"kind":"stage","text":"Exeunt","id":"hamlet:4.1:15"}],"scene":1},{"id":"4.2","label":"Act 4 · SCENE II. Another room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter HAMLET","id":"hamlet:4.2:1"},{"kind":"speech","text":"Safely stowed.","sourceLine":"4.2.1","speaker":"HAMLET","id":"hamlet:4.2:2"},{"kind":"speech","text":"[Within] Hamlet! Lord Hamlet!","sourceLine":"4.2.2","speaker":"GUILDENSTERN:","id":"hamlet:4.2:3"},{"kind":"speech","text":"What noise? who calls on Hamlet?\nO, here they come.","sourceLine":"4.2.3","speaker":"HAMLET","id":"hamlet:4.2:4"},{"kind":"stage","text":"Enter ROSENCRANTZ and GUILDENSTERN","id":"hamlet:4.2:5"},{"kind":"speech","text":"What have you done, my lord, with the dead body?","sourceLine":"4.2.5","speaker":"ROSENCRANTZ","id":"hamlet:4.2:6"},{"kind":"speech","text":"Compounded it with dust, whereto 'tis kin.","sourceLine":"4.2.6","speaker":"HAMLET","id":"hamlet:4.2:7"},{"kind":"speech","text":"Tell us where 'tis, that we may take it thence\nAnd bear it to the chapel.","sourceLine":"4.2.7","speaker":"ROSENCRANTZ","id":"hamlet:4.2:8"},{"kind":"speech","text":"Do not believe it.","sourceLine":"4.2.9","speaker":"HAMLET","id":"hamlet:4.2:9"},{"kind":"speech","text":"Believe what?","sourceLine":"4.2.10","speaker":"ROSENCRANTZ","id":"hamlet:4.2:10"},{"kind":"speech","text":"That I can keep your counsel and not mine own.\nBesides, to be demanded of a sponge! what\nreplication should be made by the son of a king?","sourceLine":"4.2.11","speaker":"HAMLET","id":"hamlet:4.2:11"},{"kind":"speech","text":"Take you me for a sponge, my lord?","sourceLine":"4.2.14","speaker":"ROSENCRANTZ","id":"hamlet:4.2:12"},{"kind":"speech","text":"Ay, sir, that soaks up the king's countenance, his\nrewards, his authorities. But such officers do the\nking best service in the end: he keeps them, like\nan ape, in the corner of his jaw; first mouthed, to\nbe last swallowed: when he needs what you have\ngleaned, it is but squeezing you, and, sponge, you\nshall be dry again.","sourceLine":"4.2.15","speaker":"HAMLET","id":"hamlet:4.2:13"},{"kind":"speech","text":"I understand you not, my lord.","sourceLine":"4.2.22","speaker":"ROSENCRANTZ","id":"hamlet:4.2:14"},{"kind":"speech","text":"I am glad of it: a knavish speech sleeps in a\nfoolish ear.","sourceLine":"4.2.23","speaker":"HAMLET","id":"hamlet:4.2:15"},{"kind":"speech","text":"My lord, you must tell us where the body is, and go\nwith us to the king.","sourceLine":"4.2.25","speaker":"ROSENCRANTZ","id":"hamlet:4.2:16"},{"kind":"speech","text":"The body is with the king, but the king is not with\nthe body. The king is a thing--","sourceLine":"4.2.27","speaker":"HAMLET","id":"hamlet:4.2:17"},{"kind":"speech","text":"A thing, my lord!","sourceLine":"4.2.29","speaker":"GUILDENSTERN","id":"hamlet:4.2:18"},{"kind":"speech","text":"Of nothing: bring me to him. Hide fox, and all after.","sourceLine":"4.2.30","speaker":"HAMLET","id":"hamlet:4.2:19"},{"kind":"stage","text":"Exeunt","id":"hamlet:4.2:20"}],"scene":2},{"id":"4.3","label":"Act 4 · SCENE III. Another room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS, attended","id":"hamlet:4.3:1"},{"kind":"speech","text":"I have sent to seek him, and to find the body.\nHow dangerous is it that this man goes loose!\nYet must not we put the strong law on him:\nHe's loved of the distracted multitude,\nWho like not in their judgment, but their eyes;\nAnd where tis so, the offender's scourge is weigh'd,\nBut never the offence. To bear all smooth and even,\nThis sudden sending him away must seem\nDeliberate pause: diseases desperate grown\nBy desperate appliance are relieved,\nOr not at all.","sourceLine":"4.3.1","speaker":"KING CLAUDIUS","id":"hamlet:4.3:2"},{"kind":"stage","text":"Enter ROSENCRANTZ","id":"hamlet:4.3:3"},{"kind":"speech","text":"How now! what hath befall'n?","sourceLine":"4.3.12","speaker":"KING CLAUDIUS","id":"hamlet:4.3:4"},{"kind":"speech","text":"Where the dead body is bestow'd, my lord,\nWe cannot get from him.","sourceLine":"4.3.13","speaker":"ROSENCRANTZ","id":"hamlet:4.3:5"},{"kind":"speech","text":"But where is he?","sourceLine":"4.3.15","speaker":"KING CLAUDIUS","id":"hamlet:4.3:6"},{"kind":"speech","text":"Without, my lord; guarded, to know your pleasure.","sourceLine":"4.3.16","speaker":"ROSENCRANTZ","id":"hamlet:4.3:7"},{"kind":"speech","text":"Bring him before us.","sourceLine":"4.3.17","speaker":"KING CLAUDIUS","id":"hamlet:4.3:8"},{"kind":"speech","text":"Ho, Guildenstern! bring in my lord.","sourceLine":"4.3.18","speaker":"ROSENCRANTZ","id":"hamlet:4.3:9"},{"kind":"stage","text":"Enter HAMLET and GUILDENSTERN","id":"hamlet:4.3:10"},{"kind":"speech","text":"Now, Hamlet, where's Polonius?","sourceLine":"4.3.19","speaker":"KING CLAUDIUS","id":"hamlet:4.3:11"},{"kind":"speech","text":"At supper.","sourceLine":"4.3.20","speaker":"HAMLET","id":"hamlet:4.3:12"},{"kind":"speech","text":"At supper! where?","sourceLine":"4.3.21","speaker":"KING CLAUDIUS","id":"hamlet:4.3:13"},{"kind":"speech","text":"Not where he eats, but where he is eaten: a certain\nconvocation of politic worms are e'en at him. Your\nworm is your only emperor for diet: we fat all\ncreatures else to fat us, and we fat ourselves for\nmaggots: your fat king and your lean beggar is but\nvariable service, two dishes, but to one table:\nthat's the end.","sourceLine":"4.3.22","speaker":"HAMLET","id":"hamlet:4.3:14"},{"kind":"speech","text":"Alas, alas!","sourceLine":"4.3.29","speaker":"KING CLAUDIUS","id":"hamlet:4.3:15"},{"kind":"speech","text":"A man may fish with the worm that hath eat of a\nking, and eat of the fish that hath fed of that worm.","sourceLine":"4.3.30","speaker":"HAMLET","id":"hamlet:4.3:16"},{"kind":"speech","text":"What dost you mean by this?","sourceLine":"4.3.32","speaker":"KING CLAUDIUS","id":"hamlet:4.3:17"},{"kind":"speech","text":"Nothing but to show you how a king may go a\nprogress through the guts of a beggar.","sourceLine":"4.3.33","speaker":"HAMLET","id":"hamlet:4.3:18"},{"kind":"speech","text":"Where is Polonius?","sourceLine":"4.3.35","speaker":"KING CLAUDIUS","id":"hamlet:4.3:19"},{"kind":"speech","text":"In heaven; send hither to see: if your messenger\nfind him not there, seek him i' the other place\nyourself. But indeed, if you find him not within\nthis month, you shall nose him as you go up the\nstairs into the lobby.","sourceLine":"4.3.36","speaker":"HAMLET","id":"hamlet:4.3:20"},{"kind":"speech","text":"Go seek him there.","sourceLine":"4.3.41","speaker":"KING CLAUDIUS","id":"hamlet:4.3:21"},{"kind":"stage","text":"To some Attendants","id":"hamlet:4.3:22"},{"kind":"speech","text":"He will stay till ye come.","sourceLine":"4.3.42","speaker":"HAMLET","id":"hamlet:4.3:23"},{"kind":"stage","text":"Exeunt Attendants","id":"hamlet:4.3:24"},{"kind":"speech","text":"Hamlet, this deed, for thine especial safety,--\nWhich we do tender, as we dearly grieve\nFor that which thou hast done,--must send thee hence\nWith fiery quickness: therefore prepare thyself;\nThe bark is ready, and the wind at help,\nThe associates tend, and every thing is bent\nFor England.","sourceLine":"4.3.43","speaker":"KING CLAUDIUS","id":"hamlet:4.3:25"},{"kind":"speech","text":"For England!","sourceLine":"4.3.50","speaker":"HAMLET","id":"hamlet:4.3:26"},{"kind":"speech","text":"Ay, Hamlet.","sourceLine":"4.3.51","speaker":"KING CLAUDIUS","id":"hamlet:4.3:27"},{"kind":"speech","text":"Good.","sourceLine":"4.3.52","speaker":"HAMLET","id":"hamlet:4.3:28"},{"kind":"speech","text":"So is it, if thou knew'st our purposes.","sourceLine":"4.3.53","speaker":"KING CLAUDIUS","id":"hamlet:4.3:29"},{"kind":"speech","text":"I see a cherub that sees them. But, come; for\nEngland! Farewell, dear mother.","sourceLine":"4.3.54","speaker":"HAMLET","id":"hamlet:4.3:30"},{"kind":"speech","text":"Thy loving father, Hamlet.","sourceLine":"4.3.56","speaker":"KING CLAUDIUS","id":"hamlet:4.3:31"},{"kind":"speech","text":"My mother: father and mother is man and wife; man\nand wife is one flesh; and so, my mother. Come, for England!","sourceLine":"4.3.57","speaker":"HAMLET","id":"hamlet:4.3:32"},{"kind":"stage","text":"Exit","id":"hamlet:4.3:33"},{"kind":"speech","text":"Follow him at foot; tempt him with speed aboard;\nDelay it not; I'll have him hence to-night:\nAway! for every thing is seal'd and done\nThat else leans on the affair: pray you, make haste.","sourceLine":"4.3.59","speaker":"KING CLAUDIUS","id":"hamlet:4.3:34"},{"kind":"stage","text":"Exeunt ROSENCRANTZ and GUILDENSTERN","id":"hamlet:4.3:35"},{"kind":"speech","text":"And, England, if my love thou hold'st at aught--\nAs my great power thereof may give thee sense,\nSince yet thy cicatrice looks raw and red\nAfter the Danish sword, and thy free awe\nPays homage to us--thou mayst not coldly set\nOur sovereign process; which imports at full,\nBy letters congruing to that effect,\nThe present death of Hamlet. Do it, England;\nFor like the hectic in my blood he rages,\nAnd thou must cure me: till I know 'tis done,\nHowe'er my haps, my joys were ne'er begun.","sourceLine":"4.3.63","speaker":"KING CLAUDIUS","id":"hamlet:4.3:36"},{"kind":"stage","text":"Exit","id":"hamlet:4.3:37"}],"scene":3},{"id":"4.4","label":"Act 4 · SCENE IV. A plain in Denmark.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter FORTINBRAS, a Captain, and Soldiers, marching","id":"hamlet:4.4:1"},{"kind":"speech","text":"Go, captain, from me greet the Danish king;\nTell him that, by his licence, Fortinbras\nCraves the conveyance of a promised march\nOver his kingdom. You know the rendezvous.\nIf that his majesty would aught with us,\nWe shall express our duty in his eye;\nAnd let him know so.","sourceLine":"4.4.1","speaker":"PRINCE FORTINBRAS","id":"hamlet:4.4:2"},{"kind":"speech","text":"I will do't, my lord.","sourceLine":"4.4.8","speaker":"Captain","id":"hamlet:4.4:3"},{"kind":"speech","text":"Go softly on.","sourceLine":"4.4.9","speaker":"PRINCE FORTINBRAS","id":"hamlet:4.4:4"},{"kind":"stage","text":"Exeunt FORTINBRAS and Soldiers","id":"hamlet:4.4:5"},{"kind":"stage","text":"Enter HAMLET, ROSENCRANTZ, GUILDENSTERN, and others","id":"hamlet:4.4:6"},{"kind":"speech","text":"Good sir, whose powers are these?","sourceLine":"4.4.10","speaker":"HAMLET","id":"hamlet:4.4:7"},{"kind":"speech","text":"They are of Norway, sir.","sourceLine":"4.4.11","speaker":"Captain","id":"hamlet:4.4:8"},{"kind":"speech","text":"How purposed, sir, I pray you?","sourceLine":"4.4.12","speaker":"HAMLET","id":"hamlet:4.4:9"},{"kind":"speech","text":"Against some part of Poland.","sourceLine":"4.4.13","speaker":"Captain","id":"hamlet:4.4:10"},{"kind":"speech","text":"Who commands them, sir?","sourceLine":"4.4.14","speaker":"HAMLET","id":"hamlet:4.4:11"},{"kind":"speech","text":"The nephews to old Norway, Fortinbras.","sourceLine":"4.4.15","speaker":"Captain","id":"hamlet:4.4:12"},{"kind":"speech","text":"Goes it against the main of Poland, sir,\nOr for some frontier?","sourceLine":"4.4.16","speaker":"HAMLET","id":"hamlet:4.4:13"},{"kind":"speech","text":"Truly to speak, and with no addition,\nWe go to gain a little patch of ground\nThat hath in it no profit but the name.\nTo pay five ducats, five, I would not farm it;\nNor will it yield to Norway or the Pole\nA ranker rate, should it be sold in fee.","sourceLine":"4.4.18","speaker":"Captain","id":"hamlet:4.4:14"},{"kind":"speech","text":"Why, then the Polack never will defend it.","sourceLine":"4.4.24","speaker":"HAMLET","id":"hamlet:4.4:15"},{"kind":"speech","text":"Yes, it is already garrison'd.","sourceLine":"4.4.25","speaker":"Captain","id":"hamlet:4.4:16"},{"kind":"speech","text":"Two thousand souls and twenty thousand ducats\nWill not debate the question of this straw:\nThis is the imposthume of much wealth and peace,\nThat inward breaks, and shows no cause without\nWhy the man dies. I humbly thank you, sir.","sourceLine":"4.4.26","speaker":"HAMLET","id":"hamlet:4.4:17"},{"kind":"speech","text":"God be wi' you, sir.","sourceLine":"4.4.31","speaker":"Captain","id":"hamlet:4.4:18"},{"kind":"stage","text":"Exit","id":"hamlet:4.4:19"},{"kind":"speech","text":"Wilt please you go, my lord?","sourceLine":"4.4.32","speaker":"ROSENCRANTZ","id":"hamlet:4.4:20"},{"kind":"speech","text":"I'll be with you straight go a little before.","sourceLine":"4.4.33","speaker":"HAMLET","id":"hamlet:4.4:21"},{"kind":"stage","text":"Exeunt all except HAMLET","id":"hamlet:4.4:22"},{"kind":"speech","text":"How all occasions do inform against me,\nAnd spur my dull revenge! What is a man,\nIf his chief good and market of his time\nBe but to sleep and feed? a beast, no more.\nSure, he that made us with such large discourse,\nLooking before and after, gave us not\nThat capability and god-like reason\nTo fust in us unused. Now, whether it be\nBestial oblivion, or some craven scruple\nOf thinking too precisely on the event,\nA thought which, quarter'd, hath but one part wisdom\nAnd ever three parts coward, I do not know\nWhy yet I live to say 'This thing's to do;'\nSith I have cause and will and strength and means\nTo do't. Examples gross as earth exhort me:\nWitness this army of such mass and charge\nLed by a delicate and tender prince,\nWhose spirit with divine ambition puff'd\nMakes mouths at the invisible event,\nExposing what is mortal and unsure\nTo all that fortune, death and danger dare,\nEven for an egg-shell. Rightly to be great\nIs not to stir without great argument,\nBut greatly to find quarrel in a straw\nWhen honour's at the stake. How stand I then,\nThat have a father kill'd, a mother stain'd,\nExcitements of my reason and my blood,\nAnd let all sleep? while, to my shame, I see\nThe imminent death of twenty thousand men,\nThat, for a fantasy and trick of fame,\nGo to their graves like beds, fight for a plot\nWhereon the numbers cannot try the cause,\nWhich is not tomb enough and continent\nTo hide the slain? O, from this time forth,\nMy thoughts be bloody, or be nothing worth!","sourceLine":"4.4.34","speaker":"HAMLET","id":"hamlet:4.4:23"},{"kind":"stage","text":"Exit","id":"hamlet:4.4:24"}],"scene":4},{"id":"4.5","label":"Act 4 · SCENE V. Elsinore. A room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter QUEEN GERTRUDE, HORATIO, and a Gentleman","id":"hamlet:4.5:1"},{"kind":"speech","text":"I will not speak with her.","sourceLine":"4.5.1","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:2"},{"kind":"speech","text":"She is importunate, indeed distract:\nHer mood will needs be pitied.","sourceLine":"4.5.2","speaker":"Gentleman","id":"hamlet:4.5:3"},{"kind":"speech","text":"What would she have?","sourceLine":"4.5.4","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:4"},{"kind":"speech","text":"She speaks much of her father; says she hears\nThere's tricks i' the world; and hems, and beats her heart;\nSpurns enviously at straws; speaks things in doubt,\nThat carry but half sense: her speech is nothing,\nYet the unshaped use of it doth move\nThe hearers to collection; they aim at it,\nAnd botch the words up fit to their own thoughts;\nWhich, as her winks, and nods, and gestures\nyield them,\nIndeed would make one think there might be thought,\nThough nothing sure, yet much unhappily.","sourceLine":"4.5.5","speaker":"Gentleman","id":"hamlet:4.5:5"},{"kind":"speech","text":"'Twere good she were spoken with; for she may strew\nDangerous conjectures in ill-breeding minds.","sourceLine":"4.5.16","speaker":"HORATIO","id":"hamlet:4.5:6"},{"kind":"speech","text":"Let her come in.","sourceLine":"4.5.18","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:7"},{"kind":"stage","text":"Exit HORATIO","id":"hamlet:4.5:8"},{"kind":"speech","text":"To my sick soul, as sin's true nature is,\nEach toy seems prologue to some great amiss:\nSo full of artless jealousy is guilt,\nIt spills itself in fearing to be spilt.","sourceLine":"4.5.19","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:9"},{"kind":"stage","text":"Re-enter HORATIO, with OPHELIA","id":"hamlet:4.5:10"},{"kind":"speech","text":"Where is the beauteous majesty of Denmark?","sourceLine":"4.5.23","speaker":"OPHELIA","id":"hamlet:4.5:11"},{"kind":"speech","text":"How now, Ophelia!","sourceLine":"4.5.24","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:12"},{"kind":"speech","text":"[Sings]\nHow should I your true love know\nFrom another one?\nBy his cockle hat and staff,\nAnd his sandal shoon.","sourceLine":"4.5.25","speaker":"OPHELIA","id":"hamlet:4.5:13"},{"kind":"speech","text":"Alas, sweet lady, what imports this song?","sourceLine":"4.5.30","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:14"},{"kind":"speech","text":"Say you? nay, pray you, mark.","sourceLine":"4.5.31","speaker":"OPHELIA","id":"hamlet:4.5:15"},{"kind":"stage","text":"Sings","id":"hamlet:4.5:16"},{"kind":"speech","text":"He is dead and gone, lady,\nHe is dead and gone;\nAt his head a grass-green turf,\nAt his heels a stone.","sourceLine":"4.5.32","speaker":"OPHELIA","id":"hamlet:4.5:17"},{"kind":"speech","text":"Nay, but, Ophelia,--","sourceLine":"4.5.36","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:18"},{"kind":"speech","text":"Pray you, mark.","sourceLine":"4.5.37","speaker":"OPHELIA","id":"hamlet:4.5:19"},{"kind":"stage","text":"Sings","id":"hamlet:4.5:20"},{"kind":"speech","text":"White his shroud as the mountain snow,--","sourceLine":"4.5.38","speaker":"OPHELIA","id":"hamlet:4.5:21"},{"kind":"stage","text":"Enter KING CLAUDIUS","id":"hamlet:4.5:22"},{"kind":"speech","text":"Alas, look here, my lord.","sourceLine":"4.5.39","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:23"},{"kind":"speech","text":"[Sings]\nLarded with sweet flowers\nWhich bewept to the grave did go\nWith true-love showers.","sourceLine":"4.5.40","speaker":"OPHELIA","id":"hamlet:4.5:24"},{"kind":"speech","text":"How do you, pretty lady?","sourceLine":"4.5.44","speaker":"KING CLAUDIUS","id":"hamlet:4.5:25"},{"kind":"speech","text":"Well, God 'ild you! They say the owl was a baker's\ndaughter. Lord, we know what we are, but know not\nwhat we may be. God be at your table!","sourceLine":"4.5.45","speaker":"OPHELIA","id":"hamlet:4.5:26"},{"kind":"speech","text":"Conceit upon her father.","sourceLine":"4.5.48","speaker":"KING CLAUDIUS","id":"hamlet:4.5:27"},{"kind":"speech","text":"Pray you, let's have no words of this; but when they\nask you what it means, say you this:","sourceLine":"4.5.49","speaker":"OPHELIA","id":"hamlet:4.5:28"},{"kind":"stage","text":"Sings","id":"hamlet:4.5:29"},{"kind":"speech","text":"To-morrow is Saint Valentine's day,\nAll in the morning betime,\nAnd I a maid at your window,\nTo be your Valentine.\nThen up he rose, and donn'd his clothes,\nAnd dupp'd the chamber-door;\nLet in the maid, that out a maid\nNever departed more.","sourceLine":"4.5.51","speaker":"OPHELIA","id":"hamlet:4.5:30"},{"kind":"speech","text":"Pretty Ophelia!","sourceLine":"4.5.59","speaker":"KING CLAUDIUS","id":"hamlet:4.5:31"},{"kind":"speech","text":"Indeed, la, without an oath, I'll make an end on't:","sourceLine":"4.5.60","speaker":"OPHELIA","id":"hamlet:4.5:32"},{"kind":"stage","text":"Sings","id":"hamlet:4.5:33"},{"kind":"speech","text":"By Gis and by Saint Charity,\nAlack, and fie for shame!\nYoung men will do't, if they come to't;\nBy cock, they are to blame.\nQuoth she, before you tumbled me,\nYou promised me to wed.\nSo would I ha' done, by yonder sun,\nAn thou hadst not come to my bed.","sourceLine":"4.5.61","speaker":"OPHELIA","id":"hamlet:4.5:34"},{"kind":"speech","text":"How long hath she been thus?","sourceLine":"4.5.69","speaker":"KING CLAUDIUS","id":"hamlet:4.5:35"},{"kind":"speech","text":"I hope all will be well. We must be patient: but I\ncannot choose but weep, to think they should lay him\ni' the cold ground. My brother shall know of it:\nand so I thank you for your good counsel. Come, my\ncoach! Good night, ladies; good night, sweet ladies;\ngood night, good night.","sourceLine":"4.5.70","speaker":"OPHELIA","id":"hamlet:4.5:36"},{"kind":"stage","text":"Exit","id":"hamlet:4.5:37"},{"kind":"speech","text":"Follow her close; give her good watch,\nI pray you.","sourceLine":"4.5.76","speaker":"KING CLAUDIUS","id":"hamlet:4.5:38"},{"kind":"stage","text":"Exit HORATIO","id":"hamlet:4.5:39"},{"kind":"speech","text":"O, this is the poison of deep grief; it springs\nAll from her father's death. O Gertrude, Gertrude,\nWhen sorrows come, they come not single spies\nBut in battalions. First, her father slain:\nNext, your son gone; and he most violent author\nOf his own just remove: the people muddied,\nThick and unwholesome in their thoughts and whispers,\nFor good Polonius' death; and we have done but greenly,\nIn hugger-mugger to inter him: poor Ophelia\nDivided from herself and her fair judgment,\nWithout the which we are pictures, or mere beasts:\nLast, and as much containing as all these,\nHer brother is in secret come from France;\nFeeds on his wonder, keeps himself in clouds,\nAnd wants not buzzers to infect his ear\nWith pestilent speeches of his father's death;\nWherein necessity, of matter beggar'd,\nWill nothing stick our person to arraign\nIn ear and ear. O my dear Gertrude, this,\nLike to a murdering-piece, in many places\nGives me superfluous death.","sourceLine":"4.5.78","speaker":"KING CLAUDIUS","id":"hamlet:4.5:40"},{"kind":"stage","text":"A noise within","id":"hamlet:4.5:41"},{"kind":"speech","text":"Alack, what noise is this?","sourceLine":"4.5.99","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:42"},{"kind":"speech","text":"Where are my Switzers? Let them guard the door.","sourceLine":"4.5.100","speaker":"KING CLAUDIUS","id":"hamlet:4.5:43"},{"kind":"stage","text":"Enter another Gentleman","id":"hamlet:4.5:44"},{"kind":"speech","text":"What is the matter?","sourceLine":"4.5.101","speaker":"KING CLAUDIUS","id":"hamlet:4.5:45"},{"kind":"speech","text":"Save yourself, my lord:\nThe ocean, overpeering of his list,\nEats not the flats with more impetuous haste\nThan young Laertes, in a riotous head,\nO'erbears your officers. The rabble call him lord;\nAnd, as the world were now but to begin,\nAntiquity forgot, custom not known,\nThe ratifiers and props of every word,\nThey cry 'Choose we: Laertes shall be king:'\nCaps, hands, and tongues, applaud it to the clouds:\n'Laertes shall be king, Laertes king!'","sourceLine":"4.5.102","speaker":"Gentleman","id":"hamlet:4.5:46"},{"kind":"speech","text":"How cheerfully on the false trail they cry!\nO, this is counter, you false Danish dogs!","sourceLine":"4.5.113","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:47"},{"kind":"speech","text":"The doors are broke.","sourceLine":"4.5.115","speaker":"KING CLAUDIUS","id":"hamlet:4.5:48"},{"kind":"stage","text":"Noise within","id":"hamlet:4.5:49"},{"kind":"stage","text":"Enter LAERTES, armed; Danes following","id":"hamlet:4.5:50"},{"kind":"speech","text":"Where is this king? Sirs, stand you all without.","sourceLine":"4.5.116","speaker":"LAERTES","id":"hamlet:4.5:51"},{"kind":"speech","text":"No, let's come in.","sourceLine":"4.5.117","speaker":"Danes","id":"hamlet:4.5:52"},{"kind":"speech","text":"I pray you, give me leave.","sourceLine":"4.5.118","speaker":"LAERTES","id":"hamlet:4.5:53"},{"kind":"speech","text":"We will, we will.","sourceLine":"4.5.119","speaker":"Danes","id":"hamlet:4.5:54"},{"kind":"stage","text":"They retire without the door","id":"hamlet:4.5:55"},{"kind":"speech","text":"I thank you: keep the door. O thou vile king,\nGive me my father!","sourceLine":"4.5.120","speaker":"LAERTES","id":"hamlet:4.5:56"},{"kind":"speech","text":"Calmly, good Laertes.","sourceLine":"4.5.122","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:57"},{"kind":"speech","text":"That drop of blood that's calm proclaims me bastard,\nCries cuckold to my father, brands the harlot\nEven here, between the chaste unsmirched brow\nOf my true mother.","sourceLine":"4.5.123","speaker":"LAERTES","id":"hamlet:4.5:58"},{"kind":"speech","text":"What is the cause, Laertes,\nThat thy rebellion looks so giant-like?\nLet him go, Gertrude; do not fear our person:\nThere's such divinity doth hedge a king,\nThat treason can but peep to what it would,\nActs little of his will. Tell me, Laertes,\nWhy thou art thus incensed. Let him go, Gertrude.\nSpeak, man.","sourceLine":"4.5.127","speaker":"KING CLAUDIUS","id":"hamlet:4.5:59"},{"kind":"speech","text":"Where is my father?","sourceLine":"4.5.135","speaker":"LAERTES","id":"hamlet:4.5:60"},{"kind":"speech","text":"Dead.","sourceLine":"4.5.136","speaker":"KING CLAUDIUS","id":"hamlet:4.5:61"},{"kind":"speech","text":"But not by him.","sourceLine":"4.5.137","speaker":"QUEEN GERTRUDE","id":"hamlet:4.5:62"},{"kind":"speech","text":"Let him demand his fill.","sourceLine":"4.5.138","speaker":"KING CLAUDIUS","id":"hamlet:4.5:63"},{"kind":"speech","text":"How came he dead? I'll not be juggled with:\nTo hell, allegiance! vows, to the blackest devil!\nConscience and grace, to the profoundest pit!\nI dare damnation. To this point I stand,\nThat both the worlds I give to negligence,\nLet come what comes; only I'll be revenged\nMost thoroughly for my father.","sourceLine":"4.5.139","speaker":"LAERTES","id":"hamlet:4.5:64"},{"kind":"speech","text":"Who shall stay you?","sourceLine":"4.5.146","speaker":"KING CLAUDIUS","id":"hamlet:4.5:65"},{"kind":"speech","text":"My will, not all the world:\nAnd for my means, I'll husband them so well,\nThey shall go far with little.","sourceLine":"4.5.147","speaker":"LAERTES","id":"hamlet:4.5:66"},{"kind":"speech","text":"Good Laertes,\nIf you desire to know the certainty\nOf your dear father's death, is't writ in your revenge,\nThat, swoopstake, you will draw both friend and foe,\nWinner and loser?","sourceLine":"4.5.150","speaker":"KING CLAUDIUS","id":"hamlet:4.5:67"},{"kind":"speech","text":"None but his enemies.","sourceLine":"4.5.155","speaker":"LAERTES","id":"hamlet:4.5:68"},{"kind":"speech","text":"Will you know them then?","sourceLine":"4.5.156","speaker":"KING CLAUDIUS","id":"hamlet:4.5:69"},{"kind":"speech","text":"To his good friends thus wide I'll ope my arms;\nAnd like the kind life-rendering pelican,\nRepast them with my blood.","sourceLine":"4.5.157","speaker":"LAERTES","id":"hamlet:4.5:70"},{"kind":"speech","text":"Why, now you speak\nLike a good child and a true gentleman.\nThat I am guiltless of your father's death,\nAnd am most sensible in grief for it,\nIt shall as level to your judgment pierce\nAs day does to your eye.","sourceLine":"4.5.160","speaker":"KING CLAUDIUS","id":"hamlet:4.5:71"},{"kind":"speech","text":"[Within] Let her come in.","sourceLine":"4.5.166","speaker":"Danes","id":"hamlet:4.5:72"},{"kind":"speech","text":"How now! what noise is that?","sourceLine":"4.5.167","speaker":"LAERTES","id":"hamlet:4.5:73"},{"kind":"stage","text":"Re-enter OPHELIA","id":"hamlet:4.5:74"},{"kind":"speech","text":"O heat, dry up my brains! tears seven times salt,\nBurn out the sense and virtue of mine eye!\nBy heaven, thy madness shall be paid by weight,\nTill our scale turn the beam. O rose of May!\nDear maid, kind sister, sweet Ophelia!\nO heavens! is't possible, a young maid's wits\nShould be as moral as an old man's life?\nNature is fine in love, and where 'tis fine,\nIt sends some precious instance of itself\nAfter the thing it loves.","sourceLine":"4.5.168","speaker":"LAERTES","id":"hamlet:4.5:75"},{"kind":"speech","text":"[Sings]\nThey bore him barefaced on the bier;\nHey non nonny, nonny, hey nonny;\nAnd in his grave rain'd many a tear:--\nFare you well, my dove!","sourceLine":"4.5.178","speaker":"OPHELIA","id":"hamlet:4.5:76"},{"kind":"speech","text":"Hadst thou thy wits, and didst persuade revenge,\nIt could not move thus.","sourceLine":"4.5.183","speaker":"LAERTES","id":"hamlet:4.5:77"},{"kind":"speech","text":"[Sings]\nYou must sing a-down a-down,\nAn you call him a-down-a.\nO, how the wheel becomes it! It is the false\nsteward, that stole his master's daughter.","sourceLine":"4.5.185","speaker":"OPHELIA","id":"hamlet:4.5:78"},{"kind":"speech","text":"This nothing's more than matter.","sourceLine":"4.5.190","speaker":"LAERTES","id":"hamlet:4.5:79"},{"kind":"speech","text":"There's rosemary, that's for remembrance; pray,\nlove, remember: and there is pansies. that's for thoughts.","sourceLine":"4.5.191","speaker":"OPHELIA","id":"hamlet:4.5:80"},{"kind":"speech","text":"A document in madness, thoughts and remembrance fitted.","sourceLine":"4.5.193","speaker":"LAERTES","id":"hamlet:4.5:81"},{"kind":"speech","text":"There's fennel for you, and columbines: there's rue\nfor you; and here's some for me: we may call it\nherb-grace o' Sundays: O you must wear your rue with\na difference. There's a daisy: I would give you\nsome violets, but they withered all when my father\ndied: they say he made a good end,--","sourceLine":"4.5.194","speaker":"OPHELIA","id":"hamlet:4.5:82"},{"kind":"stage","text":"Sings","id":"hamlet:4.5:83"},{"kind":"speech","text":"For bonny sweet Robin is all my joy.","sourceLine":"4.5.200","speaker":"OPHELIA","id":"hamlet:4.5:84"},{"kind":"speech","text":"Thought and affliction, passion, hell itself,\nShe turns to favour and to prettiness.","sourceLine":"4.5.201","speaker":"LAERTES","id":"hamlet:4.5:85"},{"kind":"speech","text":"[Sings]\nAnd will he not come again?\nAnd will he not come again?\nNo, no, he is dead:\nGo to thy death-bed:\nHe never will come again.\nHis beard was as white as snow,\nAll flaxen was his poll:\nHe is gone, he is gone,\nAnd we cast away moan:\nGod ha' mercy on his soul!\nAnd of all Christian souls, I pray God. God be wi' ye.","sourceLine":"4.5.203","speaker":"OPHELIA","id":"hamlet:4.5:86"},{"kind":"stage","text":"Exit","id":"hamlet:4.5:87"},{"kind":"speech","text":"Do you see this, O God?","sourceLine":"4.5.215","speaker":"LAERTES","id":"hamlet:4.5:88"},{"kind":"speech","text":"Laertes, I must commune with your grief,\nOr you deny me right. Go but apart,\nMake choice of whom your wisest friends you will.\nAnd they shall hear and judge 'twixt you and me:\nIf by direct or by collateral hand\nThey find us touch'd, we will our kingdom give,\nOur crown, our life, and all that we can ours,\nTo you in satisfaction; but if not,\nBe you content to lend your patience to us,\nAnd we shall jointly labour with your soul\nTo give it due content.","sourceLine":"4.5.216","speaker":"KING CLAUDIUS","id":"hamlet:4.5:89"},{"kind":"speech","text":"Let this be so;\nHis means of death, his obscure funeral--\nNo trophy, sword, nor hatchment o'er his bones,\nNo noble rite nor formal ostentation--\nCry to be heard, as 'twere from heaven to earth,\nThat I must call't in question.","sourceLine":"4.5.227","speaker":"LAERTES","id":"hamlet:4.5:90"},{"kind":"speech","text":"So you shall;\nAnd where the offence is let the great axe fall.\nI pray you, go with me.","sourceLine":"4.5.233","speaker":"KING CLAUDIUS","id":"hamlet:4.5:91"},{"kind":"stage","text":"Exeunt","id":"hamlet:4.5:92"}],"scene":5},{"id":"4.6","label":"Act 4 · SCENE VI. Another room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter HORATIO and a Servant","id":"hamlet:4.6:1"},{"kind":"speech","text":"What are they that would speak with me?","sourceLine":"4.6.1","speaker":"HORATIO","id":"hamlet:4.6:2"},{"kind":"speech","text":"Sailors, sir: they say they have letters for you.","sourceLine":"4.6.2","speaker":"Servant","id":"hamlet:4.6:3"},{"kind":"speech","text":"Let them come in.","sourceLine":"4.6.3","speaker":"HORATIO","id":"hamlet:4.6:4"},{"kind":"stage","text":"Exit Servant","id":"hamlet:4.6:5"},{"kind":"speech","text":"I do not know from what part of the world\nI should be greeted, if not from Lord Hamlet.","sourceLine":"4.6.4","speaker":"HORATIO","id":"hamlet:4.6:6"},{"kind":"stage","text":"Enter Sailors","id":"hamlet:4.6:7"},{"kind":"speech","text":"God bless you, sir.","sourceLine":"4.6.6","speaker":"First Sailor","id":"hamlet:4.6:8"},{"kind":"speech","text":"Let him bless thee too.","sourceLine":"4.6.7","speaker":"HORATIO","id":"hamlet:4.6:9"},{"kind":"speech","text":"He shall, sir, an't please him. There's a letter for\nyou, sir; it comes from the ambassador that was\nbound for England; if your name be Horatio, as I am\nlet to know it is.","sourceLine":"4.6.8","speaker":"First Sailor","id":"hamlet:4.6:10"},{"kind":"speech","text":"[Reads] 'Horatio, when thou shalt have overlooked\nthis, give these fellows some means to the king:\nthey have letters for him. Ere we were two days old\nat sea, a pirate of very warlike appointment gave us\nchase. Finding ourselves too slow of sail, we put on\na compelled valour, and in the grapple I boarded\nthem: on the instant they got clear of our ship; so\nI alone became their prisoner. They have dealt with\nme like thieves of mercy: but they knew what they\ndid; I am to do a good turn for them. Let the king\nhave the letters I have sent; and repair thou to me\nwith as much speed as thou wouldst fly death. I\nhave words to speak in thine ear will make thee\ndumb; yet are they much too light for the bore of\nthe matter. These good fellows will bring thee\nwhere I am. Rosencrantz and Guildenstern hold their\ncourse for England: of them I have much to tell\nthee. Farewell.\n'He that thou knowest thine, HAMLET.'\nCome, I will make you way for these your letters;\nAnd do't the speedier, that you may direct me\nTo him from whom you brought them.","sourceLine":"4.6.12","speaker":"HORATIO","id":"hamlet:4.6:11"},{"kind":"stage","text":"Exeunt","id":"hamlet:4.6:12"}],"scene":6},{"id":"4.7","label":"Act 4 · SCENE VII. Another room in the castle.","act":4,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter KING CLAUDIUS and LAERTES","id":"hamlet:4.7:1"},{"kind":"speech","text":"Now must your conscience my acquaintance seal,\nAnd you must put me in your heart for friend,\nSith you have heard, and with a knowing ear,\nThat he which hath your noble father slain\nPursued my life.","sourceLine":"4.7.1","speaker":"KING CLAUDIUS","id":"hamlet:4.7:2"},{"kind":"speech","text":"It well appears: but tell me\nWhy you proceeded not against these feats,\nSo crimeful and so capital in nature,\nAs by your safety, wisdom, all things else,\nYou mainly were stirr'd up.","sourceLine":"4.7.6","speaker":"LAERTES","id":"hamlet:4.7:3"},{"kind":"speech","text":"O, for two special reasons;\nWhich may to you, perhaps, seem much unsinew'd,\nBut yet to me they are strong. The queen his mother\nLives almost by his looks; and for myself--\nMy virtue or my plague, be it either which--\nShe's so conjunctive to my life and soul,\nThat, as the star moves not but in his sphere,\nI could not but by her. The other motive,\nWhy to a public count I might not go,\nIs the great love the general gender bear him;\nWho, dipping all his faults in their affection,\nWould, like the spring that turneth wood to stone,\nConvert his gyves to graces; so that my arrows,\nToo slightly timber'd for so loud a wind,\nWould have reverted to my bow again,\nAnd not where I had aim'd them.","sourceLine":"4.7.11","speaker":"KING CLAUDIUS","id":"hamlet:4.7:4"},{"kind":"speech","text":"And so have I a noble father lost;\nA sister driven into desperate terms,\nWhose worth, if praises may go back again,\nStood challenger on mount of all the age\nFor her perfections: but my revenge will come.","sourceLine":"4.7.27","speaker":"LAERTES","id":"hamlet:4.7:5"},{"kind":"speech","text":"Break not your sleeps for that: you must not think\nThat we are made of stuff so flat and dull\nThat we can let our beard be shook with danger\nAnd think it pastime. You shortly shall hear more:\nI loved your father, and we love ourself;\nAnd that, I hope, will teach you to imagine--","sourceLine":"4.7.32","speaker":"KING CLAUDIUS","id":"hamlet:4.7:6"},{"kind":"stage","text":"Enter a Messenger","id":"hamlet:4.7:7"},{"kind":"speech","text":"How now! what news?","sourceLine":"4.7.38","speaker":"KING CLAUDIUS","id":"hamlet:4.7:8"},{"kind":"speech","text":"Letters, my lord, from Hamlet:\nThis to your majesty; this to the queen.","sourceLine":"4.7.39","speaker":"Messenger","id":"hamlet:4.7:9"},{"kind":"speech","text":"From Hamlet! who brought them?","sourceLine":"4.7.41","speaker":"KING CLAUDIUS","id":"hamlet:4.7:10"},{"kind":"speech","text":"Sailors, my lord, they say; I saw them not:\nThey were given me by Claudio; he received them\nOf him that brought them.","sourceLine":"4.7.42","speaker":"Messenger","id":"hamlet:4.7:11"},{"kind":"speech","text":"Laertes, you shall hear them. Leave us.","sourceLine":"4.7.45","speaker":"KING CLAUDIUS","id":"hamlet:4.7:12"},{"kind":"stage","text":"Exit Messenger","id":"hamlet:4.7:13"},{"kind":"stage","text":"Reads","id":"hamlet:4.7:14"},{"kind":"speech","text":"'High and mighty, You shall know I am set naked on\nyour kingdom. To-morrow shall I beg leave to see\nyour kingly eyes: when I shall, first asking your\npardon thereunto, recount the occasion of my sudden\nand more strange return. 'HAMLET.'\nWhat should this mean? Are all the rest come back?\nOr is it some abuse, and no such thing?","sourceLine":"4.7.46","speaker":"KING CLAUDIUS","id":"hamlet:4.7:15"},{"kind":"speech","text":"Know you the hand?","sourceLine":"4.7.53","speaker":"LAERTES","id":"hamlet:4.7:16"},{"kind":"speech","text":"'Tis Hamlets character. 'Naked!\nAnd in a postscript here, he says 'alone.'\nCan you advise me?","sourceLine":"4.7.54","speaker":"KING CLAUDIUS","id":"hamlet:4.7:17"},{"kind":"speech","text":"I'm lost in it, my lord. But let him come;\nIt warms the very sickness in my heart,\nThat I shall live and tell him to his teeth,\n'Thus didest thou.'","sourceLine":"4.7.57","speaker":"LAERTES","id":"hamlet:4.7:18"},{"kind":"speech","text":"If it be so, Laertes--\nAs how should it be so? how otherwise?--\nWill you be ruled by me?","sourceLine":"4.7.61","speaker":"KING CLAUDIUS","id":"hamlet:4.7:19"},{"kind":"speech","text":"Ay, my lord;\nSo you will not o'errule me to a peace.","sourceLine":"4.7.64","speaker":"LAERTES","id":"hamlet:4.7:20"},{"kind":"speech","text":"To thine own peace. If he be now return'd,\nAs checking at his voyage, and that he means\nNo more to undertake it, I will work him\nTo an exploit, now ripe in my device,\nUnder the which he shall not choose but fall:\nAnd for his death no wind of blame shall breathe,\nBut even his mother shall uncharge the practise\nAnd call it accident.","sourceLine":"4.7.66","speaker":"KING CLAUDIUS","id":"hamlet:4.7:21"},{"kind":"speech","text":"My lord, I will be ruled;\nThe rather, if you could devise it so\nThat I might be the organ.","sourceLine":"4.7.74","speaker":"LAERTES","id":"hamlet:4.7:22"},{"kind":"speech","text":"It falls right.\nYou have been talk'd of since your travel much,\nAnd that in Hamlet's hearing, for a quality\nWherein, they say, you shine: your sum of parts\nDid not together pluck such envy from him\nAs did that one, and that, in my regard,\nOf the unworthiest siege.","sourceLine":"4.7.77","speaker":"KING CLAUDIUS","id":"hamlet:4.7:23"},{"kind":"speech","text":"What part is that, my lord?","sourceLine":"4.7.84","speaker":"LAERTES","id":"hamlet:4.7:24"},{"kind":"speech","text":"A very riband in the cap of youth,\nYet needful too; for youth no less becomes\nThe light and careless livery that it wears\nThan settled age his sables and his weeds,\nImporting health and graveness. Two months since,\nHere was a gentleman of Normandy:--\nI've seen myself, and served against, the French,\nAnd they can well on horseback: but this gallant\nHad witchcraft in't; he grew unto his seat;\nAnd to such wondrous doing brought his horse,\nAs he had been incorpsed and demi-natured\nWith the brave beast: so far he topp'd my thought,\nThat I, in forgery of shapes and tricks,\nCome short of what he did.","sourceLine":"4.7.85","speaker":"KING CLAUDIUS","id":"hamlet:4.7:25"},{"kind":"speech","text":"A Norman was't?","sourceLine":"4.7.99","speaker":"LAERTES","id":"hamlet:4.7:26"},{"kind":"speech","text":"A Norman.","sourceLine":"4.7.100","speaker":"KING CLAUDIUS","id":"hamlet:4.7:27"},{"kind":"speech","text":"Upon my life, Lamond.","sourceLine":"4.7.101","speaker":"LAERTES","id":"hamlet:4.7:28"},{"kind":"speech","text":"The very same.","sourceLine":"4.7.102","speaker":"KING CLAUDIUS","id":"hamlet:4.7:29"},{"kind":"speech","text":"I know him well: he is the brooch indeed\nAnd gem of all the nation.","sourceLine":"4.7.103","speaker":"LAERTES","id":"hamlet:4.7:30"},{"kind":"speech","text":"He made confession of you,\nAnd gave you such a masterly report\nFor art and exercise in your defence\nAnd for your rapier most especially,\nThat he cried out, 'twould be a sight indeed,\nIf one could match you: the scrimers of their nation,\nHe swore, had had neither motion, guard, nor eye,\nIf you opposed them. Sir, this report of his\nDid Hamlet so envenom with his envy\nThat he could nothing do but wish and beg\nYour sudden coming o'er, to play with him.\nNow, out of this,--","sourceLine":"4.7.105","speaker":"KING CLAUDIUS","id":"hamlet:4.7:31"},{"kind":"speech","text":"What out of this, my lord?","sourceLine":"4.7.117","speaker":"LAERTES","id":"hamlet:4.7:32"},{"kind":"speech","text":"Laertes, was your father dear to you?\nOr are you like the painting of a sorrow,\nA face without a heart?","sourceLine":"4.7.118","speaker":"KING CLAUDIUS","id":"hamlet:4.7:33"},{"kind":"speech","text":"Why ask you this?","sourceLine":"4.7.121","speaker":"LAERTES","id":"hamlet:4.7:34"},{"kind":"speech","text":"Not that I think you did not love your father;\nBut that I know love is begun by time;\nAnd that I see, in passages of proof,\nTime qualifies the spark and fire of it.\nThere lives within the very flame of love\nA kind of wick or snuff that will abate it;\nAnd nothing is at a like goodness still;\nFor goodness, growing to a plurisy,\nDies in his own too much: that we would do\nWe should do when we would; for this 'would' changes\nAnd hath abatements and delays as many\nAs there are tongues, are hands, are accidents;\nAnd then this 'should' is like a spendthrift sigh,\nThat hurts by easing. But, to the quick o' the ulcer:--\nHamlet comes back: what would you undertake,\nTo show yourself your father's son in deed\nMore than in words?","sourceLine":"4.7.122","speaker":"KING CLAUDIUS","id":"hamlet:4.7:35"},{"kind":"speech","text":"To cut his throat i' the church.","sourceLine":"4.7.139","speaker":"LAERTES","id":"hamlet:4.7:36"},{"kind":"speech","text":"No place, indeed, should murder sanctuarize;\nRevenge should have no bounds. But, good Laertes,\nWill you do this, keep close within your chamber.\nHamlet return'd shall know you are come home:\nWe'll put on those shall praise your excellence\nAnd set a double varnish on the fame\nThe Frenchman gave you, bring you in fine together\nAnd wager on your heads: he, being remiss,\nMost generous and free from all contriving,\nWill not peruse the foils; so that, with ease,\nOr with a little shuffling, you may choose\nA sword unbated, and in a pass of practise\nRequite him for your father.","sourceLine":"4.7.140","speaker":"KING CLAUDIUS","id":"hamlet:4.7:37"},{"kind":"speech","text":"I will do't:\nAnd, for that purpose, I'll anoint my sword.\nI bought an unction of a mountebank,\nSo mortal that, but dip a knife in it,\nWhere it draws blood no cataplasm so rare,\nCollected from all simples that have virtue\nUnder the moon, can save the thing from death\nThat is but scratch'd withal: I'll touch my point\nWith this contagion, that, if I gall him slightly,\nIt may be death.","sourceLine":"4.7.153","speaker":"LAERTES","id":"hamlet:4.7:38"},{"kind":"speech","text":"Let's further think of this;\nWeigh what convenience both of time and means\nMay fit us to our shape: if this should fail,\nAnd that our drift look through our bad performance,\n'Twere better not assay'd: therefore this project\nShould have a back or second, that might hold,\nIf this should blast in proof. Soft! let me see:\nWe'll make a solemn wager on your cunnings: I ha't.\nWhen in your motion you are hot and dry--\nAs make your bouts more violent to that end--\nAnd that he calls for drink, I'll have prepared him\nA chalice for the nonce, whereon but sipping,\nIf he by chance escape your venom'd stuck,\nOur purpose may hold there.","sourceLine":"4.7.163","speaker":"KING CLAUDIUS","id":"hamlet:4.7:39"},{"kind":"stage","text":"Enter QUEEN GERTRUDE","id":"hamlet:4.7:40"},{"kind":"speech","text":"How now, sweet queen!","sourceLine":"4.7.177","speaker":"KING CLAUDIUS","id":"hamlet:4.7:41"},{"kind":"speech","text":"One woe doth tread upon another's heel,\nSo fast they follow; your sister's drown'd, Laertes.","sourceLine":"4.7.178","speaker":"QUEEN GERTRUDE","id":"hamlet:4.7:42"},{"kind":"speech","text":"Drown'd! O, where?","sourceLine":"4.7.180","speaker":"LAERTES","id":"hamlet:4.7:43"},{"kind":"speech","text":"There is a willow grows aslant a brook,\nThat shows his hoar leaves in the glassy stream;\nThere with fantastic garlands did she come\nOf crow-flowers, nettles, daisies, and long purples\nThat liberal shepherds give a grosser name,\nBut our cold maids do dead men's fingers call them:\nThere, on the pendent boughs her coronet weeds\nClambering to hang, an envious sliver broke;\nWhen down her weedy trophies and herself\nFell in the weeping brook. Her clothes spread wide;\nAnd, mermaid-like, awhile they bore her up:\nWhich time she chanted snatches of old tunes;\nAs one incapable of her own distress,\nOr like a creature native and indued\nUnto that element: but long it could not be\nTill that her garments, heavy with their drink,\nPull'd the poor wretch from her melodious lay\nTo muddy death.","sourceLine":"4.7.181","speaker":"QUEEN GERTRUDE","id":"hamlet:4.7:44"},{"kind":"speech","text":"Alas, then, she is drown'd?","sourceLine":"4.7.199","speaker":"LAERTES","id":"hamlet:4.7:45"},{"kind":"speech","text":"Drown'd, drown'd.","sourceLine":"4.7.200","speaker":"QUEEN GERTRUDE","id":"hamlet:4.7:46"},{"kind":"speech","text":"Too much of water hast thou, poor Ophelia,\nAnd therefore I forbid my tears: but yet\nIt is our trick; nature her custom holds,\nLet shame say what it will: when these are gone,\nThe woman will be out. Adieu, my lord:\nI have a speech of fire, that fain would blaze,\nBut that this folly douts it.","sourceLine":"4.7.201","speaker":"LAERTES","id":"hamlet:4.7:47"},{"kind":"stage","text":"Exit","id":"hamlet:4.7:48"},{"kind":"speech","text":"Let's follow, Gertrude:\nHow much I had to do to calm his rage!\nNow fear I this will give it start again;\nTherefore let's follow.","sourceLine":"4.7.208","speaker":"KING CLAUDIUS","id":"hamlet:4.7:49"},{"kind":"stage","text":"Exeunt","id":"hamlet:4.7:50"}],"scene":7},{"id":"5.1","label":"Act 5 · SCENE I. A churchyard.","act":5,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter two Clowns, with spades, & c","id":"hamlet:5.1:1"},{"kind":"speech","text":"Is she to be buried in Christian burial that\nwilfully seeks her own salvation?","sourceLine":"5.1.1","speaker":"First Clown","id":"hamlet:5.1:2"},{"kind":"speech","text":"I tell thee she is: and therefore make her grave\nstraight: the crowner hath sat on her, and finds it\nChristian burial.","sourceLine":"5.1.3","speaker":"Second Clown","id":"hamlet:5.1:3"},{"kind":"speech","text":"How can that be, unless she drowned herself in her\nown defence?","sourceLine":"5.1.6","speaker":"First Clown","id":"hamlet:5.1:4"},{"kind":"speech","text":"Why, 'tis found so.","sourceLine":"5.1.8","speaker":"Second Clown","id":"hamlet:5.1:5"},{"kind":"speech","text":"It must be 'se offendendo;' it cannot be else. For\nhere lies the point: if I drown myself wittingly,\nit argues an act: and an act hath three branches: it\nis, to act, to do, to perform: argal, she drowned\nherself wittingly.","sourceLine":"5.1.9","speaker":"First Clown","id":"hamlet:5.1:6"},{"kind":"speech","text":"Nay, but hear you, goodman delver,--","sourceLine":"5.1.14","speaker":"Second Clown","id":"hamlet:5.1:7"},{"kind":"speech","text":"Give me leave. Here lies the water; good: here\nstands the man; good; if the man go to this water,\nand drown himself, it is, will he, nill he, he\ngoes,--mark you that; but if the water come to him\nand drown him, he drowns not himself: argal, he\nthat is not guilty of his own death shortens not his own life.","sourceLine":"5.1.15","speaker":"First Clown","id":"hamlet:5.1:8"},{"kind":"speech","text":"But is this law?","sourceLine":"5.1.21","speaker":"Second Clown","id":"hamlet:5.1:9"},{"kind":"speech","text":"Ay, marry, is't; crowner's quest law.","sourceLine":"5.1.22","speaker":"First Clown","id":"hamlet:5.1:10"},{"kind":"speech","text":"Will you ha' the truth on't? If this had not been\na gentlewoman, she should have been buried out o'\nChristian burial.","sourceLine":"5.1.23","speaker":"Second Clown","id":"hamlet:5.1:11"},{"kind":"speech","text":"Why, there thou say'st: and the more pity that\ngreat folk should have countenance in this world to\ndrown or hang themselves, more than their even\nChristian. Come, my spade. There is no ancient\ngentleman but gardeners, ditchers, and grave-makers:\nthey hold up Adam's profession.","sourceLine":"5.1.26","speaker":"First Clown","id":"hamlet:5.1:12"},{"kind":"speech","text":"Was he a gentleman?","sourceLine":"5.1.32","speaker":"Second Clown","id":"hamlet:5.1:13"},{"kind":"speech","text":"He was the first that ever bore arms.","sourceLine":"5.1.33","speaker":"First Clown","id":"hamlet:5.1:14"},{"kind":"speech","text":"Why, he had none.","sourceLine":"5.1.34","speaker":"Second Clown","id":"hamlet:5.1:15"},{"kind":"speech","text":"What, art a heathen? How dost thou understand the\nScripture? The Scripture says 'Adam digged:'\ncould he dig without arms? I'll put another\nquestion to thee: if thou answerest me not to the\npurpose, confess thyself--","sourceLine":"5.1.35","speaker":"First Clown","id":"hamlet:5.1:16"},{"kind":"speech","text":"Go to.","sourceLine":"5.1.40","speaker":"Second Clown","id":"hamlet:5.1:17"},{"kind":"speech","text":"What is he that builds stronger than either the\nmason, the shipwright, or the carpenter?","sourceLine":"5.1.41","speaker":"First Clown","id":"hamlet:5.1:18"},{"kind":"speech","text":"The gallows-maker; for that frame outlives a\nthousand tenants.","sourceLine":"5.1.43","speaker":"Second Clown","id":"hamlet:5.1:19"},{"kind":"speech","text":"I like thy wit well, in good faith: the gallows\ndoes well; but how does it well? it does well to\nthose that do in: now thou dost ill to say the\ngallows is built stronger than the church: argal,\nthe gallows may do well to thee. To't again, come.","sourceLine":"5.1.45","speaker":"First Clown","id":"hamlet:5.1:20"},{"kind":"speech","text":"'Who builds stronger than a mason, a shipwright, or\na carpenter?'","sourceLine":"5.1.50","speaker":"Second Clown","id":"hamlet:5.1:21"},{"kind":"speech","text":"Ay, tell me that, and unyoke.","sourceLine":"5.1.52","speaker":"First Clown","id":"hamlet:5.1:22"},{"kind":"speech","text":"Marry, now I can tell.","sourceLine":"5.1.53","speaker":"Second Clown","id":"hamlet:5.1:23"},{"kind":"speech","text":"To't.","sourceLine":"5.1.54","speaker":"First Clown","id":"hamlet:5.1:24"},{"kind":"speech","text":"Mass, I cannot tell.","sourceLine":"5.1.55","speaker":"Second Clown","id":"hamlet:5.1:25"},{"kind":"stage","text":"Enter HAMLET and HORATIO, at a distance","id":"hamlet:5.1:26"},{"kind":"speech","text":"Cudgel thy brains no more about it, for your dull\nass will not mend his pace with beating; and, when\nyou are asked this question next, say 'a\ngrave-maker: 'the houses that he makes last till\ndoomsday. Go, get thee to Yaughan: fetch me a\nstoup of liquor.","sourceLine":"5.1.56","speaker":"First Clown","id":"hamlet:5.1:27"},{"kind":"stage","text":"Exit Second Clown","id":"hamlet:5.1:28"},{"kind":"stage","text":"He digs and sings","id":"hamlet:5.1:29"},{"kind":"speech","text":"In youth, when I did love, did love,\nMethought it was very sweet,\nTo contract, O, the time, for, ah, my behove,\nO, methought, there was nothing meet.","sourceLine":"5.1.62","speaker":"First Clown","id":"hamlet:5.1:30"},{"kind":"speech","text":"Has this fellow no feeling of his business, that he\nsings at grave-making?","sourceLine":"5.1.66","speaker":"HAMLET","id":"hamlet:5.1:31"},{"kind":"speech","text":"Custom hath made it in him a property of easiness.","sourceLine":"5.1.68","speaker":"HORATIO","id":"hamlet:5.1:32"},{"kind":"speech","text":"'Tis e'en so: the hand of little employment hath\nthe daintier sense.","sourceLine":"5.1.69","speaker":"HAMLET","id":"hamlet:5.1:33"},{"kind":"speech","text":"[Sings]\nBut age, with his stealing steps,\nHath claw'd me in his clutch,\nAnd hath shipped me intil the land,\nAs if I had never been such.","sourceLine":"5.1.71","speaker":"First Clown","id":"hamlet:5.1:34"},{"kind":"stage","text":"Throws up a skull","id":"hamlet:5.1:35"},{"kind":"speech","text":"That skull had a tongue in it, and could sing once:\nhow the knave jowls it to the ground, as if it were\nCain's jaw-bone, that did the first murder! It\nmight be the pate of a politician, which this ass\nnow o'er-reaches; one that would circumvent God,\nmight it not?","sourceLine":"5.1.76","speaker":"HAMLET","id":"hamlet:5.1:36"},{"kind":"speech","text":"It might, my lord.","sourceLine":"5.1.82","speaker":"HORATIO","id":"hamlet:5.1:37"},{"kind":"speech","text":"Or of a courtier; which could say 'Good morrow,\nsweet lord! How dost thou, good lord?' This might\nbe my lord such-a-one, that praised my lord\nsuch-a-one's horse, when he meant to beg it; might it not?","sourceLine":"5.1.83","speaker":"HAMLET","id":"hamlet:5.1:38"},{"kind":"speech","text":"Ay, my lord.","sourceLine":"5.1.87","speaker":"HORATIO","id":"hamlet:5.1:39"},{"kind":"speech","text":"Why, e'en so: and now my Lady Worm's; chapless, and\nknocked about the mazzard with a sexton's spade:\nhere's fine revolution, an we had the trick to\nsee't. Did these bones cost no more the breeding,\nbut to play at loggats with 'em? mine ache to think on't.","sourceLine":"5.1.88","speaker":"HAMLET","id":"hamlet:5.1:40"},{"kind":"speech","text":"[Sings]\nA pick-axe, and a spade, a spade,\nFor and a shrouding sheet:\nO, a pit of clay for to be made\nFor such a guest is meet.","sourceLine":"5.1.93","speaker":"First Clown","id":"hamlet:5.1:41"},{"kind":"stage","text":"Throws up another skull","id":"hamlet:5.1:42"},{"kind":"speech","text":"There's another: why may not that be the skull of a\nlawyer? Where be his quiddities now, his quillets,\nhis cases, his tenures, and his tricks? why does he\nsuffer this rude knave now to knock him about the\nsconce with a dirty shovel, and will not tell him of\nhis action of battery? Hum! This fellow might be\nin's time a great buyer of land, with his statutes,\nhis recognizances, his fines, his double vouchers,\nhis recoveries: is this the fine of his fines, and\nthe recovery of his recoveries, to have his fine\npate full of fine dirt? will his vouchers vouch him\nno more of his purchases, and double ones too, than\nthe length and breadth of a pair of indentures? The\nvery conveyances of his lands will hardly lie in\nthis box; and must the inheritor himself have no more, ha?","sourceLine":"5.1.98","speaker":"HAMLET","id":"hamlet:5.1:43"},{"kind":"speech","text":"Not a jot more, my lord.","sourceLine":"5.1.113","speaker":"HORATIO","id":"hamlet:5.1:44"},{"kind":"speech","text":"Is not parchment made of sheepskins?","sourceLine":"5.1.114","speaker":"HAMLET","id":"hamlet:5.1:45"},{"kind":"speech","text":"Ay, my lord, and of calf-skins too.","sourceLine":"5.1.115","speaker":"HORATIO","id":"hamlet:5.1:46"},{"kind":"speech","text":"They are sheep and calves which seek out assurance\nin that. I will speak to this fellow. Whose\ngrave's this, sirrah?","sourceLine":"5.1.116","speaker":"HAMLET","id":"hamlet:5.1:47"},{"kind":"speech","text":"Mine, sir.","sourceLine":"5.1.119","speaker":"First Clown","id":"hamlet:5.1:48"},{"kind":"stage","text":"Sings","id":"hamlet:5.1:49"},{"kind":"speech","text":"O, a pit of clay for to be made\nFor such a guest is meet.","sourceLine":"5.1.120","speaker":"First Clown","id":"hamlet:5.1:50"},{"kind":"speech","text":"I think it be thine, indeed; for thou liest in't.","sourceLine":"5.1.122","speaker":"HAMLET","id":"hamlet:5.1:51"},{"kind":"speech","text":"You lie out on't, sir, and therefore it is not\nyours: for my part, I do not lie in't, and yet it is mine.","sourceLine":"5.1.123","speaker":"First Clown","id":"hamlet:5.1:52"},{"kind":"speech","text":"'Thou dost lie in't, to be in't and say it is thine:\n'tis for the dead, not for the quick; therefore thou liest.","sourceLine":"5.1.125","speaker":"HAMLET","id":"hamlet:5.1:53"},{"kind":"speech","text":"'Tis a quick lie, sir; 'twill away gain, from me to\nyou.","sourceLine":"5.1.127","speaker":"First Clown","id":"hamlet:5.1:54"},{"kind":"speech","text":"What man dost thou dig it for?","sourceLine":"5.1.129","speaker":"HAMLET","id":"hamlet:5.1:55"},{"kind":"speech","text":"For no man, sir.","sourceLine":"5.1.130","speaker":"First Clown","id":"hamlet:5.1:56"},{"kind":"speech","text":"What woman, then?","sourceLine":"5.1.131","speaker":"HAMLET","id":"hamlet:5.1:57"},{"kind":"speech","text":"For none, neither.","sourceLine":"5.1.132","speaker":"First Clown","id":"hamlet:5.1:58"},{"kind":"speech","text":"Who is to be buried in't?","sourceLine":"5.1.133","speaker":"HAMLET","id":"hamlet:5.1:59"},{"kind":"speech","text":"One that was a woman, sir; but, rest her soul, she's dead.","sourceLine":"5.1.134","speaker":"First Clown","id":"hamlet:5.1:60"},{"kind":"speech","text":"How absolute the knave is! we must speak by the\ncard, or equivocation will undo us. By the Lord,\nHoratio, these three years I have taken a note of\nit; the age is grown so picked that the toe of the\npeasant comes so near the heel of the courtier, he\ngaffs his kibe. How long hast thou been a\ngrave-maker?","sourceLine":"5.1.135","speaker":"HAMLET","id":"hamlet:5.1:61"},{"kind":"speech","text":"Of all the days i' the year, I came to't that day\nthat our last king Hamlet overcame Fortinbras.","sourceLine":"5.1.142","speaker":"First Clown","id":"hamlet:5.1:62"},{"kind":"speech","text":"How long is that since?","sourceLine":"5.1.144","speaker":"HAMLET","id":"hamlet:5.1:63"},{"kind":"speech","text":"Cannot you tell that? every fool can tell that: it\nwas the very day that young Hamlet was born; he that\nis mad, and sent into England.","sourceLine":"5.1.145","speaker":"First Clown","id":"hamlet:5.1:64"},{"kind":"speech","text":"Ay, marry, why was he sent into England?","sourceLine":"5.1.148","speaker":"HAMLET","id":"hamlet:5.1:65"},{"kind":"speech","text":"Why, because he was mad: he shall recover his wits\nthere; or, if he do not, it's no great matter there.","sourceLine":"5.1.149","speaker":"First Clown","id":"hamlet:5.1:66"},{"kind":"speech","text":"Why?","sourceLine":"5.1.151","speaker":"HAMLET","id":"hamlet:5.1:67"},{"kind":"speech","text":"'Twill, a not be seen in him there; there the men\nare as mad as he.","sourceLine":"5.1.152","speaker":"First Clown","id":"hamlet:5.1:68"},{"kind":"speech","text":"How came he mad?","sourceLine":"5.1.154","speaker":"HAMLET","id":"hamlet:5.1:69"},{"kind":"speech","text":"Very strangely, they say.","sourceLine":"5.1.155","speaker":"First Clown","id":"hamlet:5.1:70"},{"kind":"speech","text":"How strangely?","sourceLine":"5.1.156","speaker":"HAMLET","id":"hamlet:5.1:71"},{"kind":"speech","text":"Faith, e'en with losing his wits.","sourceLine":"5.1.157","speaker":"First Clown","id":"hamlet:5.1:72"},{"kind":"speech","text":"Upon what ground?","sourceLine":"5.1.158","speaker":"HAMLET","id":"hamlet:5.1:73"},{"kind":"speech","text":"Why, here in Denmark: I have been sexton here, man\nand boy, thirty years.","sourceLine":"5.1.159","speaker":"First Clown","id":"hamlet:5.1:74"},{"kind":"speech","text":"How long will a man lie i' the earth ere he rot?","sourceLine":"5.1.161","speaker":"HAMLET","id":"hamlet:5.1:75"},{"kind":"speech","text":"I' faith, if he be not rotten before he die--as we\nhave many pocky corses now-a-days, that will scarce\nhold the laying in--he will last you some eight year\nor nine year: a tanner will last you nine year.","sourceLine":"5.1.162","speaker":"First Clown","id":"hamlet:5.1:76"},{"kind":"speech","text":"Why he more than another?","sourceLine":"5.1.166","speaker":"HAMLET","id":"hamlet:5.1:77"},{"kind":"speech","text":"Why, sir, his hide is so tanned with his trade, that\nhe will keep out water a great while; and your water\nis a sore decayer of your whoreson dead body.\nHere's a skull now; this skull has lain in the earth\nthree and twenty years.","sourceLine":"5.1.167","speaker":"First Clown","id":"hamlet:5.1:78"},{"kind":"speech","text":"Whose was it?","sourceLine":"5.1.172","speaker":"HAMLET","id":"hamlet:5.1:79"},{"kind":"speech","text":"A whoreson mad fellow's it was: whose do you think it was?","sourceLine":"5.1.173","speaker":"First Clown","id":"hamlet:5.1:80"},{"kind":"speech","text":"Nay, I know not.","sourceLine":"5.1.174","speaker":"HAMLET","id":"hamlet:5.1:81"},{"kind":"speech","text":"A pestilence on him for a mad rogue! a' poured a\nflagon of Rhenish on my head once. This same skull,\nsir, was Yorick's skull, the king's jester.","sourceLine":"5.1.175","speaker":"First Clown","id":"hamlet:5.1:82"},{"kind":"speech","text":"This?","sourceLine":"5.1.178","speaker":"HAMLET","id":"hamlet:5.1:83"},{"kind":"speech","text":"E'en that.","sourceLine":"5.1.179","speaker":"First Clown","id":"hamlet:5.1:84"},{"kind":"speech","text":"Let me see.","sourceLine":"5.1.180","speaker":"HAMLET","id":"hamlet:5.1:85"},{"kind":"stage","text":"Takes the skull","id":"hamlet:5.1:86"},{"kind":"speech","text":"Alas, poor Yorick! I knew him, Horatio: a fellow\nof infinite jest, of most excellent fancy: he hath\nborne me on his back a thousand times; and now, how\nabhorred in my imagination it is! my gorge rims at\nit. Here hung those lips that I have kissed I know\nnot how oft. Where be your gibes now? your\ngambols? your songs? your flashes of merriment,\nthat were wont to set the table on a roar? Not one\nnow, to mock your own grinning? quite chap-fallen?\nNow get you to my lady's chamber, and tell her, let\nher paint an inch thick, to this favour she must\ncome; make her laugh at that. Prithee, Horatio, tell\nme one thing.","sourceLine":"5.1.181","speaker":"HAMLET","id":"hamlet:5.1:87"},{"kind":"speech","text":"What's that, my lord?","sourceLine":"5.1.194","speaker":"HORATIO","id":"hamlet:5.1:88"},{"kind":"speech","text":"Dost thou think Alexander looked o' this fashion i'\nthe earth?","sourceLine":"5.1.195","speaker":"HAMLET","id":"hamlet:5.1:89"},{"kind":"speech","text":"E'en so.","sourceLine":"5.1.197","speaker":"HORATIO","id":"hamlet:5.1:90"},{"kind":"speech","text":"And smelt so? pah!","sourceLine":"5.1.198","speaker":"HAMLET","id":"hamlet:5.1:91"},{"kind":"stage","text":"Puts down the skull","id":"hamlet:5.1:92"},{"kind":"speech","text":"E'en so, my lord.","sourceLine":"5.1.199","speaker":"HORATIO","id":"hamlet:5.1:93"},{"kind":"speech","text":"To what base uses we may return, Horatio! Why may\nnot imagination trace the noble dust of Alexander,\ntill he find it stopping a bung-hole?","sourceLine":"5.1.200","speaker":"HAMLET","id":"hamlet:5.1:94"},{"kind":"speech","text":"'Twere to consider too curiously, to consider so.","sourceLine":"5.1.203","speaker":"HORATIO","id":"hamlet:5.1:95"},{"kind":"speech","text":"No, faith, not a jot; but to follow him thither with\nmodesty enough, and likelihood to lead it: as\nthus: Alexander died, Alexander was buried,\nAlexander returneth into dust; the dust is earth; of\nearth we make loam; and why of that loam, whereto he\nwas converted, might they not stop a beer-barrel?\nImperious Caesar, dead and turn'd to clay,\nMight stop a hole to keep the wind away:\nO, that that earth, which kept the world in awe,\nShould patch a wall to expel the winter flaw!\nBut soft! but soft! aside: here comes the king.","sourceLine":"5.1.204","speaker":"HAMLET","id":"hamlet:5.1:96"},{"kind":"stage","text":"Enter Priest, & c. in procession; the Corpse of OPHELIA, LAERTES and Mourners following; KING CLAUDIUS, QUEEN GERTRUDE, their trains, & c","id":"hamlet:5.1:97"},{"kind":"speech","text":"The queen, the courtiers: who is this they follow?\nAnd with such maimed rites? This doth betoken\nThe corse they follow did with desperate hand\nFordo its own life: 'twas of some estate.\nCouch we awhile, and mark.","sourceLine":"5.1.215","speaker":"HAMLET","id":"hamlet:5.1:98"},{"kind":"stage","text":"Retiring with HORATIO","id":"hamlet:5.1:99"},{"kind":"speech","text":"What ceremony else?","sourceLine":"5.1.220","speaker":"LAERTES","id":"hamlet:5.1:100"},{"kind":"speech","text":"That is Laertes,\nA very noble youth: mark.","sourceLine":"5.1.221","speaker":"HAMLET","id":"hamlet:5.1:101"},{"kind":"speech","text":"What ceremony else?","sourceLine":"5.1.223","speaker":"LAERTES","id":"hamlet:5.1:102"},{"kind":"speech","text":"Her obsequies have been as far enlarged\nAs we have warrantise: her death was doubtful;\nAnd, but that great command o'ersways the order,\nShe should in ground unsanctified have lodged\nTill the last trumpet: for charitable prayers,\nShards, flints and pebbles should be thrown on her;\nYet here she is allow'd her virgin crants,\nHer maiden strewments and the bringing home\nOf bell and burial.","sourceLine":"5.1.224","speaker":"First Priest","id":"hamlet:5.1:103"},{"kind":"speech","text":"Must there no more be done?","sourceLine":"5.1.233","speaker":"LAERTES","id":"hamlet:5.1:104"},{"kind":"speech","text":"No more be done:\nWe should profane the service of the dead\nTo sing a requiem and such rest to her\nAs to peace-parted souls.","sourceLine":"5.1.234","speaker":"First Priest","id":"hamlet:5.1:105"},{"kind":"speech","text":"Lay her i' the earth:\nAnd from her fair and unpolluted flesh\nMay violets spring! I tell thee, churlish priest,\nA ministering angel shall my sister be,\nWhen thou liest howling.","sourceLine":"5.1.238","speaker":"LAERTES","id":"hamlet:5.1:106"},{"kind":"speech","text":"What, the fair Ophelia!","sourceLine":"5.1.243","speaker":"HAMLET","id":"hamlet:5.1:107"},{"kind":"speech","text":"Sweets to the sweet: farewell!","sourceLine":"5.1.244","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:108"},{"kind":"stage","text":"Scattering flowers","id":"hamlet:5.1:109"},{"kind":"speech","text":"I hoped thou shouldst have been my Hamlet's wife;\nI thought thy bride-bed to have deck'd, sweet maid,\nAnd not have strew'd thy grave.","sourceLine":"5.1.245","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:110"},{"kind":"speech","text":"O, treble woe\nFall ten times treble on that cursed head,\nWhose wicked deed thy most ingenious sense\nDeprived thee of! Hold off the earth awhile,\nTill I have caught her once more in mine arms:","sourceLine":"5.1.248","speaker":"LAERTES","id":"hamlet:5.1:111"},{"kind":"stage","text":"Leaps into the grave","id":"hamlet:5.1:112"},{"kind":"speech","text":"Now pile your dust upon the quick and dead,\nTill of this flat a mountain you have made,\nTo o'ertop old Pelion, or the skyish head\nOf blue Olympus.","sourceLine":"5.1.253","speaker":"LAERTES","id":"hamlet:5.1:113"},{"kind":"speech","text":"[Advancing] What is he whose grief\nBears such an emphasis? whose phrase of sorrow\nConjures the wandering stars, and makes them stand\nLike wonder-wounded hearers? This is I,\nHamlet the Dane.","sourceLine":"5.1.257","speaker":"HAMLET","id":"hamlet:5.1:114"},{"kind":"stage","text":"Leaps into the grave","id":"hamlet:5.1:115"},{"kind":"speech","text":"The devil take thy soul!","sourceLine":"5.1.262","speaker":"LAERTES","id":"hamlet:5.1:116"},{"kind":"stage","text":"Grappling with him","id":"hamlet:5.1:117"},{"kind":"speech","text":"Thou pray'st not well.\nI prithee, take thy fingers from my throat;\nFor, though I am not splenitive and rash,\nYet have I something in me dangerous,\nWhich let thy wiseness fear: hold off thy hand.","sourceLine":"5.1.263","speaker":"HAMLET","id":"hamlet:5.1:118"},{"kind":"speech","text":"Pluck them asunder.","sourceLine":"5.1.268","speaker":"KING CLAUDIUS","id":"hamlet:5.1:119"},{"kind":"speech","text":"Hamlet, Hamlet!","sourceLine":"5.1.269","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:120"},{"kind":"speech","text":"Gentlemen,--","sourceLine":"5.1.270","speaker":"All","id":"hamlet:5.1:121"},{"kind":"speech","text":"Good my lord, be quiet.","sourceLine":"5.1.271","speaker":"HORATIO","id":"hamlet:5.1:122"},{"kind":"stage","text":"The Attendants part them, and they come out of the grave","id":"hamlet:5.1:123"},{"kind":"speech","text":"Why I will fight with him upon this theme\nUntil my eyelids will no longer wag.","sourceLine":"5.1.272","speaker":"HAMLET","id":"hamlet:5.1:124"},{"kind":"speech","text":"O my son, what theme?","sourceLine":"5.1.274","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:125"},{"kind":"speech","text":"I loved Ophelia: forty thousand brothers\nCould not, with all their quantity of love,\nMake up my sum. What wilt thou do for her?","sourceLine":"5.1.275","speaker":"HAMLET","id":"hamlet:5.1:126"},{"kind":"speech","text":"O, he is mad, Laertes.","sourceLine":"5.1.278","speaker":"KING CLAUDIUS","id":"hamlet:5.1:127"},{"kind":"speech","text":"For love of God, forbear him.","sourceLine":"5.1.279","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:128"},{"kind":"speech","text":"'Swounds, show me what thou'lt do:\nWoo't weep? woo't fight? woo't fast? woo't tear thyself?\nWoo't drink up eisel? eat a crocodile?\nI'll do't. Dost thou come here to whine?\nTo outface me with leaping in her grave?\nBe buried quick with her, and so will I:\nAnd, if thou prate of mountains, let them throw\nMillions of acres on us, till our ground,\nSingeing his pate against the burning zone,\nMake Ossa like a wart! Nay, an thou'lt mouth,\nI'll rant as well as thou.","sourceLine":"5.1.280","speaker":"HAMLET","id":"hamlet:5.1:129"},{"kind":"speech","text":"This is mere madness:\nAnd thus awhile the fit will work on him;\nAnon, as patient as the female dove,\nWhen that her golden couplets are disclosed,\nHis silence will sit drooping.","sourceLine":"5.1.291","speaker":"QUEEN GERTRUDE","id":"hamlet:5.1:130"},{"kind":"speech","text":"Hear you, sir;\nWhat is the reason that you use me thus?\nI loved you ever: but it is no matter;\nLet Hercules himself do what he may,\nThe cat will mew and dog will have his day.","sourceLine":"5.1.296","speaker":"HAMLET","id":"hamlet:5.1:131"},{"kind":"stage","text":"Exit","id":"hamlet:5.1:132"},{"kind":"speech","text":"I pray you, good Horatio, wait upon him.","sourceLine":"5.1.301","speaker":"KING CLAUDIUS","id":"hamlet:5.1:133"},{"kind":"stage","text":"Exit HORATIO","id":"hamlet:5.1:134"},{"kind":"stage","text":"To LAERTES","id":"hamlet:5.1:135"},{"kind":"speech","text":"Strengthen your patience in our last night's speech;\nWe'll put the matter to the present push.\nGood Gertrude, set some watch over your son.\nThis grave shall have a living monument:\nAn hour of quiet shortly shall we see;\nTill then, in patience our proceeding be.","sourceLine":"5.1.302","speaker":"KING CLAUDIUS","id":"hamlet:5.1:136"},{"kind":"stage","text":"Exeunt","id":"hamlet:5.1:137"}],"scene":1},{"id":"5.2","label":"Act 5 · SCENE II. A hall in the castle.","act":5,"sourceUrl":"https://shakespeare.mit.edu/hamlet/full.html","blocks":[{"kind":"stage","text":"Enter HAMLET and HORATIO","id":"hamlet:5.2:1"},{"kind":"speech","text":"So much for this, sir: now shall you see the other;\nYou do remember all the circumstance?","sourceLine":"5.2.1","speaker":"HAMLET","id":"hamlet:5.2:2"},{"kind":"speech","text":"Remember it, my lord?","sourceLine":"5.2.3","speaker":"HORATIO","id":"hamlet:5.2:3"},{"kind":"speech","text":"Sir, in my heart there was a kind of fighting,\nThat would not let me sleep: methought I lay\nWorse than the mutines in the bilboes. Rashly,\nAnd praised be rashness for it, let us know,\nOur indiscretion sometimes serves us well,\nWhen our deep plots do pall: and that should teach us\nThere's a divinity that shapes our ends,\nRough-hew them how we will,--","sourceLine":"5.2.4","speaker":"HAMLET","id":"hamlet:5.2:4"},{"kind":"speech","text":"That is most certain.","sourceLine":"5.2.12","speaker":"HORATIO","id":"hamlet:5.2:5"},{"kind":"speech","text":"Up from my cabin,\nMy sea-gown scarf'd about me, in the dark\nGroped I to find out them; had my desire.\nFinger'd their packet, and in fine withdrew\nTo mine own room again; making so bold,\nMy fears forgetting manners, to unseal\nTheir grand commission; where I found, Horatio,--\nO royal knavery!--an exact command,\nLarded with many several sorts of reasons\nImporting Denmark's health and England's too,\nWith, ho! such bugs and goblins in my life,\nThat, on the supervise, no leisure bated,\nNo, not to stay the grinding of the axe,\nMy head should be struck off.","sourceLine":"5.2.13","speaker":"HAMLET","id":"hamlet:5.2:6"},{"kind":"speech","text":"Is't possible?","sourceLine":"5.2.27","speaker":"HORATIO","id":"hamlet:5.2:7"},{"kind":"speech","text":"Here's the commission: read it at more leisure.\nBut wilt thou hear me how I did proceed?","sourceLine":"5.2.28","speaker":"HAMLET","id":"hamlet:5.2:8"},{"kind":"speech","text":"I beseech you.","sourceLine":"5.2.30","speaker":"HORATIO","id":"hamlet:5.2:9"},{"kind":"speech","text":"Being thus be-netted round with villanies,--\nEre I could make a prologue to my brains,\nThey had begun the play--I sat me down,\nDevised a new commission, wrote it fair:\nI once did hold it, as our statists do,\nA baseness to write fair and labour'd much\nHow to forget that learning, but, sir, now\nIt did me yeoman's service: wilt thou know\nThe effect of what I wrote?","sourceLine":"5.2.31","speaker":"HAMLET","id":"hamlet:5.2:10"},{"kind":"speech","text":"Ay, good my lord.","sourceLine":"5.2.40","speaker":"HORATIO","id":"hamlet:5.2:11"},{"kind":"speech","text":"An earnest conjuration from the king,\nAs England was his faithful tributary,\nAs love between them like the palm might flourish,\nAs peace should stiff her wheaten garland wear\nAnd stand a comma 'tween their amities,\nAnd many such-like 'As'es of great charge,\nThat, on the view and knowing of these contents,\nWithout debatement further, more or less,\nHe should the bearers put to sudden death,\nNot shriving-time allow'd.","sourceLine":"5.2.41","speaker":"HAMLET","id":"hamlet:5.2:12"},{"kind":"speech","text":"How was this seal'd?","sourceLine":"5.2.51","speaker":"HORATIO","id":"hamlet:5.2:13"},{"kind":"speech","text":"Why, even in that was heaven ordinant.\nI had my father's signet in my purse,\nWhich was the model of that Danish seal;\nFolded the writ up in form of the other,\nSubscribed it, gave't the impression, placed it safely,\nThe changeling never known. Now, the next day\nWas our sea-fight; and what to this was sequent\nThou know'st already.","sourceLine":"5.2.52","speaker":"HAMLET","id":"hamlet:5.2:14"},{"kind":"speech","text":"So Guildenstern and Rosencrantz go to't.","sourceLine":"5.2.60","speaker":"HORATIO","id":"hamlet:5.2:15"},{"kind":"speech","text":"Why, man, they did make love to this employment;\nThey are not near my conscience; their defeat\nDoes by their own insinuation grow:\n'Tis dangerous when the baser nature comes\nBetween the pass and fell incensed points\nOf mighty opposites.","sourceLine":"5.2.61","speaker":"HAMLET","id":"hamlet:5.2:16"},{"kind":"speech","text":"Why, what a king is this!","sourceLine":"5.2.67","speaker":"HORATIO","id":"hamlet:5.2:17"},{"kind":"speech","text":"Does it not, think'st thee, stand me now upon--\nHe that hath kill'd my king and whored my mother,\nPopp'd in between the election and my hopes,\nThrown out his angle for my proper life,\nAnd with such cozenage--is't not perfect conscience,\nTo quit him with this arm? and is't not to be damn'd,\nTo let this canker of our nature come\nIn further evil?","sourceLine":"5.2.68","speaker":"HAMLET","id":"hamlet:5.2:18"},{"kind":"speech","text":"It must be shortly known to him from England\nWhat is the issue of the business there.","sourceLine":"5.2.76","speaker":"HORATIO","id":"hamlet:5.2:19"},{"kind":"speech","text":"It will be short: the interim is mine;\nAnd a man's life's no more than to say 'One.'\nBut I am very sorry, good Horatio,\nThat to Laertes I forgot myself;\nFor, by the image of my cause, I see\nThe portraiture of his: I'll court his favours.\nBut, sure, the bravery of his grief did put me\nInto a towering passion.","sourceLine":"5.2.78","speaker":"HAMLET","id":"hamlet:5.2:20"},{"kind":"speech","text":"Peace! who comes here?","sourceLine":"5.2.86","speaker":"HORATIO","id":"hamlet:5.2:21"},{"kind":"stage","text":"Enter OSRIC","id":"hamlet:5.2:22"},{"kind":"speech","text":"Your lordship is right welcome back to Denmark.","sourceLine":"5.2.87","speaker":"OSRIC","id":"hamlet:5.2:23"},{"kind":"speech","text":"I humbly thank you, sir. Dost know this water-fly?","sourceLine":"5.2.88","speaker":"HAMLET","id":"hamlet:5.2:24"},{"kind":"speech","text":"No, my good lord.","sourceLine":"5.2.89","speaker":"HORATIO","id":"hamlet:5.2:25"},{"kind":"speech","text":"Thy state is the more gracious; for 'tis a vice to\nknow him. He hath much land, and fertile: let a\nbeast be lord of beasts, and his crib shall stand at\nthe king's mess: 'tis a chough; but, as I say,\nspacious in the possession of dirt.","sourceLine":"5.2.90","speaker":"HAMLET","id":"hamlet:5.2:26"},{"kind":"speech","text":"Sweet lord, if your lordship were at leisure, I\nshould impart a thing to you from his majesty.","sourceLine":"5.2.95","speaker":"OSRIC","id":"hamlet:5.2:27"},{"kind":"speech","text":"I will receive it, sir, with all diligence of\nspirit. Put your bonnet to his right use; 'tis for the head.","sourceLine":"5.2.97","speaker":"HAMLET","id":"hamlet:5.2:28"},{"kind":"speech","text":"I thank your lordship, it is very hot.","sourceLine":"5.2.99","speaker":"OSRIC","id":"hamlet:5.2:29"},{"kind":"speech","text":"No, believe me, 'tis very cold; the wind is\nnortherly.","sourceLine":"5.2.100","speaker":"HAMLET","id":"hamlet:5.2:30"},{"kind":"speech","text":"It is indifferent cold, my lord, indeed.","sourceLine":"5.2.102","speaker":"OSRIC","id":"hamlet:5.2:31"},{"kind":"speech","text":"But yet methinks it is very sultry and hot for my\ncomplexion.","sourceLine":"5.2.103","speaker":"HAMLET","id":"hamlet:5.2:32"},{"kind":"speech","text":"Exceedingly, my lord; it is very sultry,--as\n'twere,--I cannot tell how. But, my lord, his\nmajesty bade me signify to you that he has laid a\ngreat wager on your head: sir, this is the matter,--","sourceLine":"5.2.105","speaker":"OSRIC","id":"hamlet:5.2:33"},{"kind":"speech","text":"I beseech you, remember--","sourceLine":"5.2.109","speaker":"HAMLET","id":"hamlet:5.2:34"},{"kind":"stage","text":"HAMLET moves him to put on his hat","id":"hamlet:5.2:35"},{"kind":"speech","text":"Nay, good my lord; for mine ease, in good faith.\nSir, here is newly come to court Laertes; believe\nme, an absolute gentleman, full of most excellent\ndifferences, of very soft society and great showing:\nindeed, to speak feelingly of him, he is the card or\ncalendar of gentry, for you shall find in him the\ncontinent of what part a gentleman would see.","sourceLine":"5.2.110","speaker":"OSRIC","id":"hamlet:5.2:36"},{"kind":"speech","text":"Sir, his definement suffers no perdition in you;\nthough, I know, to divide him inventorially would\ndizzy the arithmetic of memory, and yet but yaw\nneither, in respect of his quick sail. But, in the\nverity of extolment, I take him to be a soul of\ngreat article; and his infusion of such dearth and\nrareness, as, to make true diction of him, his\nsemblable is his mirror; and who else would trace\nhim, his umbrage, nothing more.","sourceLine":"5.2.117","speaker":"HAMLET","id":"hamlet:5.2:37"},{"kind":"speech","text":"Your lordship speaks most infallibly of him.","sourceLine":"5.2.126","speaker":"OSRIC","id":"hamlet:5.2:38"},{"kind":"speech","text":"The concernancy, sir? why do we wrap the gentleman\nin our more rawer breath?","sourceLine":"5.2.127","speaker":"HAMLET","id":"hamlet:5.2:39"},{"kind":"speech","text":"Sir?","sourceLine":"5.2.129","speaker":"OSRIC","id":"hamlet:5.2:40"},{"kind":"speech","text":"Is't not possible to understand in another tongue?\nYou will do't, sir, really.","sourceLine":"5.2.130","speaker":"HORATIO","id":"hamlet:5.2:41"},{"kind":"speech","text":"What imports the nomination of this gentleman?","sourceLine":"5.2.132","speaker":"HAMLET","id":"hamlet:5.2:42"},{"kind":"speech","text":"Of Laertes?","sourceLine":"5.2.133","speaker":"OSRIC","id":"hamlet:5.2:43"},{"kind":"speech","text":"His purse is empty already; all's golden words are spent.","sourceLine":"5.2.134","speaker":"HORATIO","id":"hamlet:5.2:44"},{"kind":"speech","text":"Of him, sir.","sourceLine":"5.2.135","speaker":"HAMLET","id":"hamlet:5.2:45"},{"kind":"speech","text":"I know you are not ignorant--","sourceLine":"5.2.136","speaker":"OSRIC","id":"hamlet:5.2:46"},{"kind":"speech","text":"I would you did, sir; yet, in faith, if you did,\nit would not much approve me. Well, sir?","sourceLine":"5.2.137","speaker":"HAMLET","id":"hamlet:5.2:47"},{"kind":"speech","text":"You are not ignorant of what excellence Laertes is--","sourceLine":"5.2.139","speaker":"OSRIC","id":"hamlet:5.2:48"},{"kind":"speech","text":"I dare not confess that, lest I should compare with\nhim in excellence; but, to know a man well, were to\nknow himself.","sourceLine":"5.2.140","speaker":"HAMLET","id":"hamlet:5.2:49"},{"kind":"speech","text":"I mean, sir, for his weapon; but in the imputation\nlaid on him by them, in his meed he's unfellowed.","sourceLine":"5.2.143","speaker":"OSRIC","id":"hamlet:5.2:50"},{"kind":"speech","text":"What's his weapon?","sourceLine":"5.2.145","speaker":"HAMLET","id":"hamlet:5.2:51"},{"kind":"speech","text":"Rapier and dagger.","sourceLine":"5.2.146","speaker":"OSRIC","id":"hamlet:5.2:52"},{"kind":"speech","text":"That's two of his weapons: but, well.","sourceLine":"5.2.147","speaker":"HAMLET","id":"hamlet:5.2:53"},{"kind":"speech","text":"The king, sir, hath wagered with him six Barbary\nhorses: against the which he has imponed, as I take\nit, six French rapiers and poniards, with their\nassigns, as girdle, hangers, and so: three of the\ncarriages, in faith, are very dear to fancy, very\nresponsive to the hilts, most delicate carriages,\nand of very liberal conceit.","sourceLine":"5.2.148","speaker":"OSRIC","id":"hamlet:5.2:54"},{"kind":"speech","text":"What call you the carriages?","sourceLine":"5.2.155","speaker":"HAMLET","id":"hamlet:5.2:55"},{"kind":"speech","text":"I knew you must be edified by the margent ere you had done.","sourceLine":"5.2.156","speaker":"HORATIO","id":"hamlet:5.2:56"},{"kind":"speech","text":"The carriages, sir, are the hangers.","sourceLine":"5.2.157","speaker":"OSRIC","id":"hamlet:5.2:57"},{"kind":"speech","text":"The phrase would be more german to the matter, if we\ncould carry cannon by our sides: I would it might\nbe hangers till then. But, on: six Barbary horses\nagainst six French swords, their assigns, and three\nliberal-conceited carriages; that's the French bet\nagainst the Danish. Why is this 'imponed,' as you call it?","sourceLine":"5.2.158","speaker":"HAMLET","id":"hamlet:5.2:58"},{"kind":"speech","text":"The king, sir, hath laid, that in a dozen passes\nbetween yourself and him, he shall not exceed you\nthree hits: he hath laid on twelve for nine; and it\nwould come to immediate trial, if your lordship\nwould vouchsafe the answer.","sourceLine":"5.2.164","speaker":"OSRIC","id":"hamlet:5.2:59"},{"kind":"speech","text":"How if I answer 'no'?","sourceLine":"5.2.169","speaker":"HAMLET","id":"hamlet:5.2:60"},{"kind":"speech","text":"I mean, my lord, the opposition of your person in trial.","sourceLine":"5.2.170","speaker":"OSRIC","id":"hamlet:5.2:61"},{"kind":"speech","text":"Sir, I will walk here in the hall: if it please his\nmajesty, 'tis the breathing time of day with me; let\nthe foils be brought, the gentleman willing, and the\nking hold his purpose, I will win for him an I can;\nif not, I will gain nothing but my shame and the odd hits.","sourceLine":"5.2.171","speaker":"HAMLET","id":"hamlet:5.2:62"},{"kind":"speech","text":"Shall I re-deliver you e'en so?","sourceLine":"5.2.176","speaker":"OSRIC","id":"hamlet:5.2:63"},{"kind":"speech","text":"To this effect, sir; after what flourish your nature will.","sourceLine":"5.2.177","speaker":"HAMLET","id":"hamlet:5.2:64"},{"kind":"speech","text":"I commend my duty to your lordship.","sourceLine":"5.2.178","speaker":"OSRIC","id":"hamlet:5.2:65"},{"kind":"speech","text":"Yours, yours.","sourceLine":"5.2.179","speaker":"HAMLET","id":"hamlet:5.2:66"},{"kind":"stage","text":"Exit OSRIC","id":"hamlet:5.2:67"},{"kind":"speech","text":"He does well to commend it himself; there are no\ntongues else for's turn.","sourceLine":"5.2.180","speaker":"HAMLET","id":"hamlet:5.2:68"},{"kind":"speech","text":"This lapwing runs away with the shell on his head.","sourceLine":"5.2.182","speaker":"HORATIO","id":"hamlet:5.2:69"},{"kind":"speech","text":"He did comply with his dug, before he sucked it.\nThus has he--and many more of the same bevy that I\nknow the dressy age dotes on--only got the tune of\nthe time and outward habit of encounter; a kind of\nyesty collection, which carries them through and\nthrough the most fond and winnowed opinions; and do\nbut blow them to their trial, the bubbles are out.","sourceLine":"5.2.183","speaker":"HAMLET","id":"hamlet:5.2:70"},{"kind":"stage","text":"Enter a Lord","id":"hamlet:5.2:71"},{"kind":"speech","text":"My lord, his majesty commended him to you by young\nOsric, who brings back to him that you attend him in\nthe hall: he sends to know if your pleasure hold to\nplay with Laertes, or that you will take longer time.","sourceLine":"5.2.190","speaker":"Lord","id":"hamlet:5.2:72"},{"kind":"speech","text":"I am constant to my purpose; they follow the king's\npleasure: if his fitness speaks, mine is ready; now\nor whensoever, provided I be so able as now.","sourceLine":"5.2.194","speaker":"HAMLET","id":"hamlet:5.2:73"},{"kind":"speech","text":"The king and queen and all are coming down.","sourceLine":"5.2.197","speaker":"Lord","id":"hamlet:5.2:74"},{"kind":"speech","text":"In happy time.","sourceLine":"5.2.198","speaker":"HAMLET","id":"hamlet:5.2:75"},{"kind":"speech","text":"The queen desires you to use some gentle\nentertainment to Laertes before you fall to play.","sourceLine":"5.2.199","speaker":"Lord","id":"hamlet:5.2:76"},{"kind":"speech","text":"She well instructs me.","sourceLine":"5.2.201","speaker":"HAMLET","id":"hamlet:5.2:77"},{"kind":"stage","text":"Exit Lord","id":"hamlet:5.2:78"},{"kind":"speech","text":"You will lose this wager, my lord.","sourceLine":"5.2.202","speaker":"HORATIO","id":"hamlet:5.2:79"},{"kind":"speech","text":"I do not think so: since he went into France, I\nhave been in continual practise: I shall win at the\nodds. But thou wouldst not think how ill all's here\nabout my heart: but it is no matter.","sourceLine":"5.2.203","speaker":"HAMLET","id":"hamlet:5.2:80"},{"kind":"speech","text":"Nay, good my lord,--","sourceLine":"5.2.207","speaker":"HORATIO","id":"hamlet:5.2:81"},{"kind":"speech","text":"It is but foolery; but it is such a kind of\ngain-giving, as would perhaps trouble a woman.","sourceLine":"5.2.208","speaker":"HAMLET","id":"hamlet:5.2:82"},{"kind":"speech","text":"If your mind dislike any thing, obey it: I will\nforestall their repair hither, and say you are not\nfit.","sourceLine":"5.2.210","speaker":"HORATIO","id":"hamlet:5.2:83"},{"kind":"speech","text":"Not a whit, we defy augury: there's a special\nprovidence in the fall of a sparrow. If it be now,\n'tis not to come; if it be not to come, it will be\nnow; if it be not now, yet it will come: the\nreadiness is all: since no man has aught of what he\nleaves, what is't to leave betimes?","sourceLine":"5.2.213","speaker":"HAMLET","id":"hamlet:5.2:84"},{"kind":"stage","text":"Enter KING CLAUDIUS, QUEEN GERTRUDE, LAERTES, Lords, OSRIC, and Attendants with foils, & c","id":"hamlet:5.2:85"},{"kind":"speech","text":"Come, Hamlet, come, and take this hand from me.","sourceLine":"5.2.219","speaker":"KING CLAUDIUS","id":"hamlet:5.2:86"},{"kind":"stage","text":"KING CLAUDIUS puts LAERTES' hand into HAMLET's","id":"hamlet:5.2:87"},{"kind":"speech","text":"Give me your pardon, sir: I've done you wrong;\nBut pardon't, as you are a gentleman.\nThis presence knows,\nAnd you must needs have heard, how I am punish'd\nWith sore distraction. What I have done,\nThat might your nature, honour and exception\nRoughly awake, I here proclaim was madness.\nWas't Hamlet wrong'd Laertes? Never Hamlet:\nIf Hamlet from himself be ta'en away,\nAnd when he's not himself does wrong Laertes,\nThen Hamlet does it not, Hamlet denies it.\nWho does it, then? His madness: if't be so,\nHamlet is of the faction that is wrong'd;\nHis madness is poor Hamlet's enemy.\nSir, in this audience,\nLet my disclaiming from a purposed evil\nFree me so far in your most generous thoughts,\nThat I have shot mine arrow o'er the house,\nAnd hurt my brother.","sourceLine":"5.2.220","speaker":"HAMLET","id":"hamlet:5.2:88"},{"kind":"speech","text":"I am satisfied in nature,\nWhose motive, in this case, should stir me most\nTo my revenge: but in my terms of honour\nI stand aloof; and will no reconcilement,\nTill by some elder masters, of known honour,\nI have a voice and precedent of peace,\nTo keep my name ungored. But till that time,\nI do receive your offer'd love like love,\nAnd will not wrong it.","sourceLine":"5.2.239","speaker":"LAERTES","id":"hamlet:5.2:89"},{"kind":"speech","text":"I embrace it freely;\nAnd will this brother's wager frankly play.\nGive us the foils. Come on.","sourceLine":"5.2.248","speaker":"HAMLET","id":"hamlet:5.2:90"},{"kind":"speech","text":"Come, one for me.","sourceLine":"5.2.251","speaker":"LAERTES","id":"hamlet:5.2:91"},{"kind":"speech","text":"I'll be your foil, Laertes: in mine ignorance\nYour skill shall, like a star i' the darkest night,\nStick fiery off indeed.","sourceLine":"5.2.252","speaker":"HAMLET","id":"hamlet:5.2:92"},{"kind":"speech","text":"You mock me, sir.","sourceLine":"5.2.255","speaker":"LAERTES","id":"hamlet:5.2:93"},{"kind":"speech","text":"No, by this hand.","sourceLine":"5.2.256","speaker":"HAMLET","id":"hamlet:5.2:94"},{"kind":"speech","text":"Give them the foils, young Osric. Cousin Hamlet,\nYou know the wager?","sourceLine":"5.2.257","speaker":"KING CLAUDIUS","id":"hamlet:5.2:95"},{"kind":"speech","text":"Very well, my lord\nYour grace hath laid the odds o' the weaker side.","sourceLine":"5.2.259","speaker":"HAMLET","id":"hamlet:5.2:96"},{"kind":"speech","text":"I do not fear it; I have seen you both:\nBut since he is better'd, we have therefore odds.","sourceLine":"5.2.261","speaker":"KING CLAUDIUS","id":"hamlet:5.2:97"},{"kind":"speech","text":"This is too heavy, let me see another.","sourceLine":"5.2.263","speaker":"LAERTES","id":"hamlet:5.2:98"},{"kind":"speech","text":"This likes me well. These foils have all a length?","sourceLine":"5.2.264","speaker":"HAMLET","id":"hamlet:5.2:99"},{"kind":"stage","text":"They prepare to play","id":"hamlet:5.2:100"},{"kind":"speech","text":"Ay, my good lord.","sourceLine":"5.2.265","speaker":"OSRIC","id":"hamlet:5.2:101"},{"kind":"speech","text":"Set me the stoops of wine upon that table.\nIf Hamlet give the first or second hit,\nOr quit in answer of the third exchange,\nLet all the battlements their ordnance fire:\nThe king shall drink to Hamlet's better breath;\nAnd in the cup an union shall he throw,\nRicher than that which four successive kings\nIn Denmark's crown have worn. Give me the cups;\nAnd let the kettle to the trumpet speak,\nThe trumpet to the cannoneer without,\nThe cannons to the heavens, the heavens to earth,\n'Now the king dunks to Hamlet.' Come, begin:\nAnd you, the judges, bear a wary eye.","sourceLine":"5.2.266","speaker":"KING CLAUDIUS","id":"hamlet:5.2:102"},{"kind":"speech","text":"Come on, sir.","sourceLine":"5.2.279","speaker":"HAMLET","id":"hamlet:5.2:103"},{"kind":"speech","text":"Come, my lord.","sourceLine":"5.2.280","speaker":"LAERTES","id":"hamlet:5.2:104"},{"kind":"stage","text":"They play","id":"hamlet:5.2:105"},{"kind":"speech","text":"One.","sourceLine":"5.2.281","speaker":"HAMLET","id":"hamlet:5.2:106"},{"kind":"speech","text":"No.","sourceLine":"5.2.282","speaker":"LAERTES","id":"hamlet:5.2:107"},{"kind":"speech","text":"Judgment.","sourceLine":"5.2.283","speaker":"HAMLET","id":"hamlet:5.2:108"},{"kind":"speech","text":"A hit, a very palpable hit.","sourceLine":"5.2.284","speaker":"OSRIC","id":"hamlet:5.2:109"},{"kind":"speech","text":"Well; again.","sourceLine":"5.2.285","speaker":"LAERTES","id":"hamlet:5.2:110"},{"kind":"speech","text":"Stay; give me drink. Hamlet, this pearl is thine;\nHere's to thy health.","sourceLine":"5.2.286","speaker":"KING CLAUDIUS","id":"hamlet:5.2:111"},{"kind":"stage","text":"Trumpets sound, and cannon shot off within","id":"hamlet:5.2:112"},{"kind":"speech","text":"Give him the cup.","sourceLine":"5.2.288","speaker":"KING CLAUDIUS","id":"hamlet:5.2:113"},{"kind":"speech","text":"I'll play this bout first; set it by awhile. Come.","sourceLine":"5.2.289","speaker":"HAMLET","id":"hamlet:5.2:114"},{"kind":"stage","text":"They play","id":"hamlet:5.2:115"},{"kind":"speech","text":"Another hit; what say you?","sourceLine":"5.2.290","speaker":"HAMLET","id":"hamlet:5.2:116"},{"kind":"speech","text":"A touch, a touch, I do confess.","sourceLine":"5.2.291","speaker":"LAERTES","id":"hamlet:5.2:117"},{"kind":"speech","text":"Our son shall win.","sourceLine":"5.2.292","speaker":"KING CLAUDIUS","id":"hamlet:5.2:118"},{"kind":"speech","text":"He's fat, and scant of breath.\nHere, Hamlet, take my napkin, rub thy brows;\nThe queen carouses to thy fortune, Hamlet.","sourceLine":"5.2.293","speaker":"QUEEN GERTRUDE","id":"hamlet:5.2:119"},{"kind":"speech","text":"Good madam!","sourceLine":"5.2.296","speaker":"HAMLET","id":"hamlet:5.2:120"},{"kind":"speech","text":"Gertrude, do not drink.","sourceLine":"5.2.297","speaker":"KING CLAUDIUS","id":"hamlet:5.2:121"},{"kind":"speech","text":"I will, my lord; I pray you, pardon me.","sourceLine":"5.2.298","speaker":"QUEEN GERTRUDE","id":"hamlet:5.2:122"},{"kind":"speech","text":"[Aside] It is the poison'd cup: it is too late.","sourceLine":"5.2.299","speaker":"KING CLAUDIUS","id":"hamlet:5.2:123"},{"kind":"speech","text":"I dare not drink yet, madam; by and by.","sourceLine":"5.2.300","speaker":"HAMLET","id":"hamlet:5.2:124"},{"kind":"speech","text":"Come, let me wipe thy face.","sourceLine":"5.2.301","speaker":"QUEEN GERTRUDE","id":"hamlet:5.2:125"},{"kind":"speech","text":"My lord, I'll hit him now.","sourceLine":"5.2.302","speaker":"LAERTES","id":"hamlet:5.2:126"},{"kind":"speech","text":"I do not think't.","sourceLine":"5.2.303","speaker":"KING CLAUDIUS","id":"hamlet:5.2:127"},{"kind":"speech","text":"[Aside] And yet 'tis almost 'gainst my conscience.","sourceLine":"5.2.304","speaker":"LAERTES","id":"hamlet:5.2:128"},{"kind":"speech","text":"Come, for the third, Laertes: you but dally;\nI pray you, pass with your best violence;\nI am afeard you make a wanton of me.","sourceLine":"5.2.305","speaker":"HAMLET","id":"hamlet:5.2:129"},{"kind":"speech","text":"Say you so? come on.","sourceLine":"5.2.308","speaker":"LAERTES","id":"hamlet:5.2:130"},{"kind":"stage","text":"They play","id":"hamlet:5.2:131"},{"kind":"speech","text":"Nothing, neither way.","sourceLine":"5.2.309","speaker":"OSRIC","id":"hamlet:5.2:132"},{"kind":"speech","text":"Have at you now!","sourceLine":"5.2.310","speaker":"LAERTES","id":"hamlet:5.2:133"},{"kind":"stage","text":"LAERTES wounds HAMLET; then in scuffling, they change rapiers, and HAMLET wounds LAERTES","id":"hamlet:5.2:134"},{"kind":"speech","text":"Part them; they are incensed.","sourceLine":"5.2.311","speaker":"KING CLAUDIUS","id":"hamlet:5.2:135"},{"kind":"speech","text":"Nay, come, again.","sourceLine":"5.2.312","speaker":"HAMLET","id":"hamlet:5.2:136"},{"kind":"stage","text":"QUEEN GERTRUDE falls","id":"hamlet:5.2:137"},{"kind":"speech","text":"Look to the queen there, ho!","sourceLine":"5.2.313","speaker":"OSRIC","id":"hamlet:5.2:138"},{"kind":"speech","text":"They bleed on both sides. How is it, my lord?","sourceLine":"5.2.314","speaker":"HORATIO","id":"hamlet:5.2:139"},{"kind":"speech","text":"How is't, Laertes?","sourceLine":"5.2.315","speaker":"OSRIC","id":"hamlet:5.2:140"},{"kind":"speech","text":"Why, as a woodcock to mine own springe, Osric;\nI am justly kill'd with mine own treachery.","sourceLine":"5.2.316","speaker":"LAERTES","id":"hamlet:5.2:141"},{"kind":"speech","text":"How does the queen?","sourceLine":"5.2.318","speaker":"HAMLET","id":"hamlet:5.2:142"},{"kind":"speech","text":"She swounds to see them bleed.","sourceLine":"5.2.319","speaker":"KING CLAUDIUS","id":"hamlet:5.2:143"},{"kind":"speech","text":"No, no, the drink, the drink,--O my dear Hamlet,--\nThe drink, the drink! I am poison'd.","sourceLine":"5.2.320","speaker":"QUEEN GERTRUDE","id":"hamlet:5.2:144"},{"kind":"stage","text":"Dies","id":"hamlet:5.2:145"},{"kind":"speech","text":"O villany! Ho! let the door be lock'd:\nTreachery! Seek it out.","sourceLine":"5.2.322","speaker":"HAMLET","id":"hamlet:5.2:146"},{"kind":"speech","text":"It is here, Hamlet: Hamlet, thou art slain;\nNo medicine in the world can do thee good;\nIn thee there is not half an hour of life;\nThe treacherous instrument is in thy hand,\nUnbated and envenom'd: the foul practise\nHath turn'd itself on me lo, here I lie,\nNever to rise again: thy mother's poison'd:\nI can no more: the king, the king's to blame.","sourceLine":"5.2.324","speaker":"LAERTES","id":"hamlet:5.2:147"},{"kind":"speech","text":"The point!--envenom'd too!\nThen, venom, to thy work.","sourceLine":"5.2.332","speaker":"HAMLET","id":"hamlet:5.2:148"},{"kind":"stage","text":"Stabs KING CLAUDIUS","id":"hamlet:5.2:149"},{"kind":"speech","text":"Treason! treason!","sourceLine":"5.2.334","speaker":"All","id":"hamlet:5.2:150"},{"kind":"speech","text":"O, yet defend me, friends; I am but hurt.","sourceLine":"5.2.335","speaker":"KING CLAUDIUS","id":"hamlet:5.2:151"},{"kind":"speech","text":"Here, thou incestuous, murderous, damned Dane,\nDrink off this potion. Is thy union here?\nFollow my mother.","sourceLine":"5.2.336","speaker":"HAMLET","id":"hamlet:5.2:152"},{"kind":"stage","text":"KING CLAUDIUS dies","id":"hamlet:5.2:153"},{"kind":"speech","text":"He is justly served;\nIt is a poison temper'd by himself.\nExchange forgiveness with me, noble Hamlet:\nMine and my father's death come not upon thee,\nNor thine on me.","sourceLine":"5.2.339","speaker":"LAERTES","id":"hamlet:5.2:154"},{"kind":"stage","text":"Dies","id":"hamlet:5.2:155"},{"kind":"speech","text":"Heaven make thee free of it! I follow thee.\nI am dead, Horatio. Wretched queen, adieu!\nYou that look pale and tremble at this chance,\nThat are but mutes or audience to this act,\nHad I but time--as this fell sergeant, death,\nIs strict in his arrest--O, I could tell you--\nBut let it be. Horatio, I am dead;\nThou livest; report me and my cause aright\nTo the unsatisfied.","sourceLine":"5.2.344","speaker":"HAMLET","id":"hamlet:5.2:156"},{"kind":"speech","text":"Never believe it:\nI am more an antique Roman than a Dane:\nHere's yet some liquor left.","sourceLine":"5.2.353","speaker":"HORATIO","id":"hamlet:5.2:157"},{"kind":"speech","text":"As thou'rt a man,\nGive me the cup: let go; by heaven, I'll have't.\nO good Horatio, what a wounded name,\nThings standing thus unknown, shall live behind me!\nIf thou didst ever hold me in thy heart\nAbsent thee from felicity awhile,\nAnd in this harsh world draw thy breath in pain,\nTo tell my story.","sourceLine":"5.2.356","speaker":"HAMLET","id":"hamlet:5.2:158"},{"kind":"stage","text":"March afar off, and shot within","id":"hamlet:5.2:159"},{"kind":"speech","text":"What warlike noise is this?","sourceLine":"5.2.364","speaker":"HAMLET","id":"hamlet:5.2:160"},{"kind":"speech","text":"Young Fortinbras, with conquest come from Poland,\nTo the ambassadors of England gives\nThis warlike volley.","sourceLine":"5.2.365","speaker":"OSRIC","id":"hamlet:5.2:161"},{"kind":"speech","text":"O, I die, Horatio;\nThe potent poison quite o'er-crows my spirit:\nI cannot live to hear the news from England;\nBut I do prophesy the election lights\nOn Fortinbras: he has my dying voice;\nSo tell him, with the occurrents, more and less,\nWhich have solicited. The rest is silence.","sourceLine":"5.2.368","speaker":"HAMLET","id":"hamlet:5.2:162"},{"kind":"stage","text":"Dies","id":"hamlet:5.2:163"},{"kind":"speech","text":"Now cracks a noble heart. Good night sweet prince:\nAnd flights of angels sing thee to thy rest!\nWhy does the drum come hither?","sourceLine":"5.2.375","speaker":"HORATIO","id":"hamlet:5.2:164"},{"kind":"stage","text":"March within","id":"hamlet:5.2:165"},{"kind":"stage","text":"Enter FORTINBRAS, the English Ambassadors, and others","id":"hamlet:5.2:166"},{"kind":"speech","text":"Where is this sight?","sourceLine":"5.2.378","speaker":"PRINCE FORTINBRAS","id":"hamlet:5.2:167"},{"kind":"speech","text":"What is it ye would see?\nIf aught of woe or wonder, cease your search.","sourceLine":"5.2.379","speaker":"HORATIO","id":"hamlet:5.2:168"},{"kind":"speech","text":"This quarry cries on havoc. O proud death,\nWhat feast is toward in thine eternal cell,\nThat thou so many princes at a shot\nSo bloodily hast struck?","sourceLine":"5.2.381","speaker":"PRINCE FORTINBRAS","id":"hamlet:5.2:169"},{"kind":"speech","text":"The sight is dismal;\nAnd our affairs from England come too late:\nThe ears are senseless that should give us hearing,\nTo tell him his commandment is fulfill'd,\nThat Rosencrantz and Guildenstern are dead:\nWhere should we have our thanks?","sourceLine":"5.2.385","speaker":"First Ambassador","id":"hamlet:5.2:170"},{"kind":"speech","text":"Not from his mouth,\nHad it the ability of life to thank you:\nHe never gave commandment for their death.\nBut since, so jump upon this bloody question,\nYou from the Polack wars, and you from England,\nAre here arrived give order that these bodies\nHigh on a stage be placed to the view;\nAnd let me speak to the yet unknowing world\nHow these things came about: so shall you hear\nOf carnal, bloody, and unnatural acts,\nOf accidental judgments, casual slaughters,\nOf deaths put on by cunning and forced cause,\nAnd, in this upshot, purposes mistook\nFall'n on the inventors' reads: all this can I\nTruly deliver.","sourceLine":"5.2.391","speaker":"HORATIO","id":"hamlet:5.2:171"},{"kind":"speech","text":"Let us haste to hear it,\nAnd call the noblest to the audience.\nFor me, with sorrow I embrace my fortune:\nI have some rights of memory in this kingdom,\nWhich now to claim my vantage doth invite me.","sourceLine":"5.2.406","speaker":"PRINCE FORTINBRAS","id":"hamlet:5.2:172"},{"kind":"speech","text":"Of that I shall have also cause to speak,\nAnd from his mouth whose voice will draw on more;\nBut let this same be presently perform'd,\nEven while men's minds are wild; lest more mischance\nOn plots and errors, happen.","sourceLine":"5.2.411","speaker":"HORATIO","id":"hamlet:5.2:173"},{"kind":"speech","text":"Let four captains\nBear Hamlet, like a soldier, to the stage;\nFor he was likely, had he been put on,\nTo have proved most royally: and, for his passage,\nThe soldiers' music and the rites of war\nSpeak loudly for him.\nTake up the bodies: such a sight as this\nBecomes the field, but here shows much amiss.\nGo, bid the soldiers shoot.","sourceLine":"5.2.416","speaker":"PRINCE FORTINBRAS","id":"hamlet:5.2:174"},{"kind":"stage","text":"A dead march. Exeunt, bearing off the dead bodies; after which a peal of ordnance is shot off","id":"hamlet:5.2:175"}],"scene":2}],"sourceLineCount":4011,"sourceLabel":"MIT Shakespeare","sectionCount":20,"blockCount":1409,"wordCount":30374};
